window.BARALHOS = window.BARALHOS || {};
window.BARALHOS['fr'] = {"versao":1,"idioma":"fr","curso":"fr-en","audiencia":"en","leva":"3906c001","total":577,"cards":[{"idioma":"fr","id":"fr-b001","tipo":"frase","fr":"Bonjour !","aceitasFr":["Bonjour.","Bonjour, madame.","Bonjour, monsieur."],"en":"Hello!","aceitasEn":["hello","good morning","good afternoon","good day"],"distratoresEn":["Good night!","See you tomorrow!","Welcome!","Good luck!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It works from morning until evening: good morning and good afternoon in one word. In France, saying «Bonjour» as you walk into a shop is close to mandatory.","requerTodas":[],"v":"4c50d50d"},{"idioma":"fr","id":"fr-b002","tipo":"frase","fr":"Bonsoir !","aceitasFr":["Bonsoir.","Bonsoir, madame.","Bonsoir, monsieur."],"en":"Good evening!","aceitasEn":["good evening","evening"],"distratoresEn":["Good morning!","Good afternoon!","See you tomorrow!","Have a good trip!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The greeting when you arrive in the evening. When someone goes to bed, French says «Bonne nuit» instead.","requerTodas":[],"v":"49b42210"},{"idioma":"fr","id":"fr-b003","tipo":"frase","fr":"Salut !","aceitasFr":["Salut.","Coucou !"],"en":"Hi!","aceitasEn":["hi","hey","hiya"],"distratoresEn":["Thanks!","Careful!","Congratulations!","Help!"],"nivel":"A1","tags":["primeiros passos","social","gíria"],"notaEn":"The casual hello among friends and colleagues; with strangers, use «Bonjour». It also works as a casual bye. The final «t» is silent.","requerTodas":[],"v":"123d5ee1"},{"idioma":"fr","id":"fr-b004","tipo":"frase","fr":"Au revoir !","aceitasFr":["Au revoir.","Au revoir, madame.","Au revoir, monsieur."],"en":"Goodbye!","aceitasEn":["goodbye","good bye","bye","bye bye"],"distratoresEn":["Welcome!","Thank you!","Congratulations!","Cheers!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The goodbye that works with anyone, at any time. Literally «until seeing again». «Au» sounds like «oh».","requerTodas":[],"v":"8d6af516"},{"idioma":"fr","id":"fr-b005","tipo":"frase","fr":"Merci !","aceitasFr":["Merci.","Merci bien !"],"en":"Thank you!","aceitasEn":["thank you","thanks"],"distratoresEn":["Please!","You're welcome!","Sorry!","Congratulations!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The stress falls at the end: «mehr-SEE», with the throaty French «r».","requerTodas":[],"v":"349d0e6c"},{"idioma":"fr","id":"fr-b006","tipo":"frase","fr":"Merci beaucoup !","aceitasFr":["Merci beaucoup.","Merci mille fois !"],"en":"Thank you very much!","aceitasEn":["thank you very much","thank you so much","thanks a lot","thanks so much","many thanks"],"distratoresEn":["Nice to meet you!","Very well done!","Of course, go ahead!","Everything's fine here!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Beaucoup» means a lot, and it goes after: «merci beaucoup», never «beaucoup merci». Say «boh-KOO».","requerTodas":[],"v":"419a49d1"},{"idioma":"fr","id":"fr-b007","tipo":"frase","fr":"De rien !","aceitasFr":["De rien.","Je vous en prie.","Je t'en prie.","Avec plaisir !"],"en":"You're welcome!","aceitasEn":["you are welcome","youre welcome","no problem","dont mention it","not at all","my pleasure"],"distratoresEn":["Once again!","Please!","Whatever!","Not bad!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «of nothing»: «rien» means nothing. More formal: «Je vous en prie».","requerTodas":[],"v":"3c158524"},{"idioma":"fr","id":"fr-b008","tipo":"frase","fr":"S'il vous plaît.","aceitasFr":["S'il te plaît.","SVP"],"en":"Please.","aceitasEn":["please"],"distratoresEn":["Excuse me.","Thank you.","Sorry.","See you."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «if it pleases you». With people you call «tu» (friends, family, children) it becomes «s'il te plaît». In writing: «SVP».","requerTodas":[],"v":"dad0a242"},{"idioma":"fr","id":"fr-b009","tipo":"frase","fr":"Excusez-moi.","aceitasFr":["Excuse-moi.","Pardon."],"en":"Excuse me.","aceitasEn":["excuse me","pardon me","sorry"],"distratoresEn":["Please.","Thank you.","See you later.","Welcome."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"To get someone's attention, get past people, or apologize for something small. With «tu»: «Excuse-moi». «Pardon» does the same job.","requerTodas":[],"v":"446da295"},{"idioma":"fr","id":"fr-b010","tipo":"frase","fr":"Je suis désolé.","aceitasFr":["Je suis désolée.","Désolé.","Désolée."],"en":"I'm sorry.","aceitasEn":["i am sorry","sorry","im so sorry","i am so sorry"],"distratoresEn":["I'm tired.","I'm late.","Nice to meet you.","I don't know."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"A woman writes «désolée»; it sounds the same. It is the everyday apology, not a dramatic word.","requerTodas":[],"v":"7ca213a2"},{"idioma":"fr","id":"fr-b011","tipo":"frase","fr":"Oui, bien sûr.","aceitasFr":["Bien sûr.","Oui, bien sûr !","Oui, évidemment."],"en":"Yes, of course.","aceitasEn":["yes of course","of course","sure","yes sure","yes certainly","certainly"],"distratoresEn":["No, thank you.","Yes, maybe.","No, never.","Yes, later."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Bien sûr» means of course; literally «well sure». «Oui» sounds like «wee».","requerTodas":[],"v":"fc252c17"},{"idioma":"fr","id":"fr-b012","tipo":"frase","fr":"Non, merci.","aceitasFr":["Non merci."],"en":"No, thank you.","aceitasEn":["no thank you","no thanks"],"distratoresEn":["Yes, please.","No, never.","Yes, thank you.","Not now."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"The polite refusal, to a waiter or anyone offering something. To accept: «Oui, merci» or «Oui, s'il vous plaît».","requerTodas":[],"v":"76959b07"},{"idioma":"fr","id":"fr-b013","tipo":"frase","fr":"Je ne comprends pas.","aceitasFr":["Je comprends pas."],"en":"I don't understand.","aceitasEn":["i do not understand","i dont understand","i dont get it"],"distratoresEn":["I don't agree.","I don't remember.","I can't.","I don't want to."],"nivel":"A1","tags":["primeiros passos","gramática"],"notaEn":"French negation has two parts: «ne» before the verb and «pas» after it. In speech the «ne» often drops («Je comprends pas»), but «pas» never does.","requerTodas":[],"v":"5ab567d0"},{"idioma":"fr","id":"fr-b014","tipo":"frase","fr":"Vous pouvez répéter, s'il vous plaît ?","aceitasFr":["Pouvez-vous répéter, s'il vous plaît ?","Tu peux répéter, s'il te plaît ?","Vous pouvez répéter ?"],"en":"Could you repeat that, please?","aceitasEn":["could you repeat that please","can you repeat that please","could you repeat please","can you say that again please","could you say that again please"],"distratoresEn":["Could you wait a moment, please?","Could you come in, please?","Could you write it down, please?","Could you sit down, please?"],"nivel":"A1","tags":["primeiros passos","escola"],"notaEn":"«Vous» is the polite you, for one person, and also the plural you. With friends: «Tu peux répéter ?».","requerTodas":[],"v":"edec3654"},{"idioma":"fr","id":"fr-b015","tipo":"frase","fr":"Vous parlez anglais ?","aceitasFr":["Parlez-vous anglais ?","Tu parles anglais ?","Est-ce que vous parlez anglais ?"],"en":"Do you speak English?","aceitasEn":["do you speak english","you speak english","can you speak english"],"distratoresEn":["Do you study English?","Do you understand English?","Do you teach English?","Do you like English?"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"Languages are lowercase in French: «anglais», «français». Asking with just a rising tone, no inversion, is the everyday way.","requerTodas":[],"v":"777691a9"},{"idioma":"fr","id":"fr-b016","tipo":"frase","fr":"Je parle un peu français.","aceitasFr":["Je parle un petit peu français.","Je parle un peu le français."],"en":"I speak a little French.","aceitasEn":["i speak a little french","i speak a bit of french","i speak some french"],"distratoresEn":["I speak French very well.","I understand a little French.","I study a little French.","I speak a little English."],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"«Un peu» is a little; «parler français» needs no article in this phrase.","requerTodas":[],"v":"b75ba417"},{"idioma":"fr","id":"fr-b017","tipo":"frase","fr":"Parlez plus lentement, s'il vous plaît.","aceitasFr":["Parle plus lentement, s'il te plaît.","Plus lentement, s'il vous plaît.","Vous pouvez parler plus lentement ?"],"en":"Please speak more slowly.","aceitasEn":["please speak more slowly","speak more slowly please","speak slower please","please speak slower","could you speak more slowly","slower please"],"distratoresEn":["Please speak louder.","Please speak more quietly.","Please walk more slowly.","Please write more slowly."],"nivel":"A1","tags":["primeiros passos","escola"],"notaEn":"«Parlez» is the «vous» imperative. «-ment» makes adverbs, like English «-ly»: «lentement», slowly.","requerTodas":[],"v":"6fc86399"},{"idioma":"fr","id":"fr-b018","tipo":"frase","fr":"Comment vous appelez-vous ?","aceitasFr":["Comment tu t'appelles ?","Tu t'appelles comment ?","Vous vous appelez comment ?","Quel est votre nom ?"],"en":"What's your name?","aceitasEn":["what is your name","whats your name","may i have your name"],"distratoresEn":["Where are you from?","Where do you live?","How old are you?","How are you doing?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «how do you call yourself?»: the verb is «s'appeler», to be called. Casually: «Tu t'appelles comment ?».","requerTodas":[],"v":"01c4665d"},{"idioma":"fr","id":"fr-b019","tipo":"frase","fr":"Je m'appelle Ana.","aceitasFr":["Moi, c'est Ana.","Mon nom est Ana.","Je suis Ana."],"en":"My name is Ana.","aceitasEn":["my name is ana","im ana","i am ana","my names ana"],"distratoresEn":["I live with Ana.","I'm calling Ana.","I'm Ana's friend.","Ana called me."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Je m'appelle» is literally «I call myself». Without the «m'», «J'appelle Ana» means I'm calling Ana. You also hear «Moi, c'est Ana».","requerTodas":[],"v":"51c43a18"},{"idioma":"fr","id":"fr-b020","tipo":"frase","fr":"Enchanté.","aceitasFr":["Enchantée.","Enchanté de vous connaître.","Ravi de vous rencontrer."],"en":"Nice to meet you.","aceitasEn":["nice to meet you","pleased to meet you","good to meet you","nice meeting you"],"distratoresEn":["Very tired.","Welcome.","See you soon.","Excuse me."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"A woman writes «enchantée»; it sounds the same. It is what you say when introduced; among young people «Salut» is enough.","requerTodas":[],"v":"99f1bf28"},{"idioma":"fr","id":"fr-b021","tipo":"frase","fr":"Ça va ?","aceitasFr":["Comment ça va ?","Ça va bien ?"],"en":"How's it going?","aceitasEn":["hows it going","how is it going","how are things"],"distratoresEn":["Is everything ready?","Are you leaving?","Who is it?","Where is it?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It is both the question and the answer: «— Ça va ? — Ça va.» Literally «it goes». Casual; with strangers, «Comment allez-vous ?».","requerTodas":[],"v":"2d61f16c"},{"idioma":"fr","id":"fr-b022","tipo":"frase","fr":"Ça va bien, merci.","aceitasFr":["Ça va, merci.","Très bien, merci.","Bien, merci.","Je vais bien, merci."],"en":"I'm fine, thanks.","aceitasEn":["im fine thanks","i am fine thanks","im fine thank you","i am fine thank you","fine thanks","fine thank you","im good thanks","good thanks","im well thanks"],"distratoresEn":["All set, thanks.","So-so, thanks.","I'm fine, and you?","I'm tired, thanks."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Ça va» is also the answer. Great: «Ça va très bien». So-so: «Comme ci, comme ça».","requerTodas":[],"v":"4c1fab22"},{"idioma":"fr","id":"fr-b023","tipo":"frase","fr":"Comment allez-vous ?","aceitasFr":["Vous allez bien ?","Comment vas-tu ?"],"en":"How are you?","aceitasEn":["how are you","how are you doing","how do you do"],"distratoresEn":["What is your name?","Where do you live?","Where are you going?","How did you get here?"],"nivel":"A1","tags":["primeiros passos","social","formal"],"notaEn":"The polite form, for people you call «vous». The verb is «aller», to go: «Où allez-vous ?» would be where are you going. Answer: «Je vais bien, merci».","requerTodas":[],"v":"6c0d7dfb"},{"idioma":"fr","id":"fr-b024","tipo":"frase","fr":"Et vous ?","aceitasFr":["Et toi ?","Et vous-même ?"],"en":"And you?","aceitasEn":["and you","what about you","how about you","and yourself"],"distratoresEn":["And then?","And so?","And now?","And why?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It bounces the question back: «— Ça va ? — Ça va, et toi ?». «Vous» is polite or plural; «toi» is for friends.","requerTodas":[],"v":"c60e1dbc"},{"idioma":"fr","id":"fr-b025","tipo":"frase","fr":"Où sont les toilettes ?","aceitasFr":["Où sont les toilettes, s'il vous plaît ?","Les toilettes, s'il vous plaît ?","Où se trouvent les toilettes ?"],"en":"Where is the restroom?","aceitasEn":["where is the restroom","wheres the restroom","where is the bathroom","wheres the bathroom","where are the restrooms","where is the toilet"],"distratoresEn":["Where is the exit?","Where is the kitchen?","Where is the bedroom?","Where is the elevator?"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"The French word is always plural, «les toilettes», even for a single restroom. «Où» with the accent means where; «ou» without it means or.","requerTodas":[],"v":"73f27ec0"},{"idioma":"fr","id":"fr-b026","tipo":"frase","fr":"C'est combien ?","aceitasFr":["Ça coûte combien ?","Combien ça coûte ?","Combien ?"],"en":"How much is it?","aceitasEn":["how much is it","how much","how much does it cost","how much is this","how much does this cost"],"distratoresEn":["How much is left?","How long does it take?","When does it open?","Where is it?"],"nivel":"A1","tags":["primeiros passos","compras"],"notaEn":"Literally «it's how much?», with «combien» at the end, which is how people ask in conversation.","requerTodas":[],"v":"d5589339"},{"idioma":"fr","id":"fr-b027","tipo":"frase","fr":"L'addition, s'il vous plaît.","aceitasFr":["L'addition, s'il te plaît.","L'addition !"],"en":"The check, please.","aceitasEn":["the check please","check please","can i have the check please","could we have the check please"],"regionaisEn":{"The bill, please.":"no Reino Unido"},"distratoresEn":["The menu, please.","Some water, please.","My change, please.","A table, please."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"At a restaurant the check is «l'addition», literally the sum. A bank account is «le compte».","requerTodas":[],"v":"a9d76f97"},{"idioma":"fr","id":"fr-b028","tipo":"frase","fr":"Je voudrais un café, s'il vous plaît.","aceitasFr":["Un café, s'il vous plaît.","Je voudrais un café.","Je prendrais un café, s'il vous plaît."],"en":"I'd like a coffee, please.","aceitasEn":["id like a coffee please","i would like a coffee please","a coffee please","can i have a coffee please","could i have a coffee please","coffee please"],"distratoresEn":["I'd like a tea, please.","I had a coffee, thanks.","I'll pay for the coffee.","I'd like some water, please."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"«Je voudrais» is the conditional of «vouloir», to want: the polite request, like I'd like. «Je veux» sounds blunt. In France «un café» is an espresso.","requerTodas":[],"v":"a63f101d"},{"idioma":"fr","id":"fr-b029","tipo":"frase","fr":"Une table pour deux, s'il vous plaît.","aceitasFr":["Une table pour deux personnes, s'il vous plaît.","Une table pour deux."],"en":"A table for two, please.","aceitasEn":["a table for two please","table for two please","a table for two","a table for two people please"],"distratoresEn":["A table for three, please.","A chair for two, please.","A room for two, please.","A table by the window, please."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"«La table» is feminine. The «x» in «deux» is silent.","requerTodas":[],"v":"9ab6a148"},{"idioma":"fr","id":"fr-b030","tipo":"frase","fr":"Où est la gare ?","aceitasFr":["Où se trouve la gare ?","La gare, c'est où ?","Où est la gare, s'il vous plaît ?"],"en":"Where is the train station?","aceitasEn":["where is the train station","wheres the train station","where is the station","wheres the station","where is the railway station"],"distratoresEn":["Where is the hotel?","Where is the beach?","Where is the bus stop?","Where is the garage?"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"«La gare» is the train station; a subway station is «la station». A garage is «le garage».","requerTodas":[],"v":"5becc440"},{"idioma":"fr","id":"fr-b031","tipo":"frase","fr":"Je suis perdu.","aceitasFr":["Je suis perdue."],"en":"I'm lost.","aceitasEn":["im lost","i am lost"],"distratoresEn":["I'm tired.","I'm late.","I'm ready.","I'm hungry."],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"A woman writes «perdue»; it sounds the same.","requerTodas":[],"v":"c7484a34"},{"idioma":"fr","id":"fr-b032","tipo":"frase","fr":"J'ai faim.","aceitasFr":["J'ai très faim."],"en":"I'm hungry.","aceitasEn":["im hungry","i am hungry"],"distratoresEn":["I'm thirsty.","I'm cold.","I'm sleepy.","I'm in a hurry."],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"French «has» hunger: «avoir faim», literally to have hunger. Likewise «avoir soif» (thirsty), «avoir froid» (cold), «avoir sommeil» (sleepy).","requerTodas":[],"v":"7207b812"},{"idioma":"fr","id":"fr-b033","tipo":"frase","fr":"Je ne sais pas.","aceitasFr":["Je sais pas."],"en":"I don't know.","aceitasEn":["i dont know","i do not know","no idea","dunno"],"distratoresEn":["I can't.","I don't want to.","I don't remember.","I don't like it."],"nivel":"A1","tags":["primeiros passos","gramática"],"notaEn":"«Savoir» is to know: «je sais», I know. In speech the «ne» drops: «Je sais pas».","requerTodas":[],"v":"52c3a0e2"},{"idioma":"fr","id":"fr-b034","tipo":"frase","fr":"Aidez-moi, s'il vous plaît !","aceitasFr":["Aide-moi, s'il te plaît !","Vous pouvez m'aider, s'il vous plaît ?","Aidez-moi !"],"en":"Please help me!","aceitasEn":["please help me","help me please","can you help me please","could you help me please","help me"],"distratoresEn":["Please wait for me!","Please call me!","Please forgive me!","Please listen to me!"],"nivel":"A1","tags":["primeiros passos","viagem"],"notaEn":"«Aider» is to help. With «tu»: «Aide-moi». In an emergency, shout «Au secours !».","requerTodas":[],"v":"ad337e09"},{"idioma":"fr","id":"fr-b035","tipo":"frase","fr":"Vous venez d'où ?","aceitasFr":["Tu viens d'où ?","D'où venez-vous ?","Vous êtes d'où ?"],"en":"Where are you from?","aceitasEn":["where are you from","where do you come from","where you from"],"distratoresEn":["Where do you live?","Where are you going?","Where have you been?","Where do you work?"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Literally «you come from where?»: «venir» is to come. In conversation the question word goes at the end.","requerTodas":[],"v":"a1f04bb2"},{"idioma":"fr","id":"fr-b036","tipo":"frase","fr":"Je viens du Brésil.","aceitasFr":["Je suis du Brésil.","Je suis brésilien.","Je suis brésilienne."],"en":"I'm from Brazil.","aceitasEn":["im from brazil","i am from brazil","i come from brazil","im brazilian","i am brazilian"],"distratoresEn":["I live in Brazil.","I'm going to Brazil.","I'm back from Brazil.","I like Brazil."],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"Masculine countries take «du»: «du Brésil», «du Canada»; feminine ones take «de»: «de France», «d'Angleterre». «Je viens» means I come.","requerTodas":[],"v":"1edad4f2"},{"idioma":"fr","id":"fr-b037","tipo":"frase","fr":"Quelle heure est-il ?","aceitasFr":["Il est quelle heure ?","Vous avez l'heure ?","Tu as l'heure ?"],"en":"What time is it?","aceitasEn":["what time is it","whats the time","what is the time","do you have the time"],"distratoresEn":["How old are you?","What day is it today?","What time does it open?","How much time is left?"],"nivel":"A1","tags":["primeiros passos","cotidiano"],"notaEn":"Literally «what hour is it?». The answer uses the same frame: «Il est trois heures», it's three o'clock.","requerTodas":[],"v":"b23dfd08"},{"idioma":"fr","id":"fr-b038","tipo":"frase","fr":"À bientôt !","aceitasFr":["À plus tard !","À la prochaine !","À plus !"],"en":"See you soon!","aceitasEn":["see you soon","see you","see you later","talk soon"],"distratoresEn":["See you tomorrow!","Welcome!","Have a good trip!","Enjoy your meal!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"«Bientôt» means soon. For tomorrow: «À demain !». Among friends, the short «À plus !» (the «s» is pronounced).","requerTodas":[],"v":"8ea86a8a"},{"idioma":"fr","id":"fr-b039","tipo":"frase","fr":"Bon appétit !","aceitasFr":["Bon appétit."],"en":"Enjoy your meal!","aceitasEn":["enjoy your meal","enjoy","bon appetit"],"distratoresEn":["Have a nice trip!","Good luck!","Cheers!","Sleep well!"],"nivel":"A1","tags":["primeiros passos","comida"],"notaEn":"Said before eating; English borrowed it as is. The final «t» is silent.","requerTodas":[],"v":"15dea5d1"},{"idioma":"fr","id":"fr-b040","tipo":"frase","fr":"Bonne journée !","aceitasFr":["Bonne journée.","Passez une bonne journée !","Bonne journée à vous !"],"en":"Have a nice day!","aceitasEn":["have a nice day","have a good day","have a great day","enjoy your day"],"distratoresEn":["Have a nice evening!","Have a nice trip!","Have a nice weekend!","Have a nice lunch!"],"nivel":"A1","tags":["primeiros passos","social"],"notaEn":"It's a goodbye, not a greeting: «Bonjour» when you arrive, «Bonne journée» when you leave. In the evening, «Bonne soirée».","requerTodas":[],"v":"da6a32ad"},{"idioma":"fr","id":"fr-p001","tipo":"palavra","fr":"être","en":"to be","aceitasEn":["to be","be"],"distratoresEn":["to have","to do","to stay","to give"],"nivel":"A1","tags":["verbo","gramática"],"notaEn":"Irregular: je suis, tu es, il est, nous sommes, vous êtes, ils sont. It is also the helper verb of some past tenses: «je suis allé», I went.","v":"e2b9cdca"},{"idioma":"fr","id":"fr-p002","tipo":"palavra","fr":"avoir","en":"to have","aceitasEn":["to have","have","to have got"],"distratoresEn":["to hear","to owe","to be worth","to know"],"nivel":"A1","tags":["verbo","gramática"],"notaEn":"French uses it for age and sensations: «j'ai vingt ans» (I'm twenty), «j'ai faim» (I'm hungry). Forms: j'ai, tu as, il a, nous avons, vous avez, ils ont.","v":"a7406585"},{"idioma":"fr","id":"fr-p003","tipo":"palavra","fr":"aller","en":"to go","aceitasEn":["to go","go"],"distratoresEn":["to rent","to stay","to take","to look"],"nivel":"A1","tags":["verbo"],"notaEn":"Very irregular: je vais, tu vas, il va, nous allons, vous allez, ils vont. It is in «Ça va ?» and in the near future: «je vais manger», I'm going to eat.","v":"6fc8aa32"},{"idioma":"fr","id":"fr-p004","tipo":"palavra","fr":"faire","en":"to do / to make","aceitasEn":["to do","to make","do","make"],"distratoresEn":["to speak / to say","to hurt / to injure","to boil / to heat","to close / to shut"],"nivel":"A1","tags":["verbo"],"notaEn":"Both to do and to make, and also the weather verb: «il fait beau» (it's nice out), «il fait froid» (it's cold). Forms: je fais, nous faisons, vous faites, ils font.","v":"f0f41628"},{"idioma":"fr","id":"fr-p005","tipo":"palavra","fr":"dire","en":"to say","aceitasEn":["to say","say","to tell","tell"],"distratoresEn":["to drive","to last","to leave","to owe"],"nivel":"A1","tags":["verbo"],"notaEn":"To say or tell something; to speak a language, or to talk, is «parler». Forms: je dis, nous disons, vous dites, ils disent.","v":"fe7eef1f"},{"idioma":"fr","id":"fr-p006","tipo":"palavra","fr":"pouvoir","en":"can / to be able to","aceitasEn":["can","to be able to","be able to","to be able"],"distratoresEn":["must / to have to","to be worth / to cost","to put / to place","to know / to know how"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je peux, tu peux, il peut, nous pouvons, vous pouvez, ils peuvent. To ask permission: «Je peux… ?», or formally «Puis-je… ?».","v":"1c72f625"},{"idioma":"fr","id":"fr-p007","tipo":"palavra","fr":"vouloir","en":"to want","aceitasEn":["to want","want","to wish"],"distratoresEn":["to fly","to be worth","to return","to live"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je veux, tu veux, il veut, nous voulons, ils veulent. Polite requests use the conditional: «je voudrais», I'd like. «Vouloir dire» means to mean.","v":"b3c5e3ae"},{"idioma":"fr","id":"fr-p008","tipo":"palavra","fr":"savoir","en":"to know","aceitasEn":["to know","know","to know how to"],"distratoresEn":["to meet","to save","to serve","to follow"],"nivel":"A1","tags":["verbo"],"notaEn":"To know a fact, or how to do something: «je sais nager», I can swim. Knowing a person or a place is another verb, «connaître». Forms: je sais, nous savons, ils savent.","v":"92ac684b"},{"idioma":"fr","id":"fr-p009","tipo":"palavra","fr":"venir","en":"to come","aceitasEn":["to come","come"],"distratoresEn":["to sell","to win","to see","to dress"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je viens, nous venons, ils viennent. «Venir de» + infinitive means to have just: «je viens de manger», I've just eaten.","v":"2f117e21"},{"idioma":"fr","id":"fr-p010","tipo":"palavra","fr":"voir","en":"to see","aceitasEn":["to see","see"],"distratoresEn":["to fly","to come","to be worth","to dress"],"nivel":"A1","tags":["verbo"],"notaEn":"Forms: je vois, nous voyons, ils voient. To look at or watch is «regarder». «On verra», we'll see.","v":"b7d5b90d"},{"idioma":"fr","id":"fr-p011","tipo":"palavra","fr":"prendre","en":"to take","aceitasEn":["to take","take","to grab"],"distratoresEn":["to learn","to lose","to ask for","to lend"],"nivel":"A1","tags":["verbo","falso-amigo"],"notaEn":"To take: «prendre le bus», to take the bus; «prendre un café», to have a coffee. With «ap-», «apprendre» means to learn. Forms: je prends, nous prenons, ils prennent.","v":"786aaff8"},{"idioma":"fr","id":"fr-p012","tipo":"palavra","fr":"parler","en":"to speak","aceitasEn":["to speak","speak","to talk","talk"],"distratoresEn":["to stop","to leave","to pay","to jump"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb, the pattern most verbs follow: je parle, tu parles, il parle (all three sound the same), nous parlons, vous parlez, ils parlent.","v":"31194517"},{"idioma":"fr","id":"fr-p013","tipo":"palavra","fr":"manger","en":"to eat","aceitasEn":["to eat","eat"],"distratoresEn":["to send","to move","to change","to bite"],"nivel":"A1","tags":["verbo","comida"],"notaEn":"Regular «-er» verb, with an extra «e» in «nous mangeons» to keep the soft «g». A meal is «un repas».","v":"924863aa"},{"idioma":"fr","id":"fr-p014","tipo":"palavra","fr":"boire","en":"to drink","aceitasEn":["to drink","drink"],"distratoresEn":["to beat","to kiss","to play","to look for"],"nivel":"A1","tags":["verbo","comida"],"notaEn":"Irregular: je bois, nous buvons, ils boivent; past participle «bu». A drink is «une boisson».","v":"af44509e"},{"idioma":"fr","id":"fr-p015","tipo":"palavra","fr":"aimer","en":"to love / to like","aceitasEn":["to love","to like"],"distratoresEn":["to help / to support","to accept / to admit","to find / to discover","to hate / to detest"],"nivel":"A1","tags":["verbo","família"],"notaEn":"Both to love and to like: «je t'aime» (I love you), «j'aime le café» (I like coffee). Things you like take the article: «j'aime le café», not «j'aime café».","v":"d136d30f"},{"idioma":"fr","id":"fr-p016","tipo":"palavra","fr":"habiter","en":"to live (somewhere)","aceitasEn":["to live","live","to reside","reside","to live in"],"distratoresEn":["to hesitate (to doubt)","to inherit (property)","to host (a guest)","to shelter (from cold)"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"To live somewhere: «j'habite à Paris», I live in Paris. The «h» is silent, hence the apostrophe: «j'habite». «Vivre» is to live in the broader sense.","v":"ff2f69e2"},{"idioma":"fr","id":"fr-p017","tipo":"palavra","fr":"travailler","en":"to work","aceitasEn":["to work","work"],"distratoresEn":["to block","to treat","to travel","to swap"],"nivel":"A1","tags":["verbo","trabalho"],"notaEn":"Regular «-er» verb: je travaille, nous travaillons. The «-ill-» sounds like «y»: «tra-va-YAY». Work, the noun, is «le travail».","v":"ab9766f3"},{"idioma":"fr","id":"fr-p018","tipo":"palavra","fr":"attendre","en":"to wait","aceitasEn":["to wait","wait","to wait for","wait for"],"distratoresEn":["to attend","to understand","to extend","to tend"],"nivel":"A1","tags":["verbo","falso-amigo"],"notaEn":"Not to attend: it means to wait for, with no preposition: «j'attends le bus», I'm waiting for the bus. To attend is «assister à».","v":"8639d0d0"},{"idioma":"fr","id":"fr-p019","tipo":"palavra","fr":"le jour","en":"the day","aceitasEn":["the day","day"],"distratoresEn":["the game","the newspaper","the month","the year"],"nivel":"A1","tags":["cotidiano"],"notaEn":"A day on the calendar. The day as you live it, the daytime, is «la journée»: «bonne journée». «Bonjour» is literally good day.","v":"e87a7825"},{"idioma":"fr","id":"fr-p020","tipo":"palavra","fr":"la maison","en":"the house","aceitasEn":["the house","house","the home","home"],"distratoresEn":["the table","the mansion","the dough","the apple"],"nivel":"A1","tags":["casa"],"notaEn":"«À la maison» means at home: «je suis à la maison». «Chez moi» also means at my place.","v":"bde2f8bf"},{"idioma":"fr","id":"fr-p021","tipo":"palavra","fr":"l'homme","aceitasFr":["un homme"],"en":"the man","aceitasEn":["the man","man"],"distratoresEn":["the name","the shoulder","the guest","the anthem"],"nivel":"A1","tags":["família"],"notaEn":"Masculine, with the article shortened before the silent «h»: «l'homme», «un homme».","v":"510c8580"},{"idioma":"fr","id":"fr-p022","tipo":"palavra","fr":"la femme","en":"the woman","aceitasEn":["the woman","woman","the wife","wife"],"distratoresEn":["the hunger","the daughter","the company","the shape"],"nivel":"A1","tags":["família"],"notaEn":"Also wife: «ma femme», my wife. Pronounced «fam», with an «a».","v":"ff3b66a3"},{"idioma":"fr","id":"fr-p023","tipo":"palavra","fr":"l'enfant","aceitasFr":["un enfant","une enfant"],"en":"the child","aceitasEn":["the child","child","the kid","kid"],"distratoresEn":["the childhood","the patient","the godson","the nephew"],"nivel":"A1","tags":["família"],"notaEn":"For a boy or a girl: «un enfant», «une enfant». «Les enfants» also means your children: «j'ai deux enfants». Childhood is «l'enfance».","v":"ed14078b"},{"idioma":"fr","id":"fr-p024","tipo":"palavra","fr":"l'ami","aceitasFr":["l'amie","un ami","une amie"],"en":"the friend","aceitasEn":["the friend","friend"],"distratoresEn":["the love","the lunch","the student","the neighbor"],"nivel":"A1","tags":["família","social"],"notaEn":"A female friend is «l'amie»; it sounds the same. Boyfriend and girlfriend are «le petit ami» and «la petite amie».","v":"43fe5878"},{"idioma":"fr","id":"fr-p025","tipo":"palavra","fr":"le temps","en":"time / weather","aceitasEn":["time","the time","weather","the weather"],"distratoresEn":["temple / church","seasoning / spice","ceiling / roof","topic / theme"],"nivel":"A1","tags":["cotidiano","natureza"],"notaEn":"Both time and weather: «je n'ai pas le temps» (I don't have time), «quel temps fait-il ?» (what's the weather like?). The «p» and «s» are silent.","v":"e46e6345"},{"idioma":"fr","id":"fr-p026","tipo":"palavra","fr":"l'eau","aceitasFr":["une eau"],"en":"the water","aceitasEn":["the water","water"],"distratoresEn":["the wave","the bird","the island","the grape"],"nivel":"A1","tags":["comida","natureza"],"notaEn":"Feminine: «une eau», «l'eau minérale». Three letters for one vowel sound: «oh».","v":"af06924e"},{"idioma":"fr","id":"fr-p027","tipo":"palavra","fr":"le pain","en":"the bread","aceitasEn":["the bread","bread"],"distratoresEn":["the cloth","the father","the foot","the pine"],"nivel":"A1","tags":["comida"],"notaEn":"«Ain» is a nasal vowel, with no «n» sound at the end. A baguette is «une baguette»; the baker is «le boulanger», in the «boulangerie».","v":"d1e9e55a"},{"idioma":"fr","id":"fr-p028","tipo":"palavra","fr":"la ville","en":"the city","aceitasEn":["the city","city","the town","town"],"distratoresEn":["the village","the life","the candle","the track"],"nivel":"A1","tags":["cidade","falso-amigo"],"notaEn":"A city or town of any size. A village is «le village»; a big country house is «une villa». «En ville», downtown.","v":"a2347337"},{"idioma":"fr","id":"fr-p029","tipo":"palavra","fr":"le travail","en":"work","aceitasEn":["work","the work","job","the job"],"distratoresEn":["clover","pillow","journey","theater"],"nivel":"A1","tags":["trabalho"],"notaEn":"Work and job: «je vais au travail», I'm going to work. Irregular plural: «les travaux», roadworks or renovations.","v":"c12a261e"},{"idioma":"fr","id":"fr-p030","tipo":"palavra","fr":"la nuit","en":"the night","aceitasEn":["the night","night"],"distratoresEn":["the cloud","the snow","the note","the nape"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Bonne nuit» is what you say at bedtime; arriving in the evening, it's «Bonsoir». The evening, after work, is «le soir».","v":"46f21d60"},{"idioma":"fr","id":"fr-p031","tipo":"palavra","fr":"l'année","aceitasFr":["une année"],"en":"the year","aceitasEn":["the year","year"],"distratoresEn":["the ring","the owner","the nest","the month"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine. French has two words for year: «l'an» for counting («j'ai vingt ans», I'm twenty) and «l'année» for the year as lived («bonne année !», happy new year).","v":"a8bbbecc"},{"idioma":"fr","id":"fr-p032","tipo":"palavra","fr":"la rue","en":"the street","aceitasEn":["the street","street"],"distratoresEn":["the wheel","the clothes","the wrinkle","the ruler"],"nivel":"A1","tags":["cidade"],"notaEn":"A city street; a road out of town is «la route». «Dans la rue», in the street.","v":"0e832e13"},{"idioma":"fr","id":"fr-p033","tipo":"palavra","fr":"le livre","en":"the book","aceitasEn":["the book","book"],"distratoresEn":["the lily","the liter","the lip","the canvas"],"nivel":"A1","tags":["escola"],"notaEn":"Masculine. Feminine «la livre» is the pound (money or weight). Free is «libre».","v":"135ab3cb"},{"idioma":"fr","id":"fr-p034","tipo":"palavra","fr":"la voiture","en":"the car","aceitasEn":["the car","car","the automobile"],"distratoresEn":["the bus","the truck","the train","the flight"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"Feminine in French: «une voiture», «ma voiture». To drive is «conduire».","v":"74004096"},{"idioma":"fr","id":"fr-p035","tipo":"palavra","fr":"l'argent","en":"money","aceitasEn":["money","the money","silver"],"distratoresEn":["gold","argument","change","card"],"nivel":"A1","tags":["compras","economia"],"notaEn":"Masculine. It means money and also silver, the metal.","v":"a03959da"},{"idioma":"fr","id":"fr-p036","tipo":"palavra","fr":"bon","aceitasFr":["bonne"],"en":"good","aceitasEn":["good","tasty"],"distratoresEn":["pretty","cheap","brief","brave"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «bonne». For food it means tasty: «c'est bon !». The adverb, well, is «bien».","v":"e4bdf42a"},{"idioma":"fr","id":"fr-p037","tipo":"palavra","fr":"grand","aceitasFr":["grande"],"en":"big","aceitasEn":["big","large","tall"],"distratoresEn":["thick","fat","free","serious"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «grande». For people it also means tall: «il est grand», he is tall. The «d» is only heard in the feminine.","v":"897161a1"},{"idioma":"fr","id":"fr-p038","tipo":"palavra","fr":"petit","aceitasFr":["petite"],"en":"small","aceitasEn":["small","little","short"],"distratoresEn":["few","heavy","slow","poor"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «petite». Before nouns it can sound affectionate: «un petit café». Breakfast is «le petit déjeuner».","v":"4149551f"},{"idioma":"fr","id":"fr-p039","tipo":"palavra","fr":"nouveau","aceitasFr":["nouvelle","nouvel"],"en":"new","aceitasEn":["new"],"distratoresEn":["nine","engaged","cloudy","noble"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Three forms: «nouveau»; «nouvel» before a vowel («un nouvel ami»); feminine «nouvelle». Brand-new, unused, is «neuf».","v":"9350aae7"},{"idioma":"fr","id":"fr-p040","tipo":"palavra","fr":"beau","aceitasFr":["belle","bel"],"en":"beautiful","aceitasEn":["beautiful","pretty","handsome","lovely"],"distratoresEn":["good","short","cheap","brave"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «belle»; before a vowel, «bel» («un bel homme»). Also nice weather: «il fait beau», it's a lovely day.","v":"15edc663"},{"idioma":"fr","id":"fr-p041","tipo":"palavra","fr":"vieux","aceitasFr":["vieille","vieil"],"en":"old","aceitasEn":["old","elderly","aged"],"distratoresEn":["empty","widowed","alive","brave"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «vieille»; before a vowel, «vieil» («un vieil ami», an old friend). For people, «âgé» (elderly) is more polite.","v":"eaf559c6"},{"idioma":"fr","id":"fr-p042","tipo":"palavra","fr":"content","aceitasFr":["contente"],"en":"happy","aceitasEn":["happy","glad","pleased","content"],"distratoresEn":["tired","known","restrained","hot"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Feminine «contente». With «de»: «je suis content de te voir», I'm glad to see you.","v":"09fc7831"},{"idioma":"fr","id":"fr-p043","tipo":"palavra","fr":"très","en":"very","aceitasEn":["very","really"],"distratoresEn":["three","behind","late","so much"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Goes before adjectives and adverbs: «très bien», «très grand». The number three is «trois».","v":"4dc405f6"},{"idioma":"fr","id":"fr-p044","tipo":"palavra","fr":"bien","en":"well","aceitasEn":["well","fine"],"distratoresEn":["soon","badly","far","early"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The adverb: «je vais bien», I'm well. The adjective is «bon»: «un bon livre». With «c'est» it praises: «c'est bien», that's good.","v":"fd01d39d"},{"idioma":"fr","id":"fr-p045","tipo":"palavra","fr":"aussi","en":"also","aceitasEn":["also","too","as well"],"distratoresEn":["like this","still","then","only"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Also, too: «moi aussi», me too. In comparisons it means as: «aussi grand que moi», as tall as me.","v":"194f7966"},{"idioma":"fr","id":"fr-p046","tipo":"palavra","fr":"toujours","en":"always / still","aceitasEn":["always","still"],"distratoresEn":["never / ever","sometimes / rarely","today / now","afterwards / finally"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Always, and also still: «il habite toujours ici», he still lives here. It comes from «tous les jours», every day.","v":"bb5b9bed"},{"idioma":"fr","id":"fr-p047","tipo":"palavra","fr":"maintenant","en":"now","aceitasEn":["now","right now"],"distratoresEn":["tomorrow","before","afterwards","yesterday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Now. Right away is «tout de suite».","v":"107fbbd9"},{"idioma":"fr","id":"fr-p048","tipo":"palavra","fr":"ici","en":"here","aceitasEn":["here"],"distratoresEn":["there","like this","over there","nearby"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Here. In conversation French also uses «là» this way: «je suis là», I'm here.","v":"9e8a712d"},{"idioma":"fr","id":"fr-p049","tipo":"palavra","fr":"aujourd'hui","en":"today","aceitasEn":["today"],"distratoresEn":["yesterday","tomorrow","now","later"],"nivel":"A1","tags":["cotidiano"],"notaEn":"One word, with an apostrophe. Yesterday is «hier»; tomorrow, «demain».","v":"a48d791b"},{"idioma":"fr","id":"fr-p050","tipo":"palavra","fr":"déjà","en":"already","aceitasEn":["already","yet","ever"],"distratoresEn":["still","afterwards","soon","before"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Already: «j'ai déjà mangé», I've already eaten. In questions it means ever: «tu es déjà allé à Paris ?», have you ever been to Paris?","v":"3c6a193b"},{"idioma":"fr","id":"fr-u001","tipo":"frase","requer":"fr-p001","fr":"Elle est très contente.","en":"She's very happy.","aceitasEn":["shes very happy","she is very happy","shes really happy","she is really happy","shes very glad","she is very pleased"],"distratoresEn":["She seems very happy.","She gets very happy.","She's still very happy.","She used to be very happy."],"nivel":"A1","tags":["gramática","social"],"notaEn":"«Est» is the «il»/«elle» form of «être»; the «st» is silent, so it sounds like «et» (and). The adjective agrees: «contente», with an «e», because she is the subject.","requerTodas":["fr-p001","fr-p043","fr-p042"],"v":"5c05a823"},{"idioma":"fr","id":"fr-u002","tipo":"frase","requer":"fr-p001","fr":"Je suis à la maison.","aceitasFr":["Je suis chez moi."],"en":"I'm at home.","aceitasEn":["im at home","i am at home","im home","i am home"],"distratoresEn":["I'm staying home.","I work at home.","I eat at home.","I sleep at home."],"nivel":"A1","tags":["gramática","casa"],"notaEn":"«Être» also covers location. «À la maison», at home; «chez moi», at my place.","requerTodas":["fr-p001","fr-p020"],"v":"2f4c02b0"},{"idioma":"fr","id":"fr-u003","tipo":"frase","requer":"fr-p001","fr":"C'est un bon livre.","en":"It's a good book.","aceitasEn":["its a good book","it is a good book","this is a good book","thats a good book"],"distratoresEn":["It was a good book.","It seems like a good book.","It's been a good book.","It will be a good book."],"nivel":"A1","tags":["gramática","escola"],"notaEn":"«C'est» (it is, this is) introduces things: «c'est un bon livre», «c'est mon ami». «Bon» goes before the noun.","requerTodas":["fr-p001","fr-p036","fr-p033"],"v":"fa795f29"},{"idioma":"fr","id":"fr-u004","tipo":"frase","requer":"fr-p002","fr":"J'ai vingt ans.","en":"I'm twenty years old.","aceitasEn":["im twenty years old","i am twenty years old","im twenty","i am twenty","im 20","im 20 years old"],"distratoresEn":["I'm turning twenty.","I'm twenty months old.","Twenty years ago.","I'm twenty days old."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"In French you have an age instead of being it: «j'ai vingt ans», literally I have twenty years. For counting years the word is «an», not «année».","requerTodas":["fr-p002","fr-p051","fr-p052"],"v":"c80f662e"},{"idioma":"fr","id":"fr-u005","tipo":"frase","requer":"fr-p002","fr":"Il y a un problème.","en":"There's a problem.","aceitasEn":["theres a problem","there is a problem"],"distratoresEn":["It's a problem.","I see a problem.","It was a problem.","I have a problem."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Il y a» is there is / there are. The verb is «avoir», and «il» refers to nobody. «C'est un problème» would be it's a problem.","requerTodas":["fr-p002","fr-p053"],"v":"1d4431e5"},{"idioma":"fr","id":"fr-u006","tipo":"frase","requer":"fr-p003","fr":"Je vais au travail.","en":"I'm going to work.","aceitasEn":["im going to work","i am going to work","i go to work","im off to work"],"distratoresEn":["I'm coming back from work.","I'm leaving work.","I'm getting to work.","I'm staying at work."],"nivel":"A1","tags":["gramática","trabalho"],"notaEn":"«Au» is «à» + «le» fused. Before a feminine noun there's no fusion: «à la maison».","requerTodas":["fr-p003","fr-p029"],"v":"7fccba40"},{"idioma":"fr","id":"fr-u007","tipo":"frase","requer":"fr-p004","fr":"Il fait beau aujourd'hui.","aceitasFr":["Aujourd'hui, il fait beau."],"en":"The weather is nice today.","aceitasEn":["the weather is nice today","its nice out today","its a nice day today","the weather is good today","its beautiful today","the weather is lovely today"],"distratoresEn":["The weather is bad today.","It's cold today.","It's hot today.","It's cloudy today."],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"French «makes» the weather: «il fait beau» (it's nice), «il fait froid» (it's cold), «il fait chaud» (it's hot). The «il» is a dummy subject, like English it.","requerTodas":["fr-p004","fr-p040","fr-p049"],"v":"d7c9038a"},{"idioma":"fr","id":"fr-u008","tipo":"frase","requer":"fr-p004","fr":"Qu'est-ce que tu fais ?","aceitasFr":["Tu fais quoi ?","Que fais-tu ?"],"en":"What are you doing?","aceitasEn":["what are you doing","what do you do","what are you up to"],"distratoresEn":["What are you saying?","What are you looking at?","What are you eating?","What do you want?"],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Qu'est-ce que» (what is it that) is the everyday way to ask what. The French present covers both what do you do and what are you doing.","requerTodas":["fr-p004"],"v":"c246341b"},{"idioma":"fr","id":"fr-u009","tipo":"frase","requer":"fr-p005","fr":"Comment on dit ça en français ?","aceitasFr":["Comment dit-on ça en français ?","Comment est-ce qu'on dit ça en français ?"],"en":"How do you say this in French?","aceitasEn":["how do you say this in french","how do you say that in french","how do we say this in french","how is this said in french","whats this in french","what is this in french"],"distratoresEn":["How do you spell this in French?","How do you read this in French?","How do you use this in French?","How do you pronounce this in French?"],"nivel":"A1","tags":["escola"],"notaEn":"«On» is the impersonal one or people, and the casual we: «on dit», people say. It takes the «il» form of the verb.","requerTodas":["fr-p005","fr-p054"],"v":"8b2ec7b8"},{"idioma":"fr","id":"fr-u010","tipo":"frase","requer":"fr-p005","fr":"Elle dit toujours la vérité.","en":"She always tells the truth.","aceitasEn":["she always tells the truth"],"distratoresEn":["She always asks for the truth.","She always knows the truth.","She always wants the truth.","She always hides the truth."],"nivel":"A1","tags":["social"],"notaEn":"«Toujours» comes after the verb: «elle dit toujours», never «elle toujours dit».","requerTodas":["fr-p005","fr-p046","fr-p055"],"v":"a2b2e01d"},{"idioma":"fr","id":"fr-u011","tipo":"frase","requer":"fr-p006","fr":"Je peux entrer ?","aceitasFr":["Puis-je entrer ?","Est-ce que je peux entrer ?"],"en":"Can I come in?","aceitasEn":["can i come in","may i come in","could i come in","can i go in"],"distratoresEn":["Should I come in?","Can I go out?","Can I sit down?","Can I wait?"],"nivel":"A1","tags":["social"],"notaEn":"A rising tone is enough to ask permission: «Je peux… ?». More formal: «Puis-je entrer ?».","requerTodas":["fr-p006","fr-p056"],"v":"c27feba8"},{"idioma":"fr","id":"fr-u012","tipo":"frase","requer":"fr-p006","fr":"On ne peut pas parler ici.","en":"You can't talk here.","aceitasEn":["you cant talk here","you cannot talk here","we cant talk here","you cant speak here","no talking here"],"distratoresEn":["You shouldn't talk here.","People don't usually talk here.","You can't smoke here.","You can't eat here."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«On» is the impersonal subject: «on ne peut pas», one can't. The negation wraps the conjugated verb, leaving the infinitive outside: «ne peut pas parler».","requerTodas":["fr-p006","fr-p012","fr-p048"],"v":"3d7cdb5b"},{"idioma":"fr","id":"fr-u013","tipo":"frase","requer":"fr-p007","fr":"Tu veux un café ?","aceitasFr":["Vous voulez un café ?","Tu veux du café ?"],"en":"Do you want a coffee?","aceitasEn":["do you want a coffee","do you want some coffee","want a coffee","would you like a coffee","you want a coffee"],"distratoresEn":["Do you have a coffee?","Are you having a coffee?","Are you making a coffee?","Are you paying for a coffee?"],"nivel":"A1","tags":["comida","social"],"notaEn":"«Tu» for people you're close to; «vous» for everyone else: «Vous voulez un café ?». Even more polite: «Tu voudrais un café ?».","requerTodas":["fr-p007","fr-p057"],"v":"42de145b"},{"idioma":"fr","id":"fr-u014","tipo":"frase","requer":"fr-p007","fr":"Qu'est-ce que ça veut dire ?","aceitasFr":["Ça veut dire quoi ?","Qu'est-ce que cela veut dire ?"],"en":"What does that mean?","aceitasEn":["what does that mean","what does this mean","whats that mean","what does it mean"],"distratoresEn":["What does that have to do with it?","What do you mean?","What does he want to do?","Where is that going?"],"nivel":"A1","tags":["escola"],"notaEn":"«Vouloir dire», literally to want to say, is the everyday to mean. «Ça» is that. Compare «Qu'est-ce que tu veux dire ?», what do you mean?","requerTodas":["fr-p007","fr-p005"],"v":"d63c0c98"},{"idioma":"fr","id":"fr-u015","tipo":"frase","requer":"fr-p008","fr":"Je sais nager.","en":"I can swim.","aceitasEn":["i can swim","i know how to swim"],"distratoresEn":["I'm allowed to swim.","I want to swim.","I'm going to swim.","I like swimming."],"nivel":"A1","tags":["cotidiano"],"notaEn":"A learned skill takes «savoir», to know: «je sais nager», I can swim. «Je peux nager» means I'm able or allowed to.","requerTodas":["fr-p008","fr-p058"],"v":"8d32e2fc"},{"idioma":"fr","id":"fr-u016","tipo":"frase","requer":"fr-p016","fr":"Je ne sais pas où il habite.","en":"I don't know where he lives.","aceitasEn":["i dont know where he lives","i do not know where he lives"],"distratoresEn":["I don't know where he works.","I don't know where he is.","I don't know where he eats.","I don't know where he studies."],"nivel":"A1","tags":["casa"],"notaEn":"«Où», with the accent, is where. In an indirect question the word order stays normal: «où il habite».","requerTodas":["fr-p008","fr-p016"],"v":"5cf93057"},{"idioma":"fr","id":"fr-u017","tipo":"frase","requer":"fr-p009","fr":"Viens ici !","aceitasFr":["Venez ici !","Viens là !"],"en":"Come here!","aceitasEn":["come here","come over here"],"distratoresEn":["Stay here!","Sit here!","Wait here!","Stop here!"],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Tu» imperative: «viens», the present form without «tu». With «vous»: «Venez ici !».","requerTodas":["fr-p009","fr-p048"],"v":"550a83c3"},{"idioma":"fr","id":"fr-u018","tipo":"frase","requer":"fr-p010","fr":"On se voit demain !","aceitasFr":["On se voit demain."],"en":"See you tomorrow!","aceitasEn":["see you tomorrow","well see each other tomorrow","see ya tomorrow"],"distratoresEn":["Talk to you tomorrow!","I'll call you tomorrow!","See you today!","See you later!"],"nivel":"A1","tags":["social"],"notaEn":"«On se voit», literally one sees each other: «on» is the casual we. The present stands in for the future, as in English «see you».","requerTodas":["fr-p010","fr-p059"],"v":"72d9bf0e"},{"idioma":"fr","id":"fr-u019","tipo":"frase","requer":"fr-p010","fr":"Je ne vois rien.","aceitasFr":["Je vois rien."],"en":"I can't see anything.","aceitasEn":["i cant see anything","i cannot see anything","i dont see anything","i see nothing","i can see nothing"],"distratoresEn":["I can't hear anything.","I don't know anything.","I don't want anything.","I'm not eating anything."],"nivel":"A1","tags":["gramática"],"notaEn":"With «rien» (nothing), «pas» drops out: «ne… rien», not… anything. In speech, «Je vois rien».","requerTodas":["fr-p010"],"v":"a4be660f"},{"idioma":"fr","id":"fr-u020","tipo":"frase","requer":"fr-p011","fr":"Je prends le bus.","en":"I take the bus.","aceitasEn":["i take the bus","im taking the bus","i am taking the bus","i catch the bus","i go by bus"],"distratoresEn":["I miss the bus.","I wait for the bus.","I pay for the bus.","I stop the bus."],"nivel":"A1","tags":["cidade","viagem","falso-amigo"],"notaEn":"Transport takes «prendre», to take: «prendre le bus», «prendre le train».","requerTodas":["fr-p011","fr-p060"],"v":"9e452f90"},{"idioma":"fr","id":"fr-u021","tipo":"frase","requer":"fr-p011","fr":"Je prends ça.","aceitasFr":["Je vais prendre ça.","Je le prends."],"en":"I'll take this.","aceitasEn":["ill take this","i will take this","ill take it","ill take this one"],"distratoresEn":["I'll pay for this.","I'll try this on.","I'll exchange this.","I'll return this."],"nivel":"A1","tags":["compras"],"notaEn":"In a shop, «je prends» means I'll take it. «Ça» is this or that.","requerTodas":["fr-p011"],"v":"33333335"},{"idioma":"fr","id":"fr-u022","tipo":"frase","requer":"fr-p012","fr":"Vous parlez trop vite.","aceitasFr":["Tu parles trop vite."],"en":"You're speaking too fast.","aceitasEn":["youre speaking too fast","you are speaking too fast","you speak too fast","youre talking too fast","you talk too fast","you speak too quickly"],"distratoresEn":["You're walking too fast.","You're eating too fast.","You're reading too fast.","You're driving too fast."],"nivel":"A1","tags":["escola"],"notaEn":"«Trop» means too and goes before the word: «trop vite», too fast.","requerTodas":["fr-p012","fr-p061","fr-p062"],"v":"9bada5b8"},{"idioma":"fr","id":"fr-u023","tipo":"frase","requer":"fr-p012","fr":"Je parle à ma mère.","en":"I'm talking to my mother.","aceitasEn":["im talking to my mother","i am talking to my mother","im talking to my mom","im talking with my mother","im speaking to my mother","i talk to my mother"],"distratoresEn":["I'm calling my mother.","I'm writing to my mother.","I'm waiting for my mother.","I'm listening to my mother."],"nivel":"A1","tags":["família"],"notaEn":"You talk «à» someone: «parler à quelqu'un». «Parler avec» also exists, more for chatting with.","requerTodas":["fr-p012","fr-p063"],"v":"6a9a1906"},{"idioma":"fr","id":"fr-u024","tipo":"frase","requer":"fr-p013","fr":"On mange à midi.","aceitasFr":["Nous mangeons à midi."],"en":"We eat at noon.","aceitasEn":["we eat at noon","we have lunch at noon","we eat at midday","we eat lunch at noon"],"distratoresEn":["We leave at noon.","We arrive at noon.","We sleep at noon.","We drink at noon."],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"«On» is the casual we, but it takes the «il» form: «on mange», we eat.","requerTodas":["fr-p013","fr-p064"],"v":"8e02ad87"},{"idioma":"fr","id":"fr-u025","tipo":"frase","requer":"fr-p013","fr":"Je ne mange pas de viande.","aceitasFr":["Je mange pas de viande."],"en":"I don't eat meat.","aceitasEn":["i dont eat meat","i do not eat meat"],"distratoresEn":["I don't buy meat.","I don't sell meat.","I don't cut meat.","I don't like meat."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"After a negative, «du», «de la» and «des» become «de»: «je mange de la viande», but «je ne mange pas de viande».","requerTodas":["fr-p013","fr-p065"],"v":"345e9202"},{"idioma":"fr","id":"fr-u026","tipo":"frase","requer":"fr-p014","fr":"Je bois de l'eau.","en":"I drink water.","aceitasEn":["i drink water","im drinking water","i am drinking water","i drink some water"],"distratoresEn":["I buy water.","I ask for water.","I bring water.","I want water."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"Uncountable things take the partitive: «de l'eau», «du pain», «de la viande», where English says some or nothing.","requerTodas":["fr-p014","fr-p026"],"v":"85816d3e"},{"idioma":"fr","id":"fr-u027","tipo":"frase","requer":"fr-p014","fr":"On boit un verre ?","aceitasFr":["On va boire un verre ?","Tu veux boire un verre ?"],"en":"Shall we grab a drink?","aceitasEn":["shall we grab a drink","shall we have a drink","lets have a drink","lets grab a drink","how about a drink","want to grab a drink"],"distratoresEn":["Shall we grab a bite?","Shall we go shopping?","Shall we do something?","Shall we watch a movie?"],"nivel":"A2","tags":["comida","social","expressão"],"notaEn":"Literally «do we drink a glass?»: «boire un verre» means to go for a drink, alcoholic or not.","requerTodas":["fr-p014","fr-p066"],"v":"69c4ef67"},{"idioma":"fr","id":"fr-u028","tipo":"frase","requer":"fr-p015","fr":"J'aime beaucoup le chocolat.","en":"I really like chocolate.","aceitasEn":["i really like chocolate","i like chocolate a lot","i love chocolate","i like chocolate very much"],"distratoresEn":["I don't like chocolate.","I don't really like chocolate.","I really like coffee.","I really like cake."],"nivel":"A1","tags":["comida"],"notaEn":"What you like takes the article: «j'aime le chocolat». «Beaucoup» goes right after the verb.","requerTodas":["fr-p015","fr-p067","fr-p068"],"v":"dddd4695"},{"idioma":"fr","id":"fr-u029","tipo":"frase","requer":"fr-p015","fr":"Je t'aime.","en":"I love you.","aceitasEn":["i love you"],"distratoresEn":["I'll help you.","I'll wait for you.","I see you.","I hear you."],"nivel":"A1","tags":["família","social"],"notaEn":"With people, plain «aimer» is love. To say you like someone as a friend, add «bien»: «je t'aime bien».","requerTodas":["fr-p015"],"v":"1bf47f32"},{"idioma":"fr","id":"fr-u030","tipo":"frase","requer":"fr-p016","fr":"J'habite à Rio.","en":"I live in Rio.","aceitasEn":["i live in rio","i live in rio de janeiro"],"distratoresEn":["I work in Rio.","I was born in Rio.","I study in Rio.","I'm staying in Rio."],"nivel":"A1","tags":["casa","cidade"],"notaEn":"Cities take «à»: «à Rio», «à Paris». Feminine countries take «en»: «j'habite en France».","requerTodas":["fr-p016"],"v":"741b534c"},{"idioma":"fr","id":"fr-u031","tipo":"frase","requer":"fr-p017","fr":"Elle travaille dans un hôpital.","en":"She works at a hospital.","aceitasEn":["she works at a hospital","she works in a hospital","she works at the hospital"],"distratoresEn":["She lives in a hospital.","She studies at a hospital.","She sleeps in a hospital.","She eats at a hospital."],"nivel":"A1","tags":["trabalho","saúde"],"notaEn":"«Dans» means in, inside. The «h» of «hôpital» is silent: «l'hôpital».","requerTodas":["fr-p017","fr-p069"],"v":"57a6875a"},{"idioma":"fr","id":"fr-u032","tipo":"frase","requer":"fr-p018","fr":"Attends-moi !","aceitasFr":["Attendez-moi !"],"en":"Wait for me!","aceitasEn":["wait for me","wait up"],"distratoresEn":["Help me!","Understand me!","Listen to me!","Call me!"],"nivel":"A1","tags":["cotidiano","falso-amigo"],"notaEn":"«Attendre» means to wait for, with no preposition. In positive commands the pronoun follows, with a hyphen: «attends-moi».","requerTodas":["fr-p018"],"v":"789d1724"},{"idioma":"fr","id":"fr-u033","tipo":"frase","requer":"fr-p019","fr":"Je travaille tous les jours.","en":"I work every day.","aceitasEn":["i work every day","i work everyday","i work daily"],"distratoresEn":["I work every month.","I work every year.","I work every night.","I work every Sunday."],"nivel":"A1","tags":["trabalho","cotidiano"],"notaEn":"«Tous les jours», every day (literally all the days): «tout» agrees, becoming «tous» in the masculine plural.","requerTodas":["fr-p017","fr-p070","fr-p019"],"v":"3fd9214d"},{"idioma":"fr","id":"fr-u034","tipo":"frase","requer":"fr-p020","fr":"Je rentre à la maison.","aceitasFr":["Je rentre chez moi."],"en":"I'm going home.","aceitasEn":["im going home","i am going home","im heading home","im going back home","i go home"],"distratoresEn":["I'm leaving home.","I'm staying home.","I'm cleaning the house.","I'm selling my house."],"nivel":"A1","tags":["casa"],"notaEn":"«Rentrer» is to go back home, or back inside. Being at home is «je suis à la maison».","requerTodas":["fr-p071","fr-p020"],"v":"2b418513"},{"idioma":"fr","id":"fr-u035","tipo":"frase","requer":"fr-p021","fr":"Cet homme est mon voisin.","en":"That man is my neighbor.","aceitasEn":["that man is my neighbor","this man is my neighbor","that man is my neighbour"],"distratoresEn":["That boy is my neighbor.","That student is my neighbor.","That doctor is my neighbor.","That waiter is my neighbor."],"nivel":"A1","tags":["família","casa"],"notaEn":"Before a vowel or silent «h», «ce» (this, that) becomes «cet»: «cet homme», «cet ami». Feminine: «cette femme».","requerTodas":["fr-p021","fr-p001","fr-p072"],"v":"cc4e46a1"},{"idioma":"fr","id":"fr-u036","tipo":"frase","requer":"fr-p022","fr":"Sa femme est française.","en":"His wife is French.","aceitasEn":["his wife is french","her wife is french"],"distratoresEn":["His daughter is French.","His sister is French.","His mother is French.","His friend is French."],"nivel":"A1","tags":["família"],"notaEn":"«Sa» agrees with the thing owned, not the owner: «sa femme» is his wife or her wife. Nationality adjectives are lowercase.","requerTodas":["fr-p022","fr-p001","fr-p054"],"v":"5dfd357a"},{"idioma":"fr","id":"fr-u037","tipo":"frase","requer":"fr-p023","fr":"Les enfants jouent dans la rue.","en":"The children are playing in the street.","aceitasEn":["the children are playing in the street","the kids are playing in the street","the children play in the street","the kids play in the street"],"distratoresEn":["The children are sleeping in the street.","The children are eating in the street.","The children live in the street.","The children are waiting in the street."],"nivel":"A1","tags":["família","cidade"],"notaEn":"«Jouer» is to play, games or instruments: «jouer au foot», «jouer du piano». The «-ent» ending of «jouent» is silent.","requerTodas":["fr-p023","fr-p073","fr-p032"],"v":"63168176"},{"idioma":"fr","id":"fr-u038","tipo":"frase","requer":"fr-p024","fr":"C'est mon meilleur ami.","en":"He's my best friend.","aceitasEn":["hes my best friend","he is my best friend"],"distratoresEn":["He's my best student.","He's my best neighbor.","He's my new friend.","He's my old friend."],"nivel":"A1","tags":["social"],"notaEn":"«Meilleur» is best or better; feminine «ma meilleure amie» sounds the same.","requerTodas":["fr-p001","fr-p074","fr-p024"],"v":"80ef1335"},{"idioma":"fr","id":"fr-u039","tipo":"frase","requer":"fr-p025","fr":"Je n'ai pas le temps.","aceitasFr":["J'ai pas le temps."],"en":"I don't have time.","aceitasEn":["i dont have time","i do not have time","i have no time","i dont have the time"],"distratoresEn":["I don't have money.","I'm not hungry.","I don't have a car.","I don't have a house."],"nivel":"A1","tags":["cotidiano"],"notaEn":"French uses the article here: «avoir le temps», to have (the) time.","requerTodas":["fr-p002","fr-p025"],"v":"4d2db924"},{"idioma":"fr","id":"fr-u040","tipo":"frase","requer":"fr-p025","fr":"Quel temps fait-il ?","aceitasFr":["Il fait quel temps ?"],"en":"What's the weather like?","aceitasEn":["whats the weather like","what is the weather like","hows the weather","how is the weather"],"distratoresEn":["How much time is left?","What time is it?","How long does it take?","What day is it today?"],"nivel":"A1","tags":["natureza"],"notaEn":"Literally «what weather does it make?». Asking the time is «Quelle heure est-il ?».","requerTodas":["fr-p025","fr-p004"],"v":"2d772968"},{"idioma":"fr","id":"fr-u041","tipo":"frase","requer":"fr-p026","fr":"Un verre d'eau, s'il vous plaît.","en":"A glass of water, please.","aceitasEn":["a glass of water please","glass of water please","a glass of water","could i have a glass of water"],"distratoresEn":["A glass of milk, please.","A glass of wine, please.","A bottle of water, please.","A bowl of soup, please."],"nivel":"A1","tags":["comida"],"notaEn":"«Le verre» is a glass, for drinking or the material. A glass of water: «un verre d'eau», with «de» and no article.","requerTodas":["fr-p066","fr-p026"],"v":"cb9ce708"},{"idioma":"fr","id":"fr-u042","tipo":"frase","requer":"fr-p027","fr":"J'achète du pain.","en":"I'm buying bread.","aceitasEn":["im buying bread","i am buying bread","i buy bread","i buy some bread","im buying some bread"],"distratoresEn":["I'm buying milk.","I'm buying cheese.","I'm buying rice.","I'm buying coffee."],"nivel":"A1","tags":["comida","compras"],"notaEn":"Bread with no quantity takes the partitive: «du pain», some bread. «Acheter» gets a grave accent before a silent ending: «j'achète», but «nous achetons».","requerTodas":["fr-p075","fr-p027"],"v":"f45530d8"},{"idioma":"fr","id":"fr-u043","tipo":"frase","requer":"fr-p028","fr":"Paris est une grande ville.","en":"Paris is a big city.","aceitasEn":["paris is a big city","paris is a large city","paris is a great city"],"distratoresEn":["Paris is a big village.","Paris is a big island.","Paris is a big square.","Paris is a big street."],"nivel":"A1","tags":["cidade"],"notaEn":"«Grand» usually goes before the noun: «une grande ville». The feminine adds «e», and then the «d» is pronounced.","requerTodas":["fr-p001","fr-p037","fr-p028"],"v":"eea5e1a7"},{"idioma":"fr","id":"fr-u044","tipo":"frase","requer":"fr-p029","fr":"J'aime mon travail.","en":"I like my job.","aceitasEn":["i like my job","i love my job","i like my work","i love my work"],"distratoresEn":["I like my neighborhood.","I like my car.","I like my boss.","I like my room."],"nivel":"A1","tags":["trabalho"],"notaEn":"«Mon travail»: masculine possessive, because «travail» is masculine.","requerTodas":["fr-p015","fr-p029"],"v":"1f7d37ef"},{"idioma":"fr","id":"fr-u045","tipo":"frase","requer":"fr-p030","fr":"Bonne nuit, à demain !","en":"Good night, see you tomorrow!","aceitasEn":["good night see you tomorrow","goodnight see you tomorrow","night see you tomorrow"],"distratoresEn":["Good morning, see you tomorrow!","Good afternoon, see you tomorrow!","Good night, see you later!","Have a good trip, see you tomorrow!"],"nivel":"A1","tags":["social"],"notaEn":"«Bonne nuit» is for bedtime; arriving in the evening, say «Bonsoir».","requerTodas":["fr-p036","fr-p030","fr-p059"],"v":"8ccdc042"},{"idioma":"fr","id":"fr-u046","tipo":"frase","requer":"fr-p030","fr":"Il travaille la nuit.","en":"He works at night.","aceitasEn":["he works at night","he works nights","he works during the night"],"distratoresEn":["He works during the day.","He works in the afternoon.","He works early.","He works alone."],"nivel":"A1","tags":["trabalho","cotidiano"],"notaEn":"With the article and no preposition, «la nuit» means at night, as a habit.","requerTodas":["fr-p017","fr-p030"],"v":"368432ce"},{"idioma":"fr","id":"fr-u047","tipo":"frase","requer":"fr-p031","fr":"Bonne année !","en":"Happy New Year!","aceitasEn":["happy new year"],"distratoresEn":["Happy birthday!","Merry Christmas!","Good luck!","Enjoy your vacation!"],"nivel":"A1","tags":["social","cultura"],"notaEn":"Said from January 1st, and through the whole month. It's «année», not «an», because you wish someone the year as lived.","requerTodas":["fr-p036","fr-p031"],"v":"749578ec"},{"idioma":"fr","id":"fr-u048","tipo":"frase","requer":"fr-p031","fr":"Cette année, je vais en France.","en":"This year I'm going to France.","aceitasEn":["this year im going to france","this year i am going to france","im going to france this year","this year i go to france"],"distratoresEn":["This month I'm going to France.","This summer I'm going to France.","This winter I'm going to France.","This Sunday I'm going to France."],"nivel":"A1","tags":["viagem"],"notaEn":"«Cette» is the feminine of «ce» (this), because «année» is feminine. Feminine countries take «en»: «en France».","requerTodas":["fr-p031","fr-p003"],"v":"1006048d"},{"idioma":"fr","id":"fr-u049","tipo":"frase","requer":"fr-p032","fr":"J'habite dans cette rue.","en":"I live on this street.","aceitasEn":["i live on this street","i live in this street"],"distratoresEn":["I live in this city.","I live in this house.","I live on this square.","I live in this village."],"nivel":"A1","tags":["cidade","casa"],"notaEn":"On a street is «dans la rue». In an address, no preposition or article: «j'habite rue Victor-Hugo».","requerTodas":["fr-p016","fr-p032"],"v":"a02797f6"},{"idioma":"fr","id":"fr-u050","tipo":"frase","requer":"fr-p033","fr":"Je lis un livre.","en":"I'm reading a book.","aceitasEn":["im reading a book","i am reading a book","i read a book"],"distratoresEn":["I'm reading a newspaper.","I'm reading a poem.","I'm reading an email.","I'm reading a note."],"nivel":"A1","tags":["escola"],"notaEn":"«Lire» is to read: je lis, tu lis, il lit, nous lisons. The present also means I'm reading.","requerTodas":["fr-p076","fr-p033"],"v":"8203ae4c"},{"idioma":"fr","id":"fr-u051","tipo":"frase","requer":"fr-p034","fr":"Ma voiture est en panne.","en":"My car has broken down.","aceitasEn":["my car has broken down","my car broke down","my car is broken down","my car isnt working"],"distratoresEn":["My car has been washed.","My car has been sold.","My car is parked.","My car is dirty."],"nivel":"A2","tags":["cidade","viagem"],"notaEn":"«Ma voiture»: feminine possessive, because «voiture» is feminine. «En panne» works for anything that stops working.","requerTodas":["fr-p034","fr-p001","fr-p077"],"v":"941bf898"},{"idioma":"fr","id":"fr-u052","tipo":"frase","requer":"fr-p035","fr":"Je n'ai pas d'argent.","aceitasFr":["J'ai pas d'argent."],"en":"I don't have any money.","aceitasEn":["i dont have any money","i dont have money","i have no money","i do not have any money"],"distratoresEn":["I don't have any time.","I don't have any change.","I don't have a card.","I don't have any work."],"nivel":"A1","tags":["compras","economia"],"notaEn":"After a negative, just «de»: «pas d'argent». In the positive, the partitive: «j'ai de l'argent», I have (some) money.","requerTodas":["fr-p002","fr-p035"],"v":"ee886767"},{"idioma":"fr","id":"fr-u053","tipo":"frase","requer":"fr-p036","fr":"C'est très bon !","en":"It's really good!","aceitasEn":["its really good","its very good","it is very good","its delicious","its so good","its really tasty"],"distratoresEn":["It's really salty!","It's really hot!","It's really sweet!","It's really expensive!"],"nivel":"A1","tags":["comida"],"notaEn":"For food, «bon» means tasty. Hot, as in temperature, is «chaud».","requerTodas":["fr-p001","fr-p043","fr-p036"],"v":"20734602"},{"idioma":"fr","id":"fr-u054","tipo":"frase","requer":"fr-p037","fr":"Mon frère est très grand.","en":"My brother is very tall.","aceitasEn":["my brother is very tall","my brother is really tall","my brother is very big"],"distratoresEn":["My brother is very short.","My brother is very young.","My brother is very thin.","My brother is very strong."],"nivel":"A1","tags":["família"],"notaEn":"For people, «grand» is tall and «petit» is short.","requerTodas":["fr-p078","fr-p001","fr-p043","fr-p037"],"v":"b766b7e6"},{"idioma":"fr","id":"fr-u055","tipo":"frase","requer":"fr-p038","fr":"Mon appartement est petit.","en":"My apartment is small.","aceitasEn":["my apartment is small","my flat is small","my apartment is little"],"distratoresEn":["My apartment is new.","My apartment is expensive.","My apartment is old.","My apartment is pretty."],"nivel":"A1","tags":["casa"],"notaEn":"«Petit» can follow «être», as here, or go before the noun: «un petit appartement».","requerTodas":["fr-p079","fr-p001","fr-p038"],"v":"2a590e34"},{"idioma":"fr","id":"fr-u056","tipo":"frase","requer":"fr-p039","fr":"J'ai une nouvelle voiture.","en":"I have a new car.","aceitasEn":["i have a new car","ive got a new car","i got a new car"],"distratoresEn":["I have an old car.","I have an expensive car.","I have a nice car.","I have a small car."],"nivel":"A1","tags":["cidade"],"notaEn":"«Nouvelle» agrees with «voiture» and goes before it. «Une voiture neuve» is a brand-new car, never used.","requerTodas":["fr-p002","fr-p039","fr-p034"],"v":"0711218d"},{"idioma":"fr","id":"fr-u057","tipo":"frase","requer":"fr-p040","fr":"Quelle belle maison !","en":"What a beautiful house!","aceitasEn":["what a beautiful house","what a lovely house","what a pretty house"],"distratoresEn":["What a big house!","What an old house!","What a small house!","What an expensive house!"],"nivel":"A1","tags":["casa"],"notaEn":"«Belle» is the feminine of «beau». Exclamatory «quel» (what a) agrees too: «quelle maison», «quel livre».","requerTodas":["fr-p040","fr-p020"],"v":"9657bf10"},{"idioma":"fr","id":"fr-u058","tipo":"frase","requer":"fr-p041","fr":"C'est un vieil ami.","en":"He's an old friend.","aceitasEn":["hes an old friend","he is an old friend","its an old friend"],"distratoresEn":["He's a new friend.","He's a good friend.","He's a great friend.","He's a false friend."],"nivel":"A2","tags":["social"],"notaEn":"Before a vowel, «vieux» becomes «vieil»: «un vieil ami», «un vieil homme». It sounds like «vieille».","requerTodas":["fr-p001","fr-p041","fr-p024"],"v":"cd54833a"},{"idioma":"fr","id":"fr-u059","tipo":"frase","requer":"fr-p042","fr":"Je suis content de te voir.","aceitasFr":["Je suis contente de te voir."],"en":"I'm glad to see you.","aceitasEn":["im glad to see you","im happy to see you","i am glad to see you","i am happy to see you","good to see you","nice to see you","its good to see you"],"distratoresEn":["I'm sad to see you.","I'm glad to hear from you.","I'm glad to help you.","I'm glad to meet you."],"nivel":"A1","tags":["social"],"notaEn":"«Content de» + infinitive: glad to. A woman says «contente».","requerTodas":["fr-p001","fr-p042","fr-p010"],"v":"c7f09ccf"},{"idioma":"fr","id":"fr-u060","tipo":"frase","requer":"fr-p043","fr":"Il fait très froid.","en":"It's very cold.","aceitasEn":["its very cold","it is very cold","its really cold","its freezing"],"distratoresEn":["It's very hot.","It's a bit cold.","It's kind of cold.","It's very humid."],"nivel":"A1","tags":["natureza"],"notaEn":"«Froid» is an adjective here, so it takes «très»: «il fait très froid».","requerTodas":["fr-p004","fr-p043","fr-p080"],"v":"9a172c42"},{"idioma":"fr","id":"fr-u061","tipo":"frase","requer":"fr-p044","fr":"Tu parles très bien français !","aceitasFr":["Vous parlez très bien français !","Tu parles très bien le français !"],"en":"You speak French very well!","aceitasEn":["you speak french very well","you speak very good french","your french is very good","you speak french really well"],"distratoresEn":["You speak French very badly!","You speak French very fast!","You speak French very loudly!","You speak very little French!"],"nivel":"A1","tags":["escola"],"notaEn":"«Bien» modifies the verb. «Bon» is the adjective: «un bon livre».","requerTodas":["fr-p012","fr-p043","fr-p044","fr-p054"],"v":"6038d70b"},{"idioma":"fr","id":"fr-u062","tipo":"frase","requer":"fr-p045","fr":"Elle parle aussi anglais.","aceitasFr":["Elle parle anglais aussi.","Elle parle aussi l'anglais."],"en":"She also speaks English.","aceitasEn":["she also speaks english","she speaks english too","she speaks english as well"],"distratoresEn":["She only speaks English.","She still speaks English.","She already speaks English.","She doesn't speak English."],"nivel":"A1","tags":["escola"],"notaEn":"«Aussi» comes after the verb: «elle parle aussi anglais». With a pronoun alone: «moi aussi», me too.","requerTodas":["fr-p045","fr-p012","fr-p081"],"v":"964165b4"},{"idioma":"fr","id":"fr-u063","tipo":"frase","requer":"fr-p046","fr":"Il habite toujours ici.","en":"He still lives here.","aceitasEn":["he still lives here"],"distratoresEn":["He already lives here.","He doesn't live here anymore.","He almost lives here.","He only lives here."],"nivel":"A2","tags":["casa"],"notaEn":"Here «toujours» means still. The opposite is «ne… plus»: «il n'habite plus ici», he doesn't live here anymore.","requerTodas":["fr-p016","fr-p046","fr-p048"],"v":"db312dc7"},{"idioma":"fr","id":"fr-u064","tipo":"frase","requer":"fr-p047","fr":"Je dois partir maintenant.","en":"I have to leave now.","aceitasEn":["i have to leave now","i have to go now","i need to go now","i need to leave now","i must go now","i must leave now","i gotta go now"],"distratoresEn":["I have to leave tomorrow.","I have to leave soon.","I have to leave early.","I have to leave later."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Devoir» is to have to, must. «Partir» is to leave, go away.","requerTodas":["fr-p082","fr-p083","fr-p047"],"v":"c7b5424a"},{"idioma":"fr","id":"fr-u065","tipo":"frase","requer":"fr-p048","fr":"Ici, on parle français.","en":"French is spoken here.","aceitasEn":["french is spoken here","we speak french here","here we speak french","here people speak french"],"distratoresEn":["French is spoken there.","French is spoken over there.","French is spoken like this.","French is spoken nearby."],"nivel":"A1","tags":["viagem"],"notaEn":"«On» works as the impersonal subject: «on parle», one speaks, is spoken. After «parler», the language needs no article.","requerTodas":["fr-p048","fr-p012","fr-p054"],"v":"824e6541"},{"idioma":"fr","id":"fr-u066","tipo":"frase","requer":"fr-p049","fr":"Aujourd'hui, c'est lundi.","aceitasFr":["Aujourd'hui, on est lundi.","On est lundi aujourd'hui."],"en":"Today is Monday.","aceitasEn":["today is monday","its monday today","it is monday today","today its monday"],"distratoresEn":["Yesterday was Monday.","Tomorrow is Monday.","Today is Tuesday.","Today is Sunday."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Days of the week are lowercase in French and take no article here: «c'est lundi». People also say «on est lundi».","requerTodas":["fr-p049","fr-p001","fr-p084"],"v":"76e78760"},{"idioma":"fr","id":"fr-u067","tipo":"frase","requer":"fr-p050","fr":"J'ai déjà mangé.","en":"I've already eaten.","aceitasEn":["ive already eaten","i have already eaten","i already ate","ive eaten already"],"distratoresEn":["I haven't eaten yet.","I'm about to eat.","I've never eaten.","I ate very little."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"«Déjà» sits between the helper verb and the participle: «j'ai déjà mangé».","requerTodas":["fr-p002","fr-p050","fr-p013"],"v":"3cf8da8a"},{"idioma":"fr","id":"fr-v001","tipo":"frase","fr":"Je suis en retard.","en":"I'm late.","aceitasEn":["im late","i am late","im running late","i am running late"],"distratoresEn":["I was late.","I've been late.","I'll be late.","I would be late."],"formasFr":{"J'étais en retard":"imperfect","J'ai été en retard":"passé composé","Je serai en retard":"future","Je serais en retard":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"«En retard» doesn't change for gender. Present of «être»: je suis, tu es, il est, nous sommes, vous êtes, ils sont.","requerTodas":["fr-p001","fr-p085"],"v":"f62716a4"},{"idioma":"fr","id":"fr-v002","tipo":"frase","fr":"Ils ont faim.","aceitasFr":["Elles ont faim."],"en":"They're hungry.","aceitasEn":["theyre hungry","they are hungry"],"distratoresEn":["They were hungry.","They got hungry.","They'll be hungry.","They'd be hungry."],"formasFr":{"Ils avaient faim":"imperfect","Ils ont eu faim":"passé composé","Ils auront faim":"future","Ils auraient faim":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"«Ils ont» (they have) links with a «z» sound: «eel-ZON». «Ils sont» (they are) has an «s» sound: watch the difference.","requerTodas":["fr-p002","fr-p086"],"v":"d93491f3"},{"idioma":"fr","id":"fr-v003","tipo":"frase","fr":"Je vais à la plage.","en":"I'm going to the beach.","aceitasEn":["im going to the beach","i am going to the beach","i go to the beach"],"distratoresEn":["I was going to the beach.","I went to the beach.","I'll go to the beach.","I would go to the beach."],"formasFr":{"J'allais à la plage":"imperfect","Je suis allé à la plage":"passé composé","J'irai à la plage":"future","J'irais à la plage":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","viagem"],"notaEn":"Present of «aller»: je vais, tu vas, il va, nous allons, vous allez, ils vont. The future switches stems: «j'irai».","requerTodas":["fr-p003","fr-p087"],"v":"f09313a4"},{"idioma":"fr","id":"fr-v004","tipo":"frase","fr":"Elle fait du sport.","en":"She does sports.","aceitasEn":["she does sports","she plays sports","she does sport","she exercises","she works out"],"distratoresEn":["She used to do sports.","She did sports.","She'll do sports.","She would do sports."],"formasFr":{"Elle faisait du sport":"imperfect","Elle a fait du sport":"passé composé","Elle fera du sport":"future","Elle ferait du sport":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","saúde"],"notaEn":"«Faire du sport», with the partitive, is to do sports. Present of «faire»: je fais, nous faisons, vous faites, ils font; future «elle fera».","requerTodas":["fr-p004","fr-p161"],"v":"222a81f0"},{"idioma":"fr","id":"fr-v005","tipo":"frase","fr":"Ils prennent le train.","aceitasFr":["Elles prennent le train."],"en":"They take the train.","aceitasEn":["they take the train","theyre taking the train","they are taking the train","they go by train"],"distratoresEn":["They used to take the train.","They took the train.","They'll take the train.","They would take the train."],"formasFr":{"Ils prenaient le train":"imperfect","Ils ont pris le train":"passé composé","Ils prendront le train":"future","Ils prendraient le train":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","viagem"],"notaEn":"Present of «prendre»: je prends, nous prenons, ils prennent (double «n»). Past participle: «pris».","requerTodas":["fr-p011","fr-p089"],"v":"8c99020a"},{"idioma":"fr","id":"fr-v006","tipo":"frase","fr":"Il ne peut pas venir.","aceitasFr":["Il peut pas venir."],"en":"He can't come.","aceitasEn":["he cant come","he cannot come","he is not able to come","he isnt able to come"],"distratoresEn":["He couldn't come.","He wasn't able to come.","He won't be able to come.","He wouldn't be able to come."],"formasFr":{"Il ne pouvait pas venir":"imperfect","Il n'a pas pu venir":"passé composé","Il ne pourra pas venir":"future","Il ne pourrait pas venir":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"The future and conditional of «pouvoir» have a double «r»: «il pourra», «il pourrait». Past participle: «pu».","requerTodas":["fr-p006","fr-p009"],"v":"4db35ee9"},{"idioma":"fr","id":"fr-v007","tipo":"frase","fr":"Elle veut un chien.","en":"She wants a dog.","aceitasEn":["she wants a dog"],"distratoresEn":["She used to want a dog.","She wanted a dog.","She'll want a dog.","She would like a dog."],"formasFr":{"Elle voulait un chien":"imperfect","Elle a voulu un chien":"passé composé","Elle voudra un chien":"future","Elle voudrait un chien":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","animais"],"notaEn":"Present of «vouloir»: je veux, tu veux, il veut, nous voulons, ils veulent. The conditional, «elle voudrait», is would like.","requerTodas":["fr-p007","fr-p090"],"v":"6fc4f26d"},{"idioma":"fr","id":"fr-v008","tipo":"frase","fr":"Je sais la réponse.","aceitasFr":["Je connais la réponse."],"en":"I know the answer.","aceitasEn":["i know the answer"],"distratoresEn":["I knew the answer.","I found out the answer.","I'll know the answer.","I would know the answer."],"formasFr":{"Je savais la réponse":"imperfect","J'ai su la réponse":"passé composé","Je saurai la réponse":"future","Je saurais la réponse":"conditional"},"nivel":"A2","tags":["conjugação","presente","irregular"],"notaEn":"Irregular future: «je saurai». In the passé composé, «j'ai su» means I found out.","requerTodas":["fr-p008","fr-p091"],"v":"63e9a8b2"},{"idioma":"fr","id":"fr-v009","tipo":"frase","fr":"Il vient avec nous.","en":"He's coming with us.","aceitasEn":["hes coming with us","he is coming with us","he comes with us"],"distratoresEn":["He was coming with us.","He came with us.","He'll come with us.","He would come with us."],"formasFr":{"Il venait avec nous":"imperfect","Il est venu avec nous":"passé composé","Il viendra avec nous":"future","Il viendrait avec nous":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular"],"notaEn":"«Venir» forms the passé composé with «être»: «il est venu». The future adds a «d»: «il viendra».","requerTodas":["fr-p009"],"v":"77b9eb82"},{"idioma":"fr","id":"fr-v010","tipo":"frase","fr":"Il m'a dit non.","en":"He told me no.","aceitasEn":["he told me no","he said no to me","he said no"],"distratoresEn":["He tells me no.","He used to tell me no.","He'll tell me no.","He would tell me no."],"formasFr":{"Il me dit non":"present","Il me disait non":"imperfect","Il me dira non":"future","Il me dirait non":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"The past participle of «dire» is «dit». The pronoun goes before the helper verb: «il m'a dit», he told me.","requerTodas":["fr-p005"],"v":"53201d87"},{"idioma":"fr","id":"fr-v011","tipo":"frase","fr":"Je vois la mer.","en":"I can see the sea.","aceitasEn":["i can see the sea","i see the sea","i can see the ocean","i see the ocean"],"distratoresEn":["I could see the sea.","I saw the sea.","I'll see the sea.","I would see the sea."],"formasFr":{"Je voyais la mer":"imperfect","J'ai vu la mer":"passé composé","Je verrai la mer":"future","Je verrais la mer":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","natureza"],"notaEn":"«La mer» is feminine. The future of «voir» has a double «r»: «je verrai». Past participle: «vu».","requerTodas":["fr-p010","fr-p092"],"v":"8d07ad9e"},{"idioma":"fr","id":"fr-v012","tipo":"frase","fr":"Il boit du vin.","en":"He drinks wine.","aceitasEn":["he drinks wine","hes drinking wine","he is drinking wine"],"distratoresEn":["He used to drink wine.","He drank wine.","He'll drink wine.","He would drink wine."],"formasFr":{"Il buvait du vin":"imperfect","Il a bu du vin":"passé composé","Il boira du vin":"future","Il boirait du vin":"conditional"},"nivel":"A2","tags":["conjugação","presente","irregular","comida"],"notaEn":"«Boire» changes stem in the plural and the imperfect: «nous buvons», «il buvait». Past participle: «bu».","requerTodas":["fr-p014","fr-p093"],"v":"cbb102cd"},{"idioma":"fr","id":"fr-v013","tipo":"frase","fr":"Elle parle trois langues.","en":"She speaks three languages.","aceitasEn":["she speaks three languages","she speaks 3 languages"],"distratoresEn":["She used to speak three languages.","She spoke three languages.","She'll speak three languages.","She would speak three languages."],"formasFr":{"Elle parlait trois langues":"imperfect","Elle a parlé trois langues":"passé composé","Elle parlera trois langues":"future","Elle parlerait trois langues":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular"],"notaEn":"The regular «-er» pattern: future and conditional are built on the whole infinitive, «parler-a», «parler-ait».","requerTodas":["fr-p012","fr-p094","fr-p095"],"v":"254d23f4"},{"idioma":"fr","id":"fr-v014","tipo":"frase","fr":"J'ai mangé une pomme.","en":"I ate an apple.","aceitasEn":["i ate an apple","ive eaten an apple","i have eaten an apple","i had an apple"],"distratoresEn":["I'm eating an apple.","I was eating an apple.","I'm going to eat an apple.","I'll eat an apple."],"formasFr":{"Je mange une pomme":"present","Je mangeais une pomme":"imperfect","Je vais manger une pomme":"near future","Je mangerai une pomme":"future"},"nivel":"A1","tags":["conjugação","pretérito","regular","comida"],"notaEn":"The everyday past is the passé composé: «avoir» + participle, used for both I ate and I have eaten. In «-er» verbs the participle ends in «-é».","requerTodas":["fr-p013","fr-p096"],"v":"fa586b22"},{"idioma":"fr","id":"fr-v015","tipo":"frase","fr":"Nous sommes allés au cinéma.","aceitasFr":["Nous sommes allées au cinéma.","On est allés au cinéma."],"en":"We went to the movies.","aceitasEn":["we went to the movies","we went to the cinema","we went to see a movie"],"distratoresEn":["We're going to the movies.","We used to go to the movies.","We'll go to the movies.","We would go to the movies."],"formasFr":{"Nous allons au cinéma":"present","Nous allions au cinéma":"imperfect","Nous irons au cinéma":"future","Nous irions au cinéma":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cultura"],"notaEn":"Verbs of motion (aller, venir, partir, arriver…) take «être» in the passé composé, and the participle agrees: «nous sommes allés», «elles sont allées».","requerTodas":["fr-p001","fr-p003","fr-p097"],"v":"a94a88ae"},{"idioma":"fr","id":"fr-v016","tipo":"frase","fr":"Elle est partie.","en":"She left.","aceitasEn":["she left","she has left","she went away","she has gone"],"distratoresEn":["She's leaving.","She was leaving.","She's going to leave.","She'll leave."],"formasFr":{"Elle part":"present","Elle partait":"imperfect","Elle va partir":"near future","Elle partira":"future"},"nivel":"A1","tags":["conjugação","pretérito","irregular"],"notaEn":"«Partir» takes «être» in the passé composé, and the participle agrees with her: «elle est partie».","requerTodas":["fr-p001","fr-p083"],"v":"64be71e1"},{"idioma":"fr","id":"fr-v017","tipo":"frase","fr":"Je travaillais à Paris.","en":"I used to work in Paris.","aceitasEn":["i used to work in paris","i was working in paris"],"distratoresEn":["I work in Paris.","I worked in Paris.","I'll work in Paris.","I would work in Paris."],"formasFr":{"Je travaille à Paris":"present","J'ai travaillé à Paris":"passé composé","Je travaillerai à Paris":"future","Je travaillerais à Paris":"conditional"},"nivel":"A2","tags":["conjugação","imperfeito","regular","trabalho"],"notaEn":"The imperfect tells what used to happen. Its endings are the same for every verb: -ais, -ais, -ait, -ions, -iez, -aient.","requerTodas":["fr-p017"],"v":"ca1acc28"},{"idioma":"fr","id":"fr-v018","tipo":"frase","fr":"Il faisait froid.","en":"It was cold.","aceitasEn":["it was cold"],"distratoresEn":["It's cold.","It's been cold.","It'll be cold.","It would be cold."],"formasFr":{"Il fait froid":"present","Il a fait froid":"passé composé","Il fera froid":"future","Il ferait froid":"conditional"},"nivel":"A2","tags":["conjugação","imperfeito","irregular","natureza"],"notaEn":"The imperfect describes the background: what the weather was like. The passé composé, «il a fait froid», reports a closed period.","requerTodas":["fr-p004","fr-p080"],"v":"9e9cdb8c"},{"idioma":"fr","id":"fr-v019","tipo":"frase","fr":"On va manger au restaurant.","aceitasFr":["Nous allons manger au restaurant."],"en":"We're going to eat at the restaurant.","aceitasEn":["we are going to eat at the restaurant","were going to eat at the restaurant","were going to eat at a restaurant","we are going to eat at a restaurant"],"distratoresEn":["We eat at the restaurant.","We ate at the restaurant.","We used to eat at the restaurant.","We would eat at the restaurant."],"formasFr":{"On mange au restaurant":"present","On a mangé au restaurant":"passé composé","On mangeait au restaurant":"imperfect","On mangerait au restaurant":"conditional"},"nivel":"A1","tags":["conjugação","futuro","comida"],"notaEn":"The near future is «aller» + infinitive, just like going to: «on va manger». It's the most common future in speech.","requerTodas":["fr-p003","fr-p013","fr-p098"],"v":"51f52dc1"},{"idioma":"fr","id":"fr-v020","tipo":"frase","fr":"Tu verras.","en":"You'll see.","aceitasEn":["youll see","you will see","you are going to see"],"distratoresEn":["You see.","You saw.","You used to see.","You would see."],"formasFr":{"Tu vois":"present","Tu as vu":"passé composé","Tu voyais":"imperfect","Tu verrais":"conditional"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"The simple future adds the endings of «avoir» to the infinitive: «tu parleras». Some verbs change stem: «tu verras», «tu seras», «tu auras», «tu iras».","requerTodas":["fr-p010"],"v":"79a0aaf4"},{"idioma":"fr","id":"fr-v021","tipo":"frase","fr":"Ce serait génial !","en":"That would be great!","aceitasEn":["that would be great","it would be great","thatd be great","that would be awesome"],"distratoresEn":["That's great!","That was great!","It's been great!","That'll be great!"],"formasFr":{"C'est génial":"present","C'était génial":"imperfect","Ça a été génial":"passé composé","Ce sera génial":"future"},"nivel":"A2","tags":["conjugação","condicional","irregular"],"notaEn":"The conditional joins the future stem and the imperfect endings: «ser-» + «-ait» = «serait».","requerTodas":["fr-p001","fr-p099"],"v":"286d5e2f"},{"idioma":"fr","id":"fr-v022","tipo":"frase","fr":"Tu as vu ce film ?","aceitasFr":["Vous avez vu ce film ?"],"en":"Did you see this movie?","aceitasEn":["did you see this movie","have you seen this movie","did you see that movie","have you seen this film","did you watch this movie"],"distratoresEn":["Are you watching this movie?","Did you use to watch this movie?","Are you going to see this movie?","Will you see this movie?"],"formasFr":{"Tu vois ce film":"present","Tu voyais ce film":"imperfect","Tu vas voir ce film":"near future","Tu verras ce film":"future"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cultura"],"notaEn":"Irregular participle of «voir»: «vu». «Ce film»: «ce» means this or that.","requerTodas":["fr-p002","fr-p010","fr-p100"],"v":"26338564"},{"idioma":"fr","id":"fr-v023","tipo":"frase","fr":"J'ai pris le métro.","en":"I took the subway.","aceitasEn":["i took the subway","i took the metro","ive taken the subway","i have taken the subway","i took the underground"],"distratoresEn":["I take the subway.","I used to take the subway.","I'm going to take the subway.","I'll take the subway."],"formasFr":{"Je prends le métro":"present","Je prenais le métro":"imperfect","Je vais prendre le métro":"near future","Je prendrai le métro":"future"},"nivel":"A1","tags":["conjugação","pretérito","irregular","cidade"],"notaEn":"Irregular participle of «prendre»: «pris», silent «s». Same in «apprendre», «appris», and «comprendre», «compris».","requerTodas":["fr-p002","fr-p011","fr-p101"],"v":"c4da3cc5"},{"idioma":"fr","id":"fr-v024","tipo":"frase","fr":"J'ai eu peur.","en":"I got scared.","aceitasEn":["i got scared","i was scared","i was afraid","i got frightened"],"distratoresEn":["I'm scared.","I used to be scared.","I'll be scared.","I would be scared."],"formasFr":{"J'ai peur":"present","J'avais peur":"imperfect","J'aurai peur":"future","J'aurais peur":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"Fear is something you have: «avoir peur». The participle of «avoir» is «eu», pronounced like the «u» in «tu».","requerTodas":["fr-p002","fr-p102"],"v":"ebff2f27"},{"idioma":"fr","id":"fr-p051","tipo":"palavra","fr":"vingt","en":"twenty","aceitasEn":["twenty","20"],"distratoresEn":["thirty","twelve","two","a hundred"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «gt» is silent: «vingt» sounds like «vin» (wine). The «t» is heard again in «vingt et un» and from «vingt-deux» to «vingt-neuf».","v":"a8828f4e"},{"idioma":"fr","id":"fr-p052","tipo":"palavra","fr":"l'an","aceitasFr":["un an"],"en":"the year (counting)","aceitasEn":["year","the year","years"],"distratoresEn":["the month (calendar)","the day (of the week)","the ring (gold)","the nest (bird)"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine. The year you count with: age («vingt ans»), duration («deux ans»), dates («l'an 2000»). The year as lived is «l'année».","v":"807ad884"},{"idioma":"fr","id":"fr-p053","tipo":"palavra","fr":"le problème","en":"the problem","aceitasEn":["problem","the problem","the issue","the trouble"],"distratoresEn":["the poem","the prize","the program","the purpose"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine. «Pas de problème», no problem.","v":"a54e78ea"},{"idioma":"fr","id":"fr-p054","tipo":"palavra","fr":"français","aceitasFr":["française","le français"],"en":"French","aceitasEn":["french"],"distratoresEn":["fresh","frank","Flemish","English"],"nivel":"A1","tags":["adjetivo","cultura"],"notaEn":"Adjective and language: «un livre français», «parler français». Lowercase; only the people are capitalized: «les Français».","v":"4479a36b"},{"idioma":"fr","id":"fr-p055","tipo":"palavra","fr":"la vérité","en":"the truth","aceitasEn":["truth","the truth"],"distratoresEn":["the vegetable","the variety","the will","the lie"],"nivel":"A1","tags":["cotidiano"],"notaEn":"French «-té» often matches English «-ty»: «la liberté», liberty; «la société», society.","v":"2f6e227f"},{"idioma":"fr","id":"fr-p056","tipo":"palavra","fr":"entrer","en":"to enter","aceitasEn":["to enter","enter","to come in","to go in"],"distratoresEn":["to bury","to deliver","to entertain","to meet"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb, with «être» in the passé composé: «je suis entré». The entrance is «l'entrée», which on a menu is the starter.","v":"c8acaf30"},{"idioma":"fr","id":"fr-p057","tipo":"palavra","fr":"le café","en":"coffee","aceitasEn":["coffee","the coffee","cafe","the cafe","a cafe"],"distratoresEn":["tea","cocoa","milk","sugar"],"nivel":"A1","tags":["comida","cidade"],"notaEn":"Both the drink and the place: «on se retrouve au café», let's meet at the café. Ordered on its own, «un café» is an espresso.","v":"5e1fa861"},{"idioma":"fr","id":"fr-p058","tipo":"palavra","fr":"nager","en":"to swim","aceitasEn":["to swim","swim"],"distratoresEn":["to deny","to sail","to be born","to dive"],"nivel":"A1","tags":["verbo","natureza"],"notaEn":"Like «manger», it adds an «e» in «nous nageons». Swimming, the sport, is «la natation».","v":"bab4d405"},{"idioma":"fr","id":"fr-p059","tipo":"palavra","fr":"demain","en":"tomorrow","aceitasEn":["tomorrow"],"distratoresEn":["yesterday","afterwards","in the morning","today"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Tomorrow. The morning is «le matin». «À demain !», see you tomorrow.","v":"f980ac54"},{"idioma":"fr","id":"fr-p060","tipo":"palavra","fr":"le bus","en":"the bus","aceitasEn":["bus","the bus"],"distratoresEn":["the streetcar","the boat","the taxi","the bust"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"The final «s» is pronounced. A long-distance coach is «le car».","v":"0bf078c2"},{"idioma":"fr","id":"fr-p061","tipo":"palavra","fr":"trop","en":"too / too much","aceitasEn":["too","too much","too many"],"distratoresEn":["little / not much","late / later","so much / so","almost / nearly"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Before an adjective, «trop» is too: «trop cher», too expensive. With a noun it takes «de»: «trop de gens», too many people.","v":"62e9e03d"},{"idioma":"fr","id":"fr-p062","tipo":"palavra","fr":"vite","en":"fast / quickly","aceitasEn":["fast","quickly","quick"],"distratoresEn":["slowly / slow","early / ahead","far / away","late / later"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Adverb: «parler vite», to talk fast. The adjective is «rapide». «Vite !», quick!","v":"a5bae2f8"},{"idioma":"fr","id":"fr-p063","tipo":"palavra","fr":"la mère","en":"the mother","aceitasEn":["mother","the mother","mom","the mom"],"distratoresEn":["the table","the girl","the sister","the grandmother"],"nivel":"A1","tags":["família"],"notaEn":"It sounds exactly like «la mer» (the sea). Mom is «maman».","v":"eb47714d"},{"idioma":"fr","id":"fr-p064","tipo":"palavra","fr":"midi","en":"noon","aceitasEn":["noon","midday"],"distratoresEn":["middle","month","Sunday","dusk"],"nivel":"A1","tags":["cotidiano"],"notaEn":"No article: «à midi», at noon. Capitalized, «le Midi» is the south of France.","v":"4f63560a"},{"idioma":"fr","id":"fr-p065","tipo":"palavra","fr":"la viande","en":"meat","aceitasEn":["meat","the meat"],"distratoresEn":["fruit","vegetables","vineyard","pasta"],"nivel":"A1","tags":["comida"],"notaEn":"Meat as food. Flesh is «la chair».","v":"a492d682"},{"idioma":"fr","id":"fr-p066","tipo":"palavra","fr":"le verre","en":"the glass","aceitasEn":["glass","the glass"],"distratoresEn":["the plate","the vase","the fork","the verse"],"nivel":"A1","tags":["comida","casa"],"notaEn":"Both a drinking glass and the material: «un verre d'eau», «une table en verre». Eyeglasses are «les lunettes».","v":"49bf339f"},{"idioma":"fr","id":"fr-p067","tipo":"palavra","fr":"beaucoup","en":"a lot","aceitasEn":["a lot","much","very much","lots"],"distratoresEn":["a little","nicely","cheaply","too much"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Beaucoup» is a lot, very much: «j'aime beaucoup»; with a noun, «beaucoup de»: «beaucoup d'amis». Before adjectives, very is «très».","v":"2422a4d6"},{"idioma":"fr","id":"fr-p068","tipo":"palavra","fr":"le chocolat","en":"chocolate","aceitasEn":["chocolate","the chocolate"],"distratoresEn":["cocoa","chewing gum","caramel","rattle"],"nivel":"A1","tags":["comida"],"notaEn":"The final «t» is silent. Hot chocolate is «un chocolat chaud»; the pastry is «un pain au chocolat».","v":"684a87fd"},{"idioma":"fr","id":"fr-p069","tipo":"palavra","fr":"l'hôpital","en":"the hospital","aceitasEn":["hospital","the hospital"],"distratoresEn":["the hotel","the hospice","the guest","the post office"],"nivel":"A1","tags":["saúde","cidade"],"notaEn":"The circumflex marks a lost «s»: «hospital» became «hôpital». Same in «forêt» (forest) and «fête» (feast).","v":"477ec586"},{"idioma":"fr","id":"fr-p070","tipo":"palavra","fr":"tout","aceitasFr":["toute","tous","toutes"],"en":"all / every","aceitasEn":["all","every","everything","whole"],"distratoresEn":["so much / so many","other / another","none / no","few / little"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Four forms: «tout», «toute», «tous», «toutes». Alone, it means everything: «c'est tout», that's all.","v":"65a6e1ba"},{"idioma":"fr","id":"fr-p071","tipo":"palavra","fr":"rentrer","en":"to go back (home)","aceitasEn":["to go back","to go home","to come home","to come back","to get home","to return"],"distratoresEn":["to go in (somewhere)","to yield (a profit)","to withdraw (take out)","to go out (of the house)"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"To go back home, or back inside. It takes «être» in the passé composé: «je suis rentré tard», I got home late.","v":"60a5f752"},{"idioma":"fr","id":"fr-p072","tipo":"palavra","fr":"le voisin","aceitasFr":["la voisine"],"en":"the neighbor","aceitasEn":["neighbor","the neighbor","the neighbour","neighbour"],"distratoresEn":["the visitor","the poison","the cousin","the colleague"],"nivel":"A1","tags":["casa","social"],"notaEn":"Feminine «la voisine». The neighborhood is «le quartier».","v":"212136c4"},{"idioma":"fr","id":"fr-p073","tipo":"palavra","fr":"jouer","en":"to play","aceitasEn":["to play","play"],"distratoresEn":["to judge","to join","to swear","to roll"],"nivel":"A1","tags":["verbo"],"notaEn":"To play games («jouer au foot», with «à») or instruments («jouer du piano», with «de»).","v":"e0a4644c"},{"idioma":"fr","id":"fr-p074","tipo":"palavra","fr":"meilleur","aceitasFr":["meilleure"],"en":"better / best","aceitasEn":["better","best","the best"],"distratoresEn":["bigger / biggest","smaller / smallest","worse / worst","more / most"],"nivel":"A1","tags":["adjetivo"],"notaEn":"The adjective: «un meilleur prix», a better price. The adverb, better with verbs, is «mieux»: «ça va mieux», things are better.","v":"86232186"},{"idioma":"fr","id":"fr-p075","tipo":"palavra","fr":"acheter","en":"to buy","aceitasEn":["to buy","buy","to purchase"],"distratoresEn":["to find","to accept","to guess right","to sell"],"nivel":"A1","tags":["verbo","compras"],"notaEn":"It takes a grave accent before a silent ending: «j'achète», but «nous achetons». To find is «trouver».","v":"7a6fdc72"},{"idioma":"fr","id":"fr-p076","tipo":"palavra","fr":"lire","en":"to read","aceitasEn":["to read","read"],"distratoresEn":["to laugh","to tie","to free","to write"],"nivel":"A1","tags":["verbo","escola"],"notaEn":"Irregular: je lis, il lit, nous lisons, ils lisent; past participle «lu». To laugh is «rire».","v":"dfbdb944"},{"idioma":"fr","id":"fr-p077","tipo":"palavra","fr":"la panne","en":"the breakdown","aceitasEn":["breakdown","the breakdown","failure","the failure"],"distratoresEn":["the pity","the pan","the pause","the part"],"nivel":"A2","tags":["cidade","tecnologia"],"notaEn":"«En panne», broken down, out of order: for cars, elevators, machines. A power outage is «la panne de courant».","v":"a306c5d3"},{"idioma":"fr","id":"fr-p078","tipo":"palavra","fr":"le frère","en":"the brother","aceitasEn":["brother","the brother"],"distratoresEn":["the brake","the freight","the cousin","the son"],"nivel":"A1","tags":["família"],"notaEn":"Big brother, «le grand frère»; little brother, «le petit frère».","v":"3b9845ad"},{"idioma":"fr","id":"fr-p079","tipo":"palavra","fr":"l'appartement","en":"the apartment","aceitasEn":["apartment","the apartment","the flat","flat"],"distratoresEn":["the device","the office","the closet","the chamber"],"nivel":"A1","tags":["casa"],"notaEn":"Masculine. Double «p»: «appartement».","v":"bf69ca4f"},{"idioma":"fr","id":"fr-p080","tipo":"palavra","fr":"froid","aceitasFr":["froide","le froid"],"en":"cold","aceitasEn":["cold","the cold"],"distratoresEn":["weak","fried","strong","cool"],"nivel":"A1","tags":["adjetivo","natureza"],"notaEn":"Feminine «froide». Weather takes «faire»: «il fait froid»; people take «avoir»: «j'ai froid», I'm cold.","v":"19a4871d"},{"idioma":"fr","id":"fr-p081","tipo":"palavra","fr":"anglais","aceitasFr":["anglaise","l'anglais"],"en":"English","aceitasEn":["english"],"distratoresEn":["Angolan","German","Spanish","French"],"nivel":"A1","tags":["adjetivo","cultura"],"notaEn":"Adjective and language, lowercase: «parler anglais». The people are capitalized: «les Anglais».","v":"981c1da3"},{"idioma":"fr","id":"fr-p082","tipo":"palavra","fr":"devoir","en":"must / to have to","aceitasEn":["must","to have to","have to","to owe","owe"],"distratoresEn":["to leave / to drop","to hurt / to ache","to give / to hand","to doubt / to hesitate"],"nivel":"A1","tags":["verbo"],"notaEn":"Obligation and debt: «je dois partir» (I have to go), «je te dois dix euros» (I owe you ten euros). Forms: je dois, nous devons, ils doivent; participle «dû».","v":"2e752405"},{"idioma":"fr","id":"fr-p083","tipo":"palavra","fr":"partir","en":"to leave","aceitasEn":["to leave","leave","to go away","to depart"],"distratoresEn":["to share","to stop","to jump","to lose"],"nivel":"A1","tags":["verbo","viagem","falso-amigo"],"notaEn":"To leave, set off: «je pars demain», I'm leaving tomorrow. To share is «partager». It takes «être» in the passé composé: «elle est partie».","v":"e2ef6cc0"},{"idioma":"fr","id":"fr-p084","tipo":"palavra","fr":"le lundi","aceitasFr":["lundi"],"en":"Monday","aceitasEn":["monday"],"distratoresEn":["Tuesday","Friday","Wednesday","Thursday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Moon day. Without an article it's one Monday: «lundi», on Monday. With one, every Monday: «le lundi». Lowercase.","v":"ea938997"},{"idioma":"fr","id":"fr-p085","tipo":"palavra","fr":"le retard","en":"the delay","aceitasEn":["delay","the delay","lateness"],"distratoresEn":["the portrait","the return","the message","the rest"],"nivel":"A2","tags":["cotidiano","viagem"],"notaEn":"«Être en retard», to be late; «le train a du retard», the train is delayed.","v":"edade308"},{"idioma":"fr","id":"fr-p086","tipo":"palavra","fr":"la faim","en":"hunger","aceitasEn":["hunger","the hunger"],"distratoresEn":["fame","faith","fever","thirst"],"nivel":"A1","tags":["comida","corpo"],"notaEn":"It sounds like «la fin» (the end). With «avoir» and no article: «j'ai faim», I'm hungry.","v":"09db4cd0"},{"idioma":"fr","id":"fr-p087","tipo":"palavra","fr":"la plage","en":"the beach","aceitasEn":["beach","the beach"],"distratoresEn":["the plague","the page","the plate","the pool"],"nivel":"A1","tags":["viagem","natureza"],"notaEn":"Feminine. «À la plage», at the beach. A page is «la page».","v":"f9886c74"},{"idioma":"fr","id":"fr-p088","tipo":"palavra","fr":"la cuisine","en":"kitchen / cooking","aceitasEn":["kitchen","the kitchen","cooking","cuisine"],"distratoresEn":["curtain / drape","cook / chef","living room / lounge","laundry / washroom"],"nivel":"A1","tags":["casa","comida"],"notaEn":"Both the room and the cooking: «la cuisine française». To cook is «faire la cuisine».","v":"23a542ff"},{"idioma":"fr","id":"fr-p089","tipo":"palavra","fr":"le train","en":"the train","aceitasEn":["train","the train"],"distratoresEn":["the rail","the training","the suit","the wheat"],"nivel":"A1","tags":["viagem"],"notaEn":"«En train de» + infinitive means in the middle of doing: «je suis en train de manger», I'm eating right now.","v":"97a2c251"},{"idioma":"fr","id":"fr-p090","tipo":"palavra","fr":"le chien","en":"the dog","aceitasEn":["dog","the dog"],"distratoresEn":["the cat","the smell","the boss","the duck"],"nivel":"A1","tags":["animais"],"notaEn":"Feminine «la chienne». A cat is «le chat».","v":"44736268"},{"idioma":"fr","id":"fr-p091","tipo":"palavra","fr":"la réponse","en":"the answer","aceitasEn":["answer","the answer","the reply","the response"],"distratoresEn":["the question","the rent","the reservation","the refusal"],"nivel":"A1","tags":["escola"],"notaEn":"To answer is «répondre». A question is «la question».","v":"3783e2bc"},{"idioma":"fr","id":"fr-p092","tipo":"palavra","fr":"la mer","en":"the sea","aceitasEn":["sea","the sea","the ocean"],"distratoresEn":["the river","the lake","the month","the pier"],"nivel":"A1","tags":["natureza","viagem"],"notaEn":"Feminine in French, and it sounds just like «la mère» (the mother). «Au bord de la mer», at the seaside.","v":"040e3f11"},{"idioma":"fr","id":"fr-p093","tipo":"palavra","fr":"le vin","en":"wine","aceitasEn":["wine","the wine"],"distratoresEn":["vinegar","wind","soda","wicker"],"nivel":"A1","tags":["comida"],"notaEn":"«Vin rouge», red; «vin blanc», white. It sounds like «vingt» (twenty).","v":"9ee834b7"},{"idioma":"fr","id":"fr-p094","tipo":"palavra","fr":"trois","en":"three","aceitasEn":["three","3"],"distratoresEn":["thirteen","thirty","two","six"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «s» is heard only before a vowel: «trois amis», «trwah-zah-MEE». Don't mix it up with «très», very.","v":"01781a3c"},{"idioma":"fr","id":"fr-p095","tipo":"palavra","fr":"la langue","en":"language / tongue","aceitasEn":["language","tongue","the language","the tongue"],"distratoresEn":["firewood / logs","spear / lance","moon / moonlight","glove / mitten"],"nivel":"A1","tags":["escola","corpo"],"notaEn":"Both a language and the tongue in your mouth. «Ma langue maternelle», my mother tongue.","v":"9008f4a9"},{"idioma":"fr","id":"fr-p096","tipo":"palavra","fr":"la pomme","en":"the apple","aceitasEn":["apple","the apple"],"distratoresEn":["the ointment","the plum","the pear","the dove"],"nivel":"A1","tags":["comida"],"notaEn":"A potato is «la pomme de terre», literally earth apple; fries are «les frites».","v":"0b7f78f9"},{"idioma":"fr","id":"fr-p097","tipo":"palavra","fr":"le cinéma","en":"the movie theater","aceitasEn":["movie theater","the movie theater","the movies","movies","cinema","the cinema"],"distratoresEn":["the theater","the museum","the circus","the stage"],"nivel":"A1","tags":["cultura","cidade"],"notaEn":"«Aller au cinéma», to go to the movies. Casually, «le ciné».","v":"aea2a93e"},{"idioma":"fr","id":"fr-p098","tipo":"palavra","fr":"le restaurant","en":"the restaurant","aceitasEn":["restaurant","the restaurant"],"distratoresEn":["the rest","the market","the hotel","the bar"],"nivel":"A1","tags":["comida","cidade"],"notaEn":"English took the word as is; in French the final «t» is silent.","v":"872f063c"},{"idioma":"fr","id":"fr-p099","tipo":"palavra","fr":"génial","aceitasFr":["géniale"],"en":"great","aceitasEn":["great","brilliant","awesome","fantastic"],"distratoresEn":["kind","general","frozen","genuine"],"nivel":"A2","tags":["adjetivo","gíria"],"notaEn":"In conversation, great or awesome: «c'est génial !». Kind is «gentil».","v":"c29c095c"},{"idioma":"fr","id":"fr-p100","tipo":"palavra","fr":"le film","en":"the movie","aceitasEn":["movie","the movie","film","the film"],"distratoresEn":["the son","the thread","the end","the book"],"nivel":"A1","tags":["cultura"],"notaEn":"The thread is «le fil»; the end, «la fin»; the son, «le fils».","v":"6520086d"},{"idioma":"fr","id":"fr-p101","tipo":"palavra","fr":"le métro","en":"the subway","aceitasEn":["subway","the subway","the metro","metro","the underground","the tube"],"distratoresEn":["the train","the streetcar","the tunnel","the bus"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"«Prendre le métro», to take the subway. A station is «la station de métro».","v":"67f2943c"},{"idioma":"fr","id":"fr-p102","tipo":"palavra","fr":"la peur","en":"fear","aceitasEn":["fear","the fear","fright"],"distratoresEn":["hair","danger","weight","modesty"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine in French. With «avoir» and no article: «j'ai peur», I'm scared. «Avoir peur de», to be afraid of.","v":"6e2445fa"},{"idioma":"fr","id":"fr-p103","tipo":"palavra","fr":"le père","en":"the father","aceitasEn":["father","the father","dad","the dad"],"distratoresEn":["the turkey","the forgiveness","the grandfather","the uncle"],"nivel":"A1","tags":["família"],"notaEn":"Dad is «papa». Parents, mother and father, are «les parents».","v":"1a2ea87f"},{"idioma":"fr","id":"fr-p104","tipo":"palavra","fr":"la sœur","en":"the sister","aceitasEn":["sister","the sister"],"distratoresEn":["the luck","the lady","the cousin","the daughter"],"nivel":"A1","tags":["família"],"notaEn":"Spelled with the «œ» ligature. It also means a nun, like Sister in English.","v":"b82296d8"},{"idioma":"fr","id":"fr-p105","tipo":"palavra","fr":"la famille","en":"the family","aceitasEn":["family","the family"],"distratoresEn":["the row","the fault","the firm","the factory"],"nivel":"A1","tags":["família"],"notaEn":"The «-ille» sounds like «-ee-y»: «fa-MEE-y». «En famille», with the family.","v":"864041ab"},{"idioma":"fr","id":"fr-p106","tipo":"palavra","fr":"l'école","aceitasFr":["une école"],"en":"the school","aceitasEn":["school","the school"],"distratoresEn":["the stairs","the corner","the lock","the church"],"nivel":"A1","tags":["escola"],"notaEn":"Feminine. The initial «é» often marks a lost «s»: school, «école»; state, «état». A church is «l'église».","v":"703526fb"},{"idioma":"fr","id":"fr-p107","tipo":"palavra","fr":"la chambre","en":"the bedroom","aceitasEn":["bedroom","the bedroom","the room","room"],"distratoresEn":["the bed","the kitchen","the living room","the office"],"nivel":"A1","tags":["casa","viagem"],"notaEn":"A bedroom, or a hotel room. The living room is «le salon»; the bed, «le lit».","v":"2ada2fb5"},{"idioma":"fr","id":"fr-p108","tipo":"palavra","fr":"sortir","en":"to go out","aceitasEn":["to go out","go out","to get out","to come out"],"distratoresEn":["to draw lots","to have an effect","to go up","to go in"],"nivel":"A1","tags":["verbo","cidade"],"notaEn":"To go out of a place, or out for fun: «on sort ce soir ?». It takes «être»: «je suis sorti». The exit is «la sortie».","v":"76d1cf67"},{"idioma":"fr","id":"fr-p109","tipo":"palavra","fr":"dormir","en":"to sleep","aceitasEn":["to sleep","sleep"],"distratoresEn":["to dwell","to last","to tame","to wake up"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"Irregular singular: je dors, tu dors, il dort; regular plural: nous dormons.","v":"6d018eef"},{"idioma":"fr","id":"fr-p110","tipo":"palavra","fr":"comprendre","en":"to understand","aceitasEn":["to understand","understand"],"distratoresEn":["to buy","to arrest","to learn","to complete"],"nivel":"A1","tags":["verbo","escola"],"notaEn":"Conjugated like «prendre»: je comprends, nous comprenons; participle «compris». «Compris !», got it!","v":"4b957ad8"},{"idioma":"fr","id":"fr-p111","tipo":"palavra","fr":"aider","en":"to help","aceitasEn":["to help","help"],"distratoresEn":["to postpone","to hate","to act","to wait"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb, taking a direct object: «aider quelqu'un», to help someone. Help, the noun, is «l'aide».","v":"d54d0848"},{"idioma":"fr","id":"fr-p112","tipo":"palavra","fr":"chaud","aceitasFr":["chaude","le chaud"],"en":"hot / warm","aceitasEn":["hot","warm"],"distratoresEn":["flat / dull","dear / pricey","lukewarm / tepid","cold / chilly"],"nivel":"A1","tags":["adjetivo","natureza"],"notaEn":"Feminine «chaude». Weather: «il fait chaud», it's hot; people: «j'ai chaud», I'm hot.","v":"9ff016c9"},{"idioma":"fr","id":"fr-p113","tipo":"palavra","fr":"fatigué","aceitasFr":["fatiguée"],"en":"tired","aceitasEn":["tired","exhausted","weary"],"distratoresEn":["sliced","starving","furious","injured"],"nivel":"A1","tags":["adjetivo","saúde"],"notaEn":"Feminine «fatiguée»; it sounds the same. «Je suis fatigué», I'm tired.","v":"26222f99"},{"idioma":"fr","id":"fr-p114","tipo":"palavra","fr":"souvent","en":"often","aceitasEn":["often","frequently"],"distratoresEn":["rarely","sometimes","never again","again"],"nivel":"A1","tags":["cotidiano"],"notaEn":"It goes after the verb: «je vais souvent au cinéma», I often go to the movies. Sometimes is «parfois».","v":"83b5f1d1"},{"idioma":"fr","id":"fr-u068","tipo":"frase","requer":"fr-p088","fr":"Elle est dans la cuisine.","aceitasFr":["Elle est à la cuisine."],"en":"She's in the kitchen.","aceitasEn":["shes in the kitchen","she is in the kitchen"],"distratoresEn":["She's in the living room.","She's on the balcony.","She's in the garage.","She's in the laundry room."],"nivel":"A1","tags":["casa"],"notaEn":"«Dans», inside: «dans la cuisine», in the kitchen («à la cuisine» is also heard). The same word means cooking or cuisine: «la cuisine française».","requerTodas":["fr-p001","fr-p088"],"v":"00760b7f"},{"idioma":"fr","id":"fr-u069","tipo":"frase","requer":"fr-p103","fr":"Mon père fait la cuisine.","en":"My father does the cooking.","aceitasEn":["my father does the cooking","my dad does the cooking","my father cooks","my dad cooks"],"distratoresEn":["My father does the cleaning.","My father does the laundry.","My father does the shopping.","My father does the ironing."],"nivel":"A1","tags":["família","casa","comida"],"notaEn":"To cook is «faire la cuisine»: «la cuisine» is both the kitchen and the cooking. Dad, in conversation, is «papa».","requerTodas":["fr-p103","fr-p004","fr-p088"],"v":"119bcc10"},{"idioma":"fr","id":"fr-u070","tipo":"frase","requer":"fr-p104","fr":"J'ai deux sœurs.","en":"I have two sisters.","aceitasEn":["i have two sisters","ive got two sisters","i have got two sisters","i have 2 sisters"],"distratoresEn":["I have two daughters.","I have two cousins.","I have two aunts.","I have two nieces."],"nivel":"A1","tags":["família"],"notaEn":"«Sœur» is written with the joined «œ». The «x» of «deux» is silent except before a vowel: «deux amis», «duh-zah-MEE».","requerTodas":["fr-p002","fr-p120","fr-p104"],"v":"4ede65f9"},{"idioma":"fr","id":"fr-u071","tipo":"frase","requer":"fr-p105","fr":"Ma famille habite à Lyon.","en":"My family lives in Lyon.","aceitasEn":["my family lives in lyon"],"distratoresEn":["My sister lives in Lyon.","My aunt lives in Lyon.","My grandmother lives in Lyon.","My cousin lives in Lyon."],"nivel":"A1","tags":["família","casa"],"notaEn":"«Ma famille», with the feminine possessive. The «-ille» ending sounds like «-ee-y»: «fa-MEE-y». The verb is singular, as in English.","requerTodas":["fr-p105","fr-p016"],"v":"7a488721"},{"idioma":"fr","id":"fr-u072","tipo":"frase","requer":"fr-p106","fr":"Les enfants sont à l'école.","en":"The children are at school.","aceitasEn":["the children are at school","the kids are at school","the children are in school","the kids are in school"],"distratoresEn":["The children are at the beach.","The children are at church.","The children are at the pool.","The children are at daycare."],"nivel":"A1","tags":["escola","família"],"notaEn":"At school is «à l'école», with «à». «École» is feminine; before a vowel the article shrinks to «l'».","requerTodas":["fr-p023","fr-p001","fr-p106"],"v":"b8f92d6f"},{"idioma":"fr","id":"fr-u073","tipo":"frase","requer":"fr-p107","fr":"Ma chambre est très petite.","en":"My bedroom is very small.","aceitasEn":["my bedroom is very small","my room is very small","my bedroom is really small","my room is really small","my bedroom is tiny","my room is tiny"],"distratoresEn":["My bathroom is very small.","My office is very small.","My garden is very small.","My hallway is very small."],"nivel":"A1","tags":["casa"],"notaEn":"«Chambre» is feminine: «ma chambre», «petite». It's a bedroom, or a hotel room — the old English «chamber».","requerTodas":["fr-p107","fr-p001","fr-p043","fr-p038"],"v":"7aac5ca2"},{"idioma":"fr","id":"fr-u074","tipo":"frase","requer":"fr-p108","fr":"On sort ce soir ?","en":"Shall we go out tonight?","aceitasEn":["shall we go out tonight","should we go out tonight","do you want to go out tonight","want to go out tonight","lets go out tonight","are we going out tonight"],"distratoresEn":["Shall we have dinner tonight?","Shall we go dancing tonight?","Shall we work out tonight?","Shall we study tonight?"],"nivel":"A1","tags":["social","cidade"],"notaEn":"«Sortir» on its own means to go out and have fun. «Ce soir» is tonight: «le soir» is the evening, «la nuit» the night you sleep through.","requerTodas":["fr-p108","fr-p160"],"v":"4a723680"},{"idioma":"fr","id":"fr-u075","tipo":"frase","requer":"fr-p108","fr":"Je sors du travail à six heures.","en":"I leave work at six.","aceitasEn":["i leave work at six","i leave work at 6","i get off work at six","i get out of work at six","i finish work at six"],"distratoresEn":["I get to work at six.","I start work at six.","I have dinner at work at six.","I'm at work at six."],"nivel":"A1","tags":["trabalho","cotidiano"],"notaEn":"Leaving a place is «sortir de»; «du» is «de» + «le». Clock times need «heures»: «à six heures», at six (o'clock).","requerTodas":["fr-p108","fr-p029","fr-p179","fr-p129"],"v":"1a313285"},{"idioma":"fr","id":"fr-u076","tipo":"frase","requer":"fr-p109","fr":"Tu as bien dormi ?","aceitasFr":["Vous avez bien dormi ?"],"en":"Did you sleep well?","aceitasEn":["did you sleep well","did you sleep ok","did you sleep alright","have you slept well"],"distratoresEn":["Did you eat well?","Did you have a good dinner?","Did you have a good trip?","Did you get there safely?"],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"The participle of «dormir» is «dormi». In the passé composé, «bien» sits between the helper verb and the participle: «tu as bien dormi».","requerTodas":["fr-p002","fr-p044","fr-p109"],"v":"275bdda3"},{"idioma":"fr","id":"fr-u077","tipo":"frase","requer":"fr-p110","fr":"Je n'ai pas compris la question.","aceitasFr":["J'ai pas compris la question."],"en":"I didn't understand the question.","aceitasEn":["i didnt understand the question","i did not understand the question","i didnt get the question"],"distratoresEn":["I didn't hear the question.","I didn't read the question.","I didn't see the question.","I didn't ask the question."],"nivel":"A1","tags":["escola"],"notaEn":"The participle of «comprendre» is «compris», like «pris» from «prendre». The negation wraps the helper verb: «je n'ai pas compris».","requerTodas":["fr-p002","fr-p110","fr-p140"],"v":"1a4dafc6"},{"idioma":"fr","id":"fr-u078","tipo":"frase","requer":"fr-p111","fr":"Tu peux m'aider ?","aceitasFr":["Vous pouvez m'aider ?","Tu pourrais m'aider ?"],"en":"Can you help me?","aceitasEn":["can you help me","could you help me","will you help me","can you give me a hand"],"distratoresEn":["Can you hear me?","Can you wait for me?","Can you call me?","Can you give me a ride?"],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"«Aider» takes a direct object: «aider quelqu'un». The pronoun goes before the infinitive: «m'aider», help me.","requerTodas":["fr-p006","fr-p111"],"v":"9687d263"},{"idioma":"fr","id":"fr-u079","tipo":"frase","requer":"fr-p112","fr":"J'ai chaud.","en":"I'm hot.","aceitasEn":["im hot","i am hot","im warm","i am warm","i feel hot"],"distratoresEn":["I'm cold.","I'm sleepy.","I'm thirsty.","I'm scared."],"nivel":"A1","tags":["corpo","natureza"],"notaEn":"In French you have heat instead of being hot: «j'ai chaud», «j'ai froid». With «être», «chaud» describes things: «le café est chaud».","requerTodas":["fr-p002","fr-p112"],"v":"763375ff"},{"idioma":"fr","id":"fr-u080","tipo":"frase","requer":"fr-p112","fr":"Le café est trop chaud.","en":"The coffee is too hot.","aceitasEn":["the coffee is too hot","the coffees too hot"],"distratoresEn":["The coffee is too cold.","The coffee is too sweet.","The coffee is too strong.","The coffee is too bitter."],"nivel":"A1","tags":["comida"],"notaEn":"For things, «chaud» is hot; for weather, «il fait chaud», it's hot out. «Trop», too, goes before the adjective.","requerTodas":["fr-p057","fr-p001","fr-p061","fr-p112"],"v":"ac304ae9"},{"idioma":"fr","id":"fr-u081","tipo":"frase","requer":"fr-p113","fr":"Je suis très fatigué.","aceitasFr":["Je suis très fatiguée."],"en":"I'm very tired.","aceitasEn":["im very tired","i am very tired","im really tired","i am really tired","im so tired"],"distratoresEn":["I'm very busy.","I'm very sick.","I'm very nervous.","I'm very bored."],"nivel":"A1","tags":["saúde","cotidiano"],"notaEn":"A woman writes «fatiguée», pronounced the same. Think of English fatigue.","requerTodas":["fr-p001","fr-p043","fr-p113"],"v":"9f20e841"},{"idioma":"fr","id":"fr-u082","tipo":"frase","requer":"fr-p114","fr":"Je vais souvent au cinéma.","en":"I often go to the movies.","aceitasEn":["i often go to the movies","i go to the movies often","i go to the movies a lot","i often go to the cinema","i go to the cinema a lot","i frequently go to the movies"],"distratoresEn":["I rarely go to the movies.","I sometimes go to the movies.","I hardly ever go to the movies.","I never go to the movies."],"nivel":"A1","tags":["cultura","cotidiano"],"notaEn":"«Souvent» comes right after the verb: «je vais souvent». Sometimes is «parfois»; rarely, «rarement».","requerTodas":["fr-p003","fr-p114","fr-p097"],"v":"666916f4"},{"idioma":"fr","id":"fr-u083","tipo":"frase","requer":"fr-p002","fr":"J'ai besoin de dormir.","en":"I need to sleep.","aceitasEn":["i need to sleep","i need some sleep","i need sleep","i need to get some sleep"],"distratoresEn":["I want to sleep.","I'm going to sleep.","I'm trying to sleep.","I like sleeping."],"nivel":"A1","tags":["cotidiano","gramática"],"notaEn":"To need is «avoir besoin de», literally to have need of: «j'ai besoin de toi», I need you; «j'ai besoin d'un café».","requerTodas":["fr-p002","fr-p146","fr-p109"],"v":"de40a7e4"},{"idioma":"fr","id":"fr-u084","tipo":"frase","requer":"fr-p002","fr":"J'ai mal à la tête.","en":"I have a headache.","aceitasEn":["i have a headache","ive got a headache","i have got a headache","my head hurts"],"distratoresEn":["I have a toothache.","I have a stomachache.","I have a sore throat.","I have an earache."],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"Pain is something you have: «avoir mal à» + the body part, with the article. «J'ai mal au dos», my back hurts; «j'ai mal aux dents», I have a toothache.","requerTodas":["fr-p002","fr-p151","fr-p144"],"v":"ed1231af"},{"idioma":"fr","id":"fr-u085","tipo":"frase","requer":"fr-p001","fr":"Nous sommes brésiliens.","aceitasFr":["Nous sommes brésiliennes.","On est brésiliens."],"en":"We're Brazilian.","aceitasEn":["were brazilian","we are brazilian","were from brazil","we are from brazil"],"distratoresEn":["We're Argentinian.","We're Portuguese.","We're Italian.","We're Chilean."],"nivel":"A1","tags":["social","cultura"],"notaEn":"Unlike English, the nationality adjective is lowercase: «nous sommes brésiliens». Capitalized, it's the people: «les Brésiliens».","requerTodas":["fr-p001","fr-p116"],"v":"49d50d43"},{"idioma":"fr","id":"fr-u086","tipo":"frase","requer":"fr-p001","fr":"Elle est médecin.","en":"She's a doctor.","aceitasEn":["shes a doctor","she is a doctor","shes a physician"],"distratoresEn":["She's a nurse.","She's a teacher.","She's a lawyer.","She's a dentist."],"nivel":"A1","tags":["profissões","saúde"],"notaEn":"After «être», a profession takes no article: «elle est médecin», she's a doctor. «Médecin» is used for men and women alike.","requerTodas":["fr-p001","fr-p155"],"v":"35090bd0"},{"idioma":"fr","id":"fr-u087","tipo":"frase","requer":"fr-p003","fr":"Je vais au travail à pied.","en":"I walk to work.","aceitasEn":["i walk to work","i go to work on foot","im walking to work"],"distratoresEn":["I drive to work.","I take the bus to work.","I bike to work.","I take the subway to work."],"nivel":"A1","tags":["cidade","trabalho"],"notaEn":"On foot is «à pied»; by car or bus, «en voiture», «en bus». In «le pied», the foot, the «d» is silent.","requerTodas":["fr-p003","fr-p029","fr-p158"],"v":"68876c47"},{"idioma":"fr","id":"fr-u088","tipo":"frase","requer":"fr-p003","fr":"Cette robe te va bien.","en":"That dress looks good on you.","aceitasEn":["that dress looks good on you","this dress looks good on you","that dress looks nice on you","that dress looks great on you","that dress suits you"],"distratoresEn":["That coat looks good on you.","That hat looks good on you.","That suit looks good on you.","That haircut looks good on you."],"nivel":"A2","tags":["roupa","falso-amigo"],"notaEn":"«Aller bien à quelqu'un» is to suit someone. «La robe» is a dress; a bathrobe is «le peignoir».","requerTodas":["fr-p142","fr-p003","fr-p044"],"v":"ba7f6e9c"},{"idioma":"fr","id":"fr-u089","tipo":"frase","requer":"fr-p003","fr":"Je vais chez le médecin.","en":"I'm going to the doctor.","aceitasEn":["im going to the doctor","i am going to the doctor","im going to the doctors","im going to see the doctor","i go to the doctor"],"distratoresEn":["I'm going to the dentist.","I'm going to the bank.","I'm going to the hairdresser.","I'm going to the market."],"nivel":"A1","tags":["saúde","cidade"],"notaEn":"To someone's place or office you go «chez»: «chez le médecin», «chez moi», «chez Paul». To a place, «à»: «à la banque».","requerTodas":["fr-p003","fr-p155"],"v":"6e8a1662"},{"idioma":"fr","id":"fr-u090","tipo":"frase","requer":"fr-p004","fr":"Fais attention !","aceitasFr":["Faites attention !"],"en":"Be careful!","aceitasEn":["be careful","careful","watch out","look out","pay attention"],"distratoresEn":["Stay calm!","Be patient!","Keep still!","Don't worry!"],"nivel":"A1","tags":["cotidiano","expressão"],"notaEn":"Literally «make attention»: it covers both be careful and pay attention. «Fais» is the «tu» form; «faites», the «vous» form.","requerTodas":["fr-p004","fr-p127"],"v":"b13810d0"},{"idioma":"fr","id":"fr-u091","tipo":"frase","requer":"fr-p004","fr":"Je fais les courses le samedi.","en":"I do the shopping on Saturdays.","aceitasEn":["i do the shopping on saturdays","i do the shopping on saturday","i do the grocery shopping on saturdays","i go grocery shopping on saturdays","i do my shopping on saturdays"],"distratoresEn":["I do the cleaning on Saturdays.","I make lunch on Saturdays.","I work out on Saturdays.","I do my nails on Saturdays."],"nivel":"A1","tags":["compras","cotidiano"],"notaEn":"«Faire les courses» is the everyday grocery shopping. «Le samedi», with the article, means every Saturday; «samedi» alone, a single Saturday.","requerTodas":["fr-p004","fr-p162","fr-p159"],"v":"92649ff2"},{"idioma":"fr","id":"fr-u092","tipo":"frase","requer":"fr-p004","fr":"Je fais la vaisselle.","en":"I do the dishes.","aceitasEn":["i do the dishes","i wash the dishes","im doing the dishes","i do the washing up","i wash up"],"distratoresEn":["I dry the dishes.","I do the laundry.","I put away the dishes.","I mop the floor."],"nivel":"A1","tags":["casa"],"notaEn":"«La vaisselle» is the dishes, and «faire la vaisselle» is doing them. Laundry is «faire la lessive».","requerTodas":["fr-p004","fr-p145"],"v":"2900f08b"},{"idioma":"fr","id":"fr-u093","tipo":"frase","requer":"fr-p011","fr":"Je prends une douche le matin.","en":"I shower in the morning.","aceitasEn":["i shower in the morning","i shower in the mornings","i take a shower in the morning","i have a shower in the morning"],"distratoresEn":["I have breakfast in the morning.","I sunbathe in the morning.","I take my medicine in the morning.","I drink tea in the morning."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"You «take» a shower with «prendre»: «prendre une douche»; a bath, «prendre un bain». «Le matin», with the article, means in the mornings.","requerTodas":["fr-p011","fr-p134","fr-p153"],"v":"5741c8ee"},{"idioma":"fr","id":"fr-u094","tipo":"frase","requer":"fr-p011","fr":"On prend le petit déjeuner à huit heures.","aceitasFr":["Nous prenons le petit déjeuner à huit heures.","On prend le petit-déjeuner à huit heures."],"en":"We have breakfast at eight.","aceitasEn":["we have breakfast at eight","we have breakfast at 8","we eat breakfast at eight","we have breakfast at eight oclock"],"distratoresEn":["We have lunch at eight.","We have dinner at eight.","We have a snack at eight.","We have a meeting at eight."],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"Breakfast is «le petit déjeuner», literally the little lunch, and you «take» it with «prendre». Lunch is «le déjeuner»; dinner, «le dîner».","requerTodas":["fr-p011","fr-p156","fr-p126","fr-p129"],"v":"45d885e0"},{"idioma":"fr","id":"fr-u095","tipo":"frase","requer":"fr-p010","fr":"Tu as vu mes clés ?","aceitasFr":["Vous avez vu mes clés ?","Tu n'as pas vu mes clés ?"],"en":"Have you seen my keys?","aceitasEn":["have you seen my keys","did you see my keys"],"distratoresEn":["Have you seen my socks?","Have you seen my gloves?","Have you seen my photos?","Have you seen my stuff?"],"nivel":"A1","tags":["casa","objetos"],"notaEn":"«Mes» is the plural of both «mon» and «ma». «La clé» is also spelled «la clef», pronounced the same.","requerTodas":["fr-p002","fr-p010","fr-p133"],"v":"45840dfd"},{"idioma":"fr","id":"fr-u096","tipo":"frase","requer":"fr-p100","fr":"On regarde un film ce soir ?","en":"Shall we watch a movie tonight?","aceitasEn":["shall we watch a movie tonight","should we watch a movie tonight","do you want to watch a movie tonight","want to watch a movie tonight","lets watch a movie tonight","shall we watch a film tonight"],"distratoresEn":["Shall we watch a game tonight?","Shall we watch a show tonight?","Shall we watch a documentary tonight?","Shall we watch cartoons tonight?"],"nivel":"A1","tags":["cultura","social"],"notaEn":"«Regarder» is to watch or look at; «voir» is to see. Films and TV are «regardés», though «voir un film» is common too, especially at the cinema.","requerTodas":["fr-p172","fr-p100","fr-p160"],"v":"c651e3c9"},{"idioma":"fr","id":"fr-u097","tipo":"frase","requer":"fr-p005","fr":"Qu'est-ce que tu as dit ?","aceitasFr":["Tu as dit quoi ?","Qu'est-ce que vous avez dit ?"],"en":"What did you say?","aceitasEn":["what did you say","what have you said"],"distratoresEn":["What did you do?","What did you see?","What did you eat?","What did you buy?"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The participle of «dire» is «dit», silent «t». To ask someone to repeat, «Pardon ?» or «Comment ?» is enough.","requerTodas":["fr-p002","fr-p005"],"v":"d44ed43a"},{"idioma":"fr","id":"fr-u098","tipo":"frase","requer":"fr-p005","fr":"Je vais le dire à mon frère.","en":"I'm going to tell my brother.","aceitasEn":["im going to tell my brother","i am going to tell my brother","im gonna tell my brother","ill tell my brother","i will tell my brother"],"distratoresEn":["I'm going to tell my father.","I'm going to tell my cousin.","I'm going to tell my boss.","I'm going to tell my neighbor."],"nivel":"A1","tags":["família"],"notaEn":"You say something «à» someone: «dire quelque chose à quelqu'un», to tell someone something. «Le» (it) goes before the infinitive.","requerTodas":["fr-p003","fr-p005","fr-p078"],"v":"cbf424cc"},{"idioma":"fr","id":"fr-u099","tipo":"frase","requer":"fr-p009","fr":"Je viens d'arriver.","en":"I just arrived.","aceitasEn":["i just arrived","ive just arrived","i have just arrived","i just got here","ive just got here","i just got in"],"distratoresEn":["I'm arriving.","I'll be there soon.","I arrived a long time ago.","I haven't arrived yet."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Venir de» + infinitive is the recent past: «je viens d'arriver», I've just arrived. Nobody is coming from anywhere.","requerTodas":["fr-p009","fr-p115"],"v":"6142cce6"},{"idioma":"fr","id":"fr-u100","tipo":"frase","requer":"fr-p104","fr":"Je ne connais pas sa sœur.","aceitasFr":["Je connais pas sa sœur."],"en":"I don't know his sister.","aceitasEn":["i dont know his sister","i dont know her sister","i do not know his sister","i do not know her sister","ive never met his sister","ive never met her sister"],"distratoresEn":["I don't know his mother.","I don't know his daughter.","I don't know his wife.","I don't know his girlfriend."],"nivel":"A1","tags":["família","social"],"notaEn":"People and places take «connaître»: «je connais Paris». Facts and skills take «savoir»: «je sais nager». «Sa sœur» can be his or her sister.","requerTodas":["fr-p119","fr-p104"],"v":"1fdbdcd6"},{"idioma":"fr","id":"fr-u101","tipo":"frase","requer":"fr-p006","fr":"Je peux payer par carte ?","aceitasFr":["Est-ce que je peux payer par carte ?","Je peux payer avec la carte ?","Je peux payer par carte bancaire ?"],"en":"Can I pay by card?","aceitasEn":["can i pay by card","can i pay with a card","can i pay with card","can i pay by credit card","could i pay by card","do you take cards"],"distratoresEn":["Can I pay in cash?","Can I pay by check?","Can I pay in dollars?","Can I pay in euros?"],"nivel":"A1","tags":["compras"],"notaEn":"You pay «par carte» or «en espèces», in cash. «La carte» is also a map and a menu.","requerTodas":["fr-p006","fr-p170","fr-p131"],"v":"ce7f93a7"},{"idioma":"fr","id":"fr-u102","tipo":"frase","requer":"fr-p082","fr":"Il doit être malade.","en":"He must be sick.","aceitasEn":["he must be sick","he must be ill","he must be unwell","hes probably sick","he is probably sick"],"distratoresEn":["He's going to get sick.","He was sick.","He isn't sick.","He's pretending to be sick."],"nivel":"A2","tags":["gramática","saúde"],"notaEn":"«Devoir» also expresses a guess, just like must: «il doit être malade». Only context separates it from have to.","requerTodas":["fr-p082","fr-p001","fr-p166"],"v":"4786f3cb"},{"idioma":"fr","id":"fr-u103","tipo":"frase","requer":"fr-p082","fr":"Je te dois dix euros.","aceitasFr":["Je vous dois dix euros."],"en":"I owe you ten euros.","aceitasEn":["i owe you ten euros","i owe you 10 euros"],"distratoresEn":["I'll give you ten euros.","I'll lend you ten euros.","I'll pay you ten euros.","I'll send you ten euros."],"nivel":"A1","tags":["compras","economia"],"notaEn":"With an object, «devoir» means to owe: «je te dois dix euros». The «x» of «dix» sounds like «z» before a vowel: «dix euros», «dee-zuh-ROH».","requerTodas":["fr-p082","fr-p121","fr-p128"],"v":"20e45c61"},{"idioma":"fr","id":"fr-u104","tipo":"frase","requer":"fr-p070","fr":"Tout le monde est là.","en":"Everyone is here.","aceitasEn":["everyone is here","everybody is here","everyones here","everybodys here","everyone is there"],"distratoresEn":["Nobody is here.","Few people are here.","Lots of people are here.","Hardly anyone is here."],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"«Tout le monde» (literally all the world) takes a singular verb. «Là» means there, but in speech it often means here: «je suis là», I'm here.","requerTodas":["fr-p070","fr-p154","fr-p001","fr-p165"],"v":"be7f792f"},{"idioma":"fr","id":"fr-u105","tipo":"frase","requer":"fr-p070","fr":"J'ai tout mangé.","en":"I ate everything.","aceitasEn":["i ate everything","i ate it all","i ate all of it","ive eaten everything","i have eaten everything"],"distratoresEn":["I ate very little.","I ate half.","I ate too much.","I didn't eat anything."],"nivel":"A1","tags":["comida"],"notaEn":"«Tout», everything, sits between the helper verb and the participle, like «déjà» and «bien»: «j'ai tout mangé».","requerTodas":["fr-p002","fr-p070","fr-p013"],"v":"edbc927c"},{"idioma":"fr","id":"fr-u106","tipo":"frase","requer":"fr-p070","fr":"J'ai dormi toute la journée.","en":"I slept all day.","aceitasEn":["i slept all day","i slept all day long","i slept the whole day","ive slept all day","i have slept all day"],"distratoresEn":["I slept all afternoon.","I slept all night.","I slept all Sunday.","I slept the whole flight."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Toute la journée», all day: «tout» agrees with the feminine «journée». «La journée» is the day as lived, start to finish; «le jour», the calendar day.","requerTodas":["fr-p002","fr-p109","fr-p070","fr-p137"],"v":"e7b0d027"},{"idioma":"fr","id":"fr-u107","tipo":"frase","requer":"fr-p067","fr":"Il y a beaucoup de monde.","en":"There are a lot of people.","aceitasEn":["there are a lot of people","there are lots of people","there are many people","theres a lot of people","its crowded","its very crowded"],"distratoresEn":["There are few people.","There's nobody here.","There are too many people.","There's a lot of noise."],"nivel":"A1","tags":["cotidiano","cidade"],"notaEn":"«Le monde» is the world and, in speech, people: «beaucoup de monde», lots of people. After «beaucoup», just «de», no article.","requerTodas":["fr-p002","fr-p067","fr-p154"],"v":"5f861c79"},{"idioma":"fr","id":"fr-u108","tipo":"frase","requer":"fr-p061","fr":"J'ai trop de travail.","en":"I have too much work.","aceitasEn":["i have too much work","ive got too much work","i have got too much work"],"distratoresEn":["I have little work.","I don't have any work.","I have more work.","I have less work."],"nivel":"A1","tags":["trabalho"],"notaEn":"«Trop de», too much, works like «beaucoup de», a lot of: just «de», no article. «Trop» means excess; «beaucoup», just quantity.","requerTodas":["fr-p002","fr-p061","fr-p029"],"v":"19ec4afe"},{"idioma":"fr","id":"fr-u109","tipo":"frase","requer":"fr-p083","fr":"Nous partons en vacances demain.","aceitasFr":["On part en vacances demain.","Demain, nous partons en vacances."],"en":"We're going on vacation tomorrow.","aceitasEn":["were going on vacation tomorrow","we are going on vacation tomorrow","were leaving on vacation tomorrow","we are leaving on vacation tomorrow","were off on vacation tomorrow","were going on holiday tomorrow","we leave on vacation tomorrow"],"distratoresEn":["We're back from vacation tomorrow.","We're leaving home tomorrow.","We're leaving the hotel tomorrow.","We're on vacation tomorrow."],"nivel":"A1","tags":["viagem"],"notaEn":"«Partir en vacances», to go (off) on vacation. «Les vacances» is always plural; «les grandes vacances» is the summer break.","requerTodas":["fr-p083","fr-p163","fr-p059"],"v":"8b571a56"},{"idioma":"fr","id":"fr-u110","tipo":"frase","requer":"fr-p071","fr":"Je suis rentré tard hier.","aceitasFr":["Je suis rentrée tard hier.","Hier, je suis rentré tard."],"en":"I got home late yesterday.","aceitasEn":["i got home late yesterday","i came home late yesterday","i got back late yesterday","i went home late yesterday","yesterday i got home late"],"distratoresEn":["I got home early yesterday.","I got home alone yesterday.","I got home tired yesterday.","I got home soaked yesterday."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"«Rentrer» takes «être» in the passé composé, and a woman writes «rentrée». «Tard» is late; «en retard» is late for something.","requerTodas":["fr-p001","fr-p071","fr-p180","fr-p125"],"v":"8b59c9b6"},{"idioma":"fr","id":"fr-u111","tipo":"frase","requer":"fr-p073","fr":"Il joue au foot.","aceitasFr":["Il joue au football."],"en":"He plays soccer.","aceitasEn":["he plays soccer","he plays football","hes playing soccer","hes playing football"],"distratoresEn":["He plays volleyball.","He plays tennis.","He plays basketball.","He plays chess."],"nivel":"A1","tags":["cotidiano","cultura"],"notaEn":"Games and sports take «jouer à», which fuses with «le» into «au»: «jouer au foot», «jouer aux cartes». Instruments take «de»: «jouer du piano».","requerTodas":["fr-p073","fr-p149"],"v":"5b73fece"},{"idioma":"fr","id":"fr-u112","tipo":"frase","requer":"fr-p073","fr":"Elle joue du piano.","en":"She plays the piano.","aceitasEn":["she plays the piano","she plays piano","shes playing the piano"],"distratoresEn":["She plays the guitar.","She plays the flute.","She plays the drums.","She plays the violin."],"nivel":"A1","tags":["cultura"],"notaEn":"Instruments take «jouer de»: «jouer du piano», «jouer de la guitare». Games take «jouer à».","requerTodas":["fr-p073","fr-p157"],"v":"540825a4"},{"idioma":"fr","id":"fr-u113","tipo":"frase","requer":"fr-p015","fr":"J'aime lire.","en":"I like reading.","aceitasEn":["i like reading","i like to read","i love reading","i love to read","i enjoy reading"],"distratoresEn":["I like writing.","I like swimming.","I like cooking.","I like sleeping."],"nivel":"A1","tags":["escola","cotidiano"],"notaEn":"«Aimer» + bare infinitive: «j'aime lire», I like reading.","requerTodas":["fr-p015","fr-p076"],"v":"3a77876c"},{"idioma":"fr","id":"fr-u114","tipo":"frase","requer":"fr-p007","fr":"Je voudrais réserver une table.","en":"I'd like to book a table.","aceitasEn":["id like to book a table","i would like to book a table","id like to reserve a table","i would like to reserve a table","i want to book a table","i want to reserve a table"],"distratoresEn":["I'd like to book a room.","I'd like to book a taxi.","I'd like to book a meeting room.","I'd like to book a ticket."],"nivel":"A1","tags":["comida","viagem"],"notaEn":"«Je voudrais», the conditional of «vouloir», is the polite I'd like.","requerTodas":["fr-p007","fr-p174","fr-p143"],"v":"82cca79a"},{"idioma":"fr","id":"fr-u115","tipo":"frase","requer":"fr-p007","fr":"Oui, je veux bien.","en":"Yes, please.","aceitasEn":["yes please","yes id love to","yes i would love to","yes id like that","yes thank you"],"distratoresEn":["Yes, I know.","Yes, I'm coming.","No, I'll pass.","Yes, but later."],"nivel":"A2","tags":["social","expressão"],"notaEn":"To accept an offer, «je veux bien» is the polite yes: «bien» softens the «I want». A bare «je veux» would sound blunt.","requerTodas":["fr-p007","fr-p044"],"v":"79b17832"},{"idioma":"fr","id":"fr-u116","tipo":"frase","requer":"fr-p002","fr":"Tu as raison.","aceitasFr":["Vous avez raison."],"en":"You're right.","aceitasEn":["youre right","you are right","youre correct","you are correct"],"distratoresEn":["You're wrong.","You're lucky.","You're in a hurry.","You're scared."],"nivel":"A1","tags":["social"],"notaEn":"In French you have reason: «avoir raison», to be right. Being wrong is also had: «avoir tort».","requerTodas":["fr-p002","fr-p141"],"v":"0e81a211"},{"idioma":"fr","id":"fr-u117","tipo":"frase","requer":"fr-p010","fr":"Ah, je vois.","en":"Oh, I see.","aceitasEn":["oh i see","i see","ah i see","oh i get it","i get it","oh i understand"],"distratoresEn":["Oh, I forgot.","Oh, I remember.","Oh, sorry.","Oh, what a shame."],"nivel":"A1","tags":["cotidiano","expressão"],"notaEn":"«Je vois» works just like English I see: I understand.","requerTodas":["fr-p010"],"v":"a882ad59"},{"idioma":"fr","id":"fr-u118","tipo":"frase","requer":"fr-p018","fr":"J'attends le bus depuis vingt minutes.","en":"I've been waiting for the bus for twenty minutes.","aceitasEn":["ive been waiting for the bus for twenty minutes","i have been waiting for the bus for twenty minutes","ive been waiting for the bus for 20 minutes"],"distratoresEn":["I waited for the bus for twenty minutes.","I'll wait for the bus for twenty minutes.","The bus comes in twenty minutes.","I'll wait for the bus twenty more minutes."],"nivel":"A2","tags":["cidade","gramática"],"notaEn":"«Depuis» + present tense is the French have been doing: «j'attends depuis vingt minutes», and the wait is still going on.","requerTodas":["fr-p018","fr-p060","fr-p051","fr-p139"],"v":"9d47bc9c"},{"idioma":"fr","id":"fr-u119","tipo":"frase","requer":"fr-p023","fr":"Vous avez des enfants ?","aceitasFr":["Tu as des enfants ?","Est-ce que vous avez des enfants ?"],"en":"Do you have children?","aceitasEn":["do you have children","do you have kids","do you have any children","do you have any kids","have you got children","have you got any children"],"distratoresEn":["Do you have siblings?","Do you have grandchildren?","Do you have nephews?","Do you have cousins?"],"nivel":"A1","tags":["família","social"],"notaEn":"«Les enfants» means both children in general and someone's own children, at any age. A son is «le fils».","requerTodas":["fr-p002","fr-p023"],"v":"e145ad65"},{"idioma":"fr","id":"fr-u120","tipo":"frase","requer":"fr-p025","fr":"Je vais à la plage de temps en temps.","en":"I go to the beach from time to time.","aceitasEn":["i go to the beach from time to time","i go to the beach now and then","i go to the beach every now and then","i go to the beach once in a while","i go to the beach sometimes","i sometimes go to the beach"],"distratoresEn":["I go to the beach every weekend.","I go to the beach almost every day.","I only go to the beach in summer.","I go to the beach once a year."],"nivel":"A2","tags":["viagem","expressão"],"notaEn":"«De temps en temps», literally from time in time: now and then. Here «le temps» is time, not weather.","requerTodas":["fr-p003","fr-p087","fr-p025"],"v":"b4f0dd3a"},{"idioma":"fr","id":"fr-u121","tipo":"frase","requer":"fr-p028","fr":"Je vais en ville.","en":"I'm going into town.","aceitasEn":["im going into town","i am going into town","im going to town","im going downtown","i am going downtown","im going into the city","im going to the city center","im going to the city centre"],"distratoresEn":["I'm going to the market.","I'm going to the countryside.","I'm going to the bank.","I'm going to the park."],"nivel":"A1","tags":["cidade"],"notaEn":"«En ville» means into town, downtown. «La ville» is the city or town; a village is «le village».","requerTodas":["fr-p003","fr-p028"],"v":"922d57f4"},{"idioma":"fr","id":"fr-u122","tipo":"frase","requer":"fr-p034","fr":"On y va en voiture ?","en":"Shall we go by car?","aceitasEn":["shall we go by car","should we go by car","shall we drive","should we drive","are we going by car","are we driving","shall we take the car","should we take the car"],"distratoresEn":["Shall we take the bus?","Shall we take a taxi?","Shall we take the subway?","Shall we go by bike?"],"nivel":"A1","tags":["cidade","viagem"],"notaEn":"Vehicles you get into take «en»: «en voiture», «en bus», «en train». On foot and by bike: «à pied», «à vélo». «On y va ?», shall we go?","requerTodas":["fr-p003","fr-p034"],"v":"8262206e"},{"idioma":"fr","id":"fr-u123","tipo":"frase","requer":"fr-p036","fr":"Bonne chance !","en":"Good luck!","aceitasEn":["good luck","best of luck","lots of luck"],"distratoresEn":["Have a good trip!","Have a good week!","Good job!","Have a nice vacation!"],"nivel":"A1","tags":["social","falso-amigo"],"notaEn":"«La chance» is luck: «avoir de la chance», to be lucky. A chance, an opportunity, is «l'occasion».","requerTodas":["fr-p036","fr-p132"],"v":"5819d36d"},{"idioma":"fr","id":"fr-u124","tipo":"frase","requer":"fr-p038","fr":"C'est ma petite sœur.","en":"She's my little sister.","aceitasEn":["shes my little sister","she is my little sister","shes my younger sister","she is my younger sister","shes my baby sister","this is my little sister","this is my younger sister"],"distratoresEn":["She's my big sister.","She's my middle sister.","She's my twin sister.","She's my adopted sister."],"nivel":"A1","tags":["família"],"notaEn":"Between siblings, «petit» means younger and «grand» older: «ma petite sœur», «mon grand frère», at any age.","requerTodas":["fr-p001","fr-p038","fr-p104"],"v":"4ec670ba"},{"idioma":"fr","id":"fr-u125","tipo":"frase","requer":"fr-p045","fr":"Il est aussi grand que son père.","en":"He's as tall as his father.","aceitasEn":["hes as tall as his father","he is as tall as his father","hes as tall as his dad","he is as tall as his dad"],"distratoresEn":["He's taller than his father.","He's shorter than his father.","He's almost as tall as his father.","He's much taller than his father."],"nivel":"A2","tags":["família","gramática"],"notaEn":"Equality: «aussi… que», as… as. More: «plus… que»; less: «moins… que». Here «aussi» doesn't mean also.","requerTodas":["fr-p001","fr-p045","fr-p037","fr-p103"],"v":"20ac8fc5"},{"idioma":"fr","id":"fr-u126","tipo":"frase","requer":"fr-p050","fr":"Tu es déjà allé à Paris ?","aceitasFr":["Tu es déjà allée à Paris ?","Vous êtes déjà allé à Paris ?","Est-ce que tu es déjà allé à Paris ?"],"en":"Have you ever been to Paris?","aceitasEn":["have you ever been to paris","have you been to paris","have you been to paris before","have you ever gone to paris","did you ever go to paris"],"distratoresEn":["Did you go to Paris yesterday?","Do you still go to Paris?","Did you go back to Paris?","Do you want to go to Paris?"],"nivel":"A1","tags":["viagem"],"notaEn":"In a question, «déjà» means ever. «Aller» takes «être» in the passé composé, and a woman writes «allée».","requerTodas":["fr-p001","fr-p050","fr-p003"],"v":"7a7f5f8c"},{"idioma":"fr","id":"fr-u127","tipo":"frase","requer":"fr-p053","fr":"Pas de problème !","en":"No problem!","aceitasEn":["no problem","not a problem","no worries","no prob"],"distratoresEn":["No doubt!","No rush!","No way!","No kidding!"],"nivel":"A1","tags":["social","expressão"],"notaEn":"No article, just «de», as after any negative: «pas de problème». In speech, «pas de souci» means the same. To answer a thank-you, French says «De rien».","requerTodas":["fr-p053"],"v":"9432cad6"},{"idioma":"fr","id":"fr-u128","tipo":"frase","requer":"fr-p056","fr":"Entrez !","aceitasFr":["Entre !"],"en":"Come in!","aceitasEn":["come in","come on in","please come in","do come in"],"distratoresEn":["Sit down!","Wait!","Come up!","Hold on!"],"nivel":"A1","tags":["social"],"notaEn":"Knock on a door and you'll hear «Entrez !», the «vous» form, even for one person. With «tu»: «Entre !». To enter a place is «entrer dans».","requerTodas":["fr-p056"],"v":"b59bd366"},{"idioma":"fr","id":"fr-u129","tipo":"frase","requer":"fr-p089","fr":"Le train part à huit heures.","en":"The train leaves at eight.","aceitasEn":["the train leaves at eight","the train leaves at 8","the train departs at eight","the train goes at eight"],"distratoresEn":["The train arrives at eight.","The train comes by at eight.","The train stops at eight.","The train comes back at eight."],"nivel":"A1","tags":["viagem"],"notaEn":"Trains, planes and buses «partent»: they leave, depart. Arriving is «arriver».","requerTodas":["fr-p089","fr-p083","fr-p126","fr-p129"],"v":"8d2bed89"},{"idioma":"fr","id":"fr-u130","tipo":"frase","requer":"fr-p085","fr":"Le train a du retard.","aceitasFr":["Le train est en retard."],"en":"The train is late.","aceitasEn":["the train is late","the trains late","the train is delayed","the trains delayed","the train is running late"],"distratoresEn":["The train is early.","The train is full.","The train is stopped.","The train is empty."],"nivel":"A2","tags":["viagem"],"notaEn":"Something delayed «a du retard», has delay; a person who is late «est en retard». To delay is «retarder».","requerTodas":["fr-p089","fr-p002","fr-p085"],"v":"e1b38ed9"},{"idioma":"fr","id":"fr-u131","tipo":"frase","requer":"fr-p102","fr":"J'ai peur des chiens.","en":"I'm afraid of dogs.","aceitasEn":["im afraid of dogs","i am afraid of dogs","im scared of dogs","i am scared of dogs","dogs scare me"],"distratoresEn":["I'm afraid of cats.","I'm afraid of mice.","I'm afraid of insects.","I'm afraid of bats."],"nivel":"A1","tags":["animais"],"notaEn":"To be afraid of is «avoir peur de», to have fear of. «Des» is «de» + «les»: «peur des chiens».","requerTodas":["fr-p002","fr-p102","fr-p090"],"v":"c6e565e4"},{"idioma":"fr","id":"fr-u132","tipo":"frase","requer":"fr-p093","fr":"Un verre de vin rouge, s'il vous plaît.","en":"A glass of red wine, please.","aceitasEn":["a glass of red wine please","a glass of red wine","a glass of red please","a red wine please"],"distratoresEn":["A glass of white wine, please.","A glass of rosé wine, please.","A glass of sweet wine, please.","A glass of dry wine, please."],"nivel":"A1","tags":["comida"],"notaEn":"Red wine is «vin rouge»; white, «vin blanc»; rosé, «vin rosé». Any drinking glass is «un verre».","requerTodas":["fr-p066","fr-p093","fr-p173"],"v":"cd00c720"},{"idioma":"fr","id":"fr-u133","tipo":"frase","requer":"fr-p108","fr":"Elle sort avec mon frère.","en":"She's going out with my brother.","aceitasEn":["shes going out with my brother","she is going out with my brother","she goes out with my brother","shes dating my brother","she is dating my brother","shes seeing my brother"],"distratoresEn":["She's helping my brother.","She's waiting for my brother.","She's avoiding my brother.","She's calling my brother."],"nivel":"A2","tags":["social","família"],"notaEn":"«Sortir avec quelqu'un», just like going out with someone, means dating. «Sortir avec des amis» is just going out with friends.","requerTodas":["fr-p108","fr-p078"],"v":"e699f186"},{"idioma":"fr","id":"fr-u134","tipo":"frase","requer":"fr-p075","fr":"Il faut acheter du pain.","en":"We need to buy bread.","aceitasEn":["we need to buy bread","we need to buy some bread","we have to buy bread","we have to buy some bread","we need to get bread","we need to get some bread","someone has to buy bread"],"distratoresEn":["We need to make bread.","We need to put the bread away.","We need to warm up the bread.","We need to cut the bread."],"nivel":"A1","tags":["compras","gramática"],"notaEn":"«Il faut» + infinitive is an impersonal must: we, you, someone has to. The verb, «falloir», only exists with «il».","requerTodas":["fr-p122","fr-p075","fr-p027"],"v":"46843b5a"},{"idioma":"fr","id":"fr-u135","tipo":"frase","requer":"fr-p002","fr":"Quel âge as-tu ?","aceitasFr":["Tu as quel âge ?","Quel âge tu as ?","Quel âge avez-vous ?","Vous avez quel âge ?"],"en":"How old are you?","aceitasEn":["how old are you","whats your age","what is your age"],"distratoresEn":["How tall are you?","How much do you weigh?","How many kids do you have?","How many siblings do you have?"],"nivel":"A1","tags":["social"],"notaEn":"In French you have an age: «j'ai vingt ans». The question uses «l'âge» (masculine): «quel âge». Casually: «Tu as quel âge ?».","requerTodas":["fr-p130","fr-p002"],"v":"8c248dad"},{"idioma":"fr","id":"fr-u136","tipo":"frase","requer":"fr-p017","fr":"Je suis en train de travailler.","en":"I'm working.","aceitasEn":["im working","i am working","im busy working"],"distratoresEn":["I'm going to work.","I worked.","I was working.","I just finished working."],"nivel":"A2","tags":["gramática","trabalho"],"notaEn":"«Être en train de» + infinitive stresses an action in progress: I'm busy working. No train involved.","requerTodas":["fr-p001","fr-p089","fr-p017"],"v":"b1b9eb20"},{"idioma":"fr","id":"fr-u137","tipo":"frase","requer":"fr-p011","fr":"Ça prend du temps.","en":"That takes time.","aceitasEn":["that takes time","it takes time","this takes time","that takes a while","it takes a while"],"distratoresEn":["That saves time.","There's enough time.","That passes the time.","That was a long time ago."],"nivel":"A2","tags":["cotidiano","expressão"],"notaEn":"«Prendre du temps» works like take time: «ça prend deux heures», it takes two hours.","requerTodas":["fr-p011","fr-p025"],"v":"ce292afd"},{"idioma":"fr","id":"fr-u138","tipo":"frase","requer":"fr-p080","fr":"L'eau est froide.","en":"The water is cold.","aceitasEn":["the water is cold","the waters cold"],"distratoresEn":["The water is hot.","The water is dirty.","The water is clean.","The water is salty."],"nivel":"A1","tags":["natureza"],"notaEn":"«Froid» agrees: «eau» is feminine, so «froide», and the «d» is now pronounced.","requerTodas":["fr-p026","fr-p001","fr-p080"],"v":"df1f9a37"},{"idioma":"fr","id":"fr-u139","tipo":"frase","requer":"fr-p066","fr":"J'ai cassé un verre.","en":"I broke a glass.","aceitasEn":["i broke a glass","ive broken a glass","i have broken a glass"],"distratoresEn":["I broke a plate.","I broke a mirror.","I broke a jar.","I broke a jug."],"nivel":"A1","tags":["casa"],"notaEn":"To break is «casser»: «j'ai cassé un verre». «Le verre» is a drinking glass, and glass the material.","requerTodas":["fr-p002","fr-p117","fr-p066"],"v":"aaaad71c"},{"idioma":"fr","id":"fr-u140","tipo":"frase","requer":"fr-p010","fr":"Je vais voir ma grand-mère.","en":"I'm going to see my grandmother.","aceitasEn":["im going to see my grandmother","i am going to see my grandmother","im going to visit my grandmother","i am going to visit my grandmother","im going to see my grandma","im going to visit my grandma"],"distratoresEn":["I'm going to call my grandmother.","I'm going to help my grandmother.","I'm going to wait for my grandmother.","I'm going to pick up my grandmother."],"nivel":"A1","tags":["família"],"notaEn":"«Aller voir quelqu'un» is to visit someone; «visiter» is mostly for places: «visiter un musée».","requerTodas":["fr-p003","fr-p010","fr-p136"],"v":"f69791d3"},{"idioma":"fr","id":"fr-u141","tipo":"frase","requer":"fr-p029","fr":"Je cherche du travail.","en":"I'm looking for work.","aceitasEn":["im looking for work","i am looking for work","im looking for a job","i am looking for a job","im job hunting"],"distratoresEn":["I'm looking for an apartment.","I'm looking for an internship.","I'm looking for a school.","I'm looking for a hotel."],"nivel":"A1","tags":["trabalho"],"notaEn":"To look for is «chercher», with no preposition: «je cherche du travail», «je cherche mes clés». To find is «trouver».","requerTodas":["fr-p118","fr-p029"],"v":"71e3b189"},{"idioma":"fr","id":"fr-v025","tipo":"frase","fr":"Les cours finissent à midi.","en":"Classes end at noon.","aceitasEn":["classes end at noon","classes finish at noon","class ends at noon","lessons end at noon"],"distratoresEn":["Classes used to end at noon.","Classes ended at noon.","Classes would end at noon.","Classes had ended at noon."],"formasFr":{"Les cours finissaient à midi":"imperfect","Les cours ont fini à midi":"passé composé","Les cours finiraient à midi":"conditional","Les cours avaient fini à midi":"pluperfect"},"nivel":"A2","tags":["conjugação","presente","regular","escola"],"notaEn":"«-ir» verbs like «finir» add «-iss-» in the plural: je finis, tu finis, il finit, nous finissons, vous finissez, ils finissent. «Le cours», a class, ends in «s» even in the singular.","requerTodas":["fr-p148","fr-p123","fr-p064"],"v":"67209931"},{"idioma":"fr","id":"fr-v026","tipo":"frase","fr":"Ils attendent le train.","aceitasFr":["Elles attendent le train."],"en":"They're waiting for the train.","aceitasEn":["theyre waiting for the train","they are waiting for the train","they wait for the train"],"distratoresEn":["They were waiting for the train.","They waited for the train.","They'll wait for the train.","They would wait for the train."],"formasFr":{"Ils attendaient le train":"imperfect","Ils ont attendu le train":"passé composé","Ils attendront le train":"future","Ils attendraient le train":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","viagem"],"notaEn":"The «-re» verb pattern: j'attends, tu attends, il attend (no «t»), nous attendons, vous attendez, ils attendent. The «d» is silent in the singular. Participle: «attendu».","requerTodas":["fr-p018","fr-p089"],"v":"20207457"},{"idioma":"fr","id":"fr-v027","tipo":"frase","fr":"Il vend sa voiture.","en":"He's selling his car.","aceitasEn":["hes selling his car","he is selling his car","he sells his car"],"distratoresEn":["He was selling his car.","He sold his car.","He'll sell his car.","He would sell his car."],"formasFr":{"Il vendait sa voiture":"imperfect","Il a vendu sa voiture":"passé composé","Il vendra sa voiture":"future","Il vendrait sa voiture":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","compras"],"notaEn":"«Vendre» follows «attendre»: je vends, il vend, nous vendons, ils vendent; participle «vendu». «Sa voiture»: the possessive agrees with «voiture», not with the owner.","requerTodas":["fr-p182","fr-p034"],"v":"e96e3b96"},{"idioma":"fr","id":"fr-v028","tipo":"frase","fr":"Son chien est mort.","en":"His dog died.","aceitasEn":["his dog died","her dog died","his dog has died","her dog has died","his dog is dead","her dog is dead"],"distratoresEn":["His dog is dying.","His dog was dying.","His dog will die.","His dog would die."],"formasFr":{"Son chien meurt":"present","Son chien mourait":"imperfect","Son chien mourra":"future","Son chien mourrait":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular","animais"],"notaEn":"«Mourir» takes «être» in the passé composé, and its participle is irregular: «mort», dead. The present changes stem: il meurt, nous mourons.","requerTodas":["fr-p090","fr-p001","fr-p168"],"v":"d0b38b35"},{"idioma":"fr","id":"fr-v029","tipo":"frase","fr":"Ils sont venus en voiture.","aceitasFr":["Elles sont venues en voiture."],"en":"They came by car.","aceitasEn":["they came by car","they came in the car","they drove here","theyve come by car","they have come by car"],"distratoresEn":["They're coming by car.","They used to come by car.","They'll come by car.","They would come by car."],"formasFr":{"Ils viennent en voiture":"present","Ils venaient en voiture":"imperfect","Ils viendront en voiture":"future","Ils viendraient en voiture":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","viagem"],"notaEn":"«Venir» takes «être» in the passé composé, and the participle agrees with the subject: «ils sont venus», «elles sont venues».","requerTodas":["fr-p001","fr-p009","fr-p034"],"v":"316ad1ff"},{"idioma":"fr","id":"fr-v030","tipo":"frase","fr":"J'ai fait un gâteau.","en":"I made a cake.","aceitasEn":["i made a cake","i baked a cake","ive made a cake","i have made a cake","ive baked a cake"],"distratoresEn":["I'm making a cake.","I was making a cake.","I'll make a cake.","I would make a cake."],"formasFr":{"Je fais un gâteau":"present","Je faisais un gâteau":"imperfect","Je vais faire un gâteau":"near future","Je ferais un gâteau":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","comida"],"notaEn":"The participle of «faire» is «fait», silent «t». «Le gâteau», cake, is masculine.","requerTodas":["fr-p002","fr-p004","fr-p150"],"v":"2489ab53"},{"idioma":"fr","id":"fr-v031","tipo":"frase","fr":"J'ai mis la clé sur la table.","en":"I put the key on the table.","aceitasEn":["i put the key on the table","ive put the key on the table","i have put the key on the table","i left the key on the table","i placed the key on the table"],"distratoresEn":["I'm putting the key on the table.","I used to put the key on the table.","I'll put the key on the table.","I would put the key on the table."],"formasFr":{"Je mets la clé sur la table":"present","Je mettais la clé sur la table":"imperfect","Je vais mettre la clé sur la table":"near future","Je mettrais la clé sur la table":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular","casa"],"notaEn":"«Mettre», to put, has an irregular participle: «mis». «Sur la table», on the table.","requerTodas":["fr-p002","fr-p167","fr-p133","fr-p143"],"v":"319c4dd2"},{"idioma":"fr","id":"fr-v032","tipo":"frase","fr":"Elle a écrit une lettre.","en":"She wrote a letter.","aceitasEn":["she wrote a letter","shes written a letter","she has written a letter"],"distratoresEn":["She's writing a letter.","She was writing a letter.","She'll write a letter.","She would write a letter."],"formasFr":{"Elle écrit une lettre":"present","Elle écrivait une lettre":"imperfect","Elle écrira une lettre":"future","Elle écrirait une lettre":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","escola"],"notaEn":"The participle of «écrire» is «écrit», the same as the present «il» form. «La lettre» is a letter, of mail or of the alphabet.","requerTodas":["fr-p002","fr-p184","fr-p138"],"v":"f9253b64"},{"idioma":"fr","id":"fr-v033","tipo":"frase","fr":"Qui a ouvert la fenêtre ?","en":"Who opened the window?","aceitasEn":["who opened the window","who has opened the window"],"distratoresEn":["Who's opening the window?","Who used to open the window?","Who will open the window?","Who would open the window?"],"formasFr":{"Qui ouvre la fenêtre":"present","Qui ouvrait la fenêtre":"imperfect","Qui ouvrira la fenêtre":"future","Qui ouvrirait la fenêtre":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular","casa"],"notaEn":"«Ouvrir», to open, takes «-er» endings in the present (j'ouvre, il ouvre), and its participle is irregular: «ouvert».","requerTodas":["fr-p002","fr-p169","fr-p135"],"v":"a5809d44"},{"idioma":"fr","id":"fr-v034","tipo":"frase","fr":"Il a été très gentil avec moi.","en":"He was very nice to me.","aceitasEn":["he was very nice to me","he was really nice to me","he was very kind to me","hes been very nice to me","he has been very nice to me","hes been very kind to me"],"distratoresEn":["He's very nice to me.","He used to be very nice to me.","He'll be very nice to me.","He would be very nice to me."],"formasFr":{"Il est très gentil avec moi":"present","Il était très gentil avec moi":"imperfect","Il sera très gentil avec moi":"future","Il serait très gentil avec moi":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular","social"],"notaEn":"The participle of «être» is «été», spelled like «l'été», summer. The passé composé reports one occasion; «il était gentil» would describe how he used to be.","requerTodas":["fr-p002","fr-p001","fr-p043","fr-p124"],"v":"b25c39cb"},{"idioma":"fr","id":"fr-v035","tipo":"frase","fr":"Tu as eu de la chance.","aceitasFr":["Vous avez eu de la chance."],"en":"You were lucky.","aceitasEn":["you were lucky","you got lucky","youve been lucky","you have been lucky"],"distratoresEn":["You're lucky.","You used to be lucky.","You'll be lucky.","You'd be lucky."],"formasFr":{"Tu as de la chance":"present","Tu avais de la chance":"imperfect","Tu auras de la chance":"future","Tu aurais de la chance":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"To be lucky is «avoir de la chance», to have (some) luck. The participle of «avoir» is «eu»: «tu as eu», you had.","requerTodas":["fr-p002","fr-p132"],"v":"c84b8a11"},{"idioma":"fr","id":"fr-v036","tipo":"frase","fr":"J'ai dû partir.","en":"I had to leave.","aceitasEn":["i had to leave","i had to go","ive had to leave","i have had to leave"],"distratoresEn":["I have to leave.","I was supposed to leave.","I'll have to leave.","I should leave."],"formasFr":{"Je dois partir":"present","Je devais partir":"imperfect","Je vais devoir partir":"near future","Je devrais partir":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"The participle of «devoir» is «dû», accented to tell it apart from «du». «J'ai dû» is I had to; «je devais», I was supposed to.","requerTodas":["fr-p002","fr-p082","fr-p083"],"v":"ad977898"},{"idioma":"fr","id":"fr-v037","tipo":"frase","fr":"Je n'ai pas pu dormir.","aceitasFr":["J'ai pas pu dormir."],"en":"I couldn't sleep.","aceitasEn":["i couldnt sleep","i could not sleep","i wasnt able to sleep","i was not able to sleep","i havent been able to sleep"],"distratoresEn":["I can't sleep.","I won't be able to sleep.","I wouldn't be able to sleep.","I hadn't been able to sleep."],"formasFr":{"Je ne peux pas dormir":"present","Je ne vais pas pouvoir dormir":"near future","Je ne pourrais pas dormir":"conditional","Je n'avais pas pu dormir":"pluperfect"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"In a negative passé composé, «ne… pas» wraps the helper verb: «je n'ai pas pu». The participle of «pouvoir» is «pu».","requerTodas":["fr-p002","fr-p006","fr-p109"],"v":"d1221f6b"},{"idioma":"fr","id":"fr-v038","tipo":"frase","fr":"Il n'a rien dit.","aceitasFr":["Il a rien dit."],"en":"He didn't say anything.","aceitasEn":["he didnt say anything","he did not say anything","he said nothing","he didnt say a word","he hasnt said anything"],"distratoresEn":["He doesn't say anything.","He wasn't saying anything.","He won't say anything.","He wouldn't say anything."],"formasFr":{"Il ne dit rien":"present","Il ne disait rien":"imperfect","Il ne dira rien":"future","Il ne dirait rien":"conditional"},"nivel":"A2","tags":["conjugação","pretérito","irregular"],"notaEn":"In the passé composé, «rien» goes before the participle: «il n'a rien dit». «Personne» goes after: «je n'ai vu personne».","requerTodas":["fr-p002","fr-p005"],"v":"fae192b4"},{"idioma":"fr","id":"fr-v039","tipo":"frase","fr":"Tu as lu ce livre ?","aceitasFr":["Vous avez lu ce livre ?"],"en":"Have you read this book?","aceitasEn":["have you read this book","have you read that book","did you read this book","did you read that book"],"distratoresEn":["Are you reading this book?","Did you use to read this book?","Will you read this book?","Would you read this book?"],"formasFr":{"Tu lis ce livre":"present","Tu lisais ce livre":"imperfect","Tu liras ce livre":"future","Tu lirais ce livre":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","escola"],"notaEn":"The participle of «lire» is «lu», short like «vu», «bu», «su» and «pu».","requerTodas":["fr-p002","fr-p076","fr-p033"],"v":"b5b14641"},{"idioma":"fr","id":"fr-v040","tipo":"frase","fr":"Il pleuvait.","en":"It was raining.","aceitasEn":["it was raining"],"distratoresEn":["It's raining.","It rained.","It's going to rain.","It would rain."],"formasFr":{"Il pleut":"present","Il a plu":"passé composé","Il pleuvra":"future","Il pleuvrait":"conditional"},"nivel":"A2","tags":["conjugação","imperfeito","irregular","natureza"],"notaEn":"The imperfect sets the scene; the passé composé tells what happened in it: «il pleuvait quand je suis sorti», it was raining when I went out. The participle of «pleuvoir» is «plu».","requerTodas":["fr-p171"],"v":"eaa5f362"},{"idioma":"fr","id":"fr-v041","tipo":"frase","fr":"Tu seras un bon père.","en":"You'll be a good father.","aceitasEn":["youll be a good father","you will be a good father","youre going to be a good father","you are going to be a good father","youll be a good dad","youll make a good father"],"distratoresEn":["You're a good father.","You used to be a good father.","You've been a good father.","You would be a good father."],"formasFr":{"Tu es un bon père":"present","Tu étais un bon père":"imperfect","Tu as été un bon père":"passé composé","Tu serais un bon père":"conditional"},"nivel":"A1","tags":["conjugação","futuro","irregular","família"],"notaEn":"Irregular future of «être»: je serai, tu seras, il sera, nous serons, vous serez, ils seront. The endings are those of every future.","requerTodas":["fr-p001","fr-p036","fr-p103"],"v":"f55a3a35"},{"idioma":"fr","id":"fr-v042","tipo":"frase","fr":"On aura le temps.","aceitasFr":["Nous aurons le temps."],"en":"We'll have time.","aceitasEn":["well have time","we will have time","were going to have time","we are going to have time"],"distratoresEn":["We have time.","We used to have time.","We had time.","We'd have time."],"formasFr":{"On a le temps":"present","On avait le temps":"imperfect","On a eu le temps":"passé composé","On aurait le temps":"conditional"},"nivel":"A1","tags":["conjugação","futuro","irregular"],"notaEn":"Irregular future of «avoir»: j'aurai, tu auras, il aura, nous aurons. «On», the casual we, takes the «il» form: «on aura».","requerTodas":["fr-p002","fr-p025"],"v":"a2c90959"},{"idioma":"fr","id":"fr-v043","tipo":"frase","fr":"Il fera chaud.","en":"It'll be hot.","aceitasEn":["itll be hot","it will be hot","its going to be hot","it is going to be hot","itll be warm","it will be warm"],"distratoresEn":["It's hot.","It was hot.","It's been hot.","It would be hot."],"formasFr":{"Il fait chaud":"present","Il faisait chaud":"imperfect","Il a fait chaud":"passé composé","Il ferait chaud":"conditional"},"nivel":"A1","tags":["conjugação","futuro","irregular","natureza"],"notaEn":"Irregular future of «faire»: je ferai, il fera, with «e» instead of «ai». Weather is made: «il fait chaud», «il fera froid».","requerTodas":["fr-p004","fr-p112"],"v":"9de0edb6"},{"idioma":"fr","id":"fr-v044","tipo":"frase","fr":"Tu iras loin.","aceitasFr":["Vous irez loin."],"en":"You'll go far.","aceitasEn":["youll go far","you will go far","youre going to go far","you are going to go far","youll go a long way"],"distratoresEn":["You went far.","You used to go far.","You'd go far.","You had gone far."],"formasFr":{"Tu allais loin":"imperfect","Tu es allé loin":"passé composé","Tu irais loin":"conditional","Tu étais allé loin":"pluperfect"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"In the future, «aller» switches to the stem «ir-»: j'irai, tu iras, il ira. «Aller loin», to go far, means to succeed.","requerTodas":["fr-p003","fr-p164"],"v":"bb19d801"},{"idioma":"fr","id":"fr-v045","tipo":"frase","fr":"Elle viendra avec son mari.","en":"She'll come with her husband.","aceitasEn":["shell come with her husband","she will come with her husband","shes going to come with her husband","she is going to come with her husband"],"distratoresEn":["She used to come with her husband.","She came with her husband.","She would come with her husband.","She had come with her husband."],"formasFr":{"Elle venait avec son mari":"imperfect","Elle est venue avec son mari":"passé composé","Elle viendrait avec son mari":"conditional","Elle était venue avec son mari":"pluperfect"},"nivel":"A2","tags":["conjugação","futuro","irregular","família"],"notaEn":"Future of «venir», with a «d»: je viendrai, elle viendra, ils viendront. «Le mari» is the husband; a wife is «la femme».","requerTodas":["fr-p009","fr-p152"],"v":"5ac459e1"},{"idioma":"fr","id":"fr-v046","tipo":"frase","fr":"Il pourra t'aider.","aceitasFr":["Il pourra vous aider."],"en":"He'll be able to help you.","aceitasEn":["hell be able to help you","he will be able to help you","hell be able to help","he will be able to help"],"distratoresEn":["He can help you.","He used to be able to help you.","He was able to help you.","He could help you."],"formasFr":{"Il peut t'aider":"present","Il pouvait t'aider":"imperfect","Il a pu t'aider":"passé composé","Il pourrait t'aider":"conditional"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"Future of «pouvoir», with a double «r»: je pourrai, il pourra. The conditional, «il pourrait», only changes the ending.","requerTodas":["fr-p006","fr-p111"],"v":"2ed8c445"},{"idioma":"fr","id":"fr-v047","tipo":"frase","fr":"On saura la vérité.","aceitasFr":["Nous saurons la vérité."],"en":"We'll know the truth.","aceitasEn":["well know the truth","we will know the truth","were going to know the truth","well find out the truth","we will find out the truth"],"distratoresEn":["We know the truth.","We used to know the truth.","We found out the truth.","We'd know the truth."],"formasFr":{"On sait la vérité":"present","On savait la vérité":"imperfect","On a su la vérité":"passé composé","On saurait la vérité":"conditional"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"Irregular future of «savoir»: je saurai, tu sauras, on saura. The same «saur-» stem makes the conditional: «on saurait».","requerTodas":["fr-p008","fr-p055"],"v":"f05ad967"},{"idioma":"fr","id":"fr-v048","tipo":"frase","fr":"Tu devras attendre.","aceitasFr":["Vous devrez attendre."],"en":"You'll have to wait.","aceitasEn":["youll have to wait","you will have to wait","youre going to have to wait","you are going to have to wait"],"distratoresEn":["You have to wait.","You were supposed to wait.","You had to wait.","You should wait."],"formasFr":{"Tu dois attendre":"present","Tu devais attendre":"imperfect","Tu as dû attendre":"passé composé","Tu devrais attendre":"conditional"},"nivel":"A2","tags":["conjugação","futuro","irregular"],"notaEn":"Future of «devoir»: je devrai, tu devras. Don't mix it up with the conditional «tu devrais», you should: one letter apart.","requerTodas":["fr-p082","fr-p018"],"v":"5554ec7f"},{"idioma":"fr","id":"fr-v049","tipo":"frase","fr":"J'aimerais voyager.","en":"I'd like to travel.","aceitasEn":["id like to travel","i would like to travel","id love to travel","i would love to travel"],"distratoresEn":["I like to travel.","I liked traveling.","I'll like traveling.","I had liked traveling."],"formasFr":{"J'aime voyager":"present","J'ai aimé voyager":"passé composé","J'aimais voyager":"imperfect","J'avais aimé voyager":"pluperfect"},"nivel":"A2","tags":["conjugação","condicional","regular","viagem"],"notaEn":"The conditional joins the future stem and the imperfect endings: «aimer-» + «-ais». «J'aimerais» is the polite wish, like «je voudrais».","requerTodas":["fr-p015","fr-p183"],"v":"b0d13e00"},{"idioma":"fr","id":"fr-v050","tipo":"frase","fr":"Tu devrais dormir.","aceitasFr":["Vous devriez dormir."],"en":"You should sleep.","aceitasEn":["you should sleep","you ought to sleep","you should get some sleep","you should go to sleep"],"distratoresEn":["You have to sleep.","You were supposed to sleep.","You had to sleep.","You'll have to sleep."],"formasFr":{"Tu dois dormir":"present","Tu devais dormir":"imperfect","Tu as dû dormir":"passé composé","Tu devras dormir":"future"},"nivel":"A2","tags":["conjugação","condicional","irregular","saúde"],"notaEn":"Advice uses the conditional of «devoir»: «tu devrais», you should. Without the middle «r», «tu devais» is the imperfect: you were supposed to.","requerTodas":["fr-p082","fr-p109"],"v":"16616938"},{"idioma":"fr","id":"fr-v051","tipo":"frase","fr":"Je me lève à sept heures.","en":"I get up at seven.","aceitasEn":["i get up at seven","i get up at 7","i get up at seven oclock"],"distratoresEn":["I used to get up at seven.","I got up at seven.","I'll get up at seven.","I would get up at seven."],"formasFr":{"Je me levais à sept heures":"imperfect","Je me suis levé à sept heures":"passé composé","Je vais me lever à sept heures":"near future","Je me lèverais à sept heures":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","pronomes","cotidiano"],"notaEn":"A reflexive verb: «je me lève», «tu te lèves», «nous nous levons». The «e» takes a grave accent before a silent ending. To wake up is «se réveiller».","requerTodas":["fr-p177","fr-p178","fr-p129"],"v":"36930868"},{"idioma":"fr","id":"fr-v052","tipo":"frase","fr":"Le bébé s'appellera Louis.","en":"The baby will be called Louis.","aceitasEn":["the baby will be called louis","the baby will be named louis","the baby is going to be called louis","the baby is going to be named louis"],"distratoresEn":["The baby is called Louis.","The baby used to be called Louis.","The baby was called Louis.","The baby would be called Louis."],"formasFr":{"Le bébé s'appelle Louis":"present","Le bébé s'appelait Louis":"imperfect","Le bébé s'est appelé Louis":"passé composé","Le bébé s'appellerait Louis":"conditional"},"nivel":"A2","tags":["conjugação","futuro","regular","pronomes","família"],"notaEn":"«S'appeler» doubles the «l» before a silent ending: «il s'appelle», «il s'appellera», but «nous nous appelons». «Louis» sounds like «lwee».","requerTodas":["fr-p147","fr-p175"],"v":"0d31f220"},{"idioma":"fr","id":"fr-v053","tipo":"frase","fr":"Les enfants se couchent tôt.","en":"The children go to bed early.","aceitasEn":["the children go to bed early","the kids go to bed early"],"distratoresEn":["The children used to go to bed early.","The children went to bed early.","The children will go to bed early.","The children would go to bed early."],"formasFr":{"Les enfants se couchaient tôt":"imperfect","Les enfants se sont couchés tôt":"passé composé","Les enfants se coucheront tôt":"future","Les enfants se coucheraient tôt":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","pronomes","casa"],"notaEn":"«Se coucher» is to go to bed; sleeping is «dormir». In the passé composé every reflexive verb takes «être»: «ils se sont couchés».","requerTodas":["fr-p023","fr-p176","fr-p181"],"v":"b246ffa6"},{"idioma":"fr","id":"fr-v054","tipo":"frase","fr":"Je n'ai pas mangé à midi.","aceitasFr":["J'ai pas mangé à midi."],"en":"I didn't eat at noon.","aceitasEn":["i didnt eat at noon","i did not eat at noon","i didnt have lunch","i didnt eat lunch","i skipped lunch"],"distratoresEn":["I don't eat at noon.","I didn't use to eat at noon.","I won't eat at noon.","I wouldn't eat at noon."],"formasFr":{"Je ne mange pas à midi":"present","Je ne mangeais pas à midi":"imperfect","Je ne vais pas manger à midi":"near future","Je ne mangerais pas à midi":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","comida"],"notaEn":"In a negative passé composé, «ne… pas» wraps only the helper verb, leaving the participle outside: «je n'ai pas mangé».","requerTodas":["fr-p002","fr-p013","fr-p064"],"v":"9126ed63"},{"idioma":"fr","id":"fr-p115","tipo":"palavra","fr":"arriver","en":"to arrive / to happen","aceitasEn":["to arrive","arrive","to get","to happen","happen","to manage","manage"],"distratoresEn":["to arrange / to tidy","to risk / to dare","to drag / to pull","to leave / to go away"],"nivel":"A1","tags":["verbo","viagem"],"notaEn":"To arrive, and also to happen: «qu'est-ce qui est arrivé ?», what happened? With «à» it means to manage: «je n'arrive pas à dormir», I can't get to sleep. It takes «être» in the passé composé.","v":"ab28dd81"},{"idioma":"fr","id":"fr-p116","tipo":"palavra","fr":"brésilien","aceitasFr":["brésilienne"],"en":"Brazilian","aceitasEn":["brazilian"],"distratoresEn":["Portuguese","Argentine","Bolivian","Paraguayan"],"nivel":"A1","tags":["adjetivo","cultura"],"notaEn":"Feminine «brésilienne», with a double «n». Lowercase; only the people are capitalized: «les Brésiliens». Brazil is «le Brésil», with the article.","v":"dab6dcc8"},{"idioma":"fr","id":"fr-p117","tipo":"palavra","fr":"casser","en":"to break","aceitasEn":["to break","break","to smash"],"distratoresEn":["to cash","to marry","to hunt","to fix"],"nivel":"A2","tags":["verbo","casa"],"notaEn":"To break: «j'ai cassé un verre», I broke a glass; «se casser la jambe», to break your leg. Nothing to do with cash, which is «les espèces».","v":"1afce86c"},{"idioma":"fr","id":"fr-p118","tipo":"palavra","fr":"chercher","en":"to look for","aceitasEn":["to look for","look for","to search","search","to search for","search for","to seek","to fetch"],"distratoresEn":["to find","to smell","to arrive","to check"],"nivel":"A1","tags":["verbo"],"notaEn":"To look for, with no preposition: «je cherche mes clés», I'm looking for my keys. «Aller chercher» is to go and get: «je vais chercher le pain». To find is «trouver».","v":"13e0e8a1"},{"idioma":"fr","id":"fr-p119","tipo":"palavra","fr":"connaître","en":"to know (people, places)","aceitasEn":["to know","know","to be familiar with","to be acquainted with"],"distratoresEn":["to connect (two things)","to count (numbers)","to conquer (a land)","to consent (agree)"],"nivel":"A1","tags":["verbo","social"],"notaEn":"To know a person or a place: «je connais Paris». Knowing a fact, or how to do something, is «savoir». Forms: je connais, il connaît, nous connaissons; participle «connu».","v":"39919da3"},{"idioma":"fr","id":"fr-p120","tipo":"palavra","fr":"deux","en":"two","aceitasEn":["two","2"],"distratoresEn":["twelve","ten","six","eleven"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «x» is silent, except before a vowel, where it sounds like «z»: «deux amis». Twelve is «douze».","v":"bc2e8495"},{"idioma":"fr","id":"fr-p121","tipo":"palavra","fr":"dix","en":"ten","aceitasEn":["ten","10"],"distratoresEn":["two","twelve","six","nine"],"nivel":"A1","tags":["cotidiano"],"notaEn":"On its own it sounds like «deess». Before a consonant the «x» goes silent: «dix livres»; before a vowel it sounds like «z»: «dix euros».","v":"ac1f42fb"},{"idioma":"fr","id":"fr-p122","tipo":"palavra","fr":"falloir","en":"to be necessary","aceitasEn":["to be necessary","be necessary","must","to have to","to need"],"distratoresEn":["to fail","to fall","to be worth","to follow"],"nivel":"A1","tags":["verbo","gramática"],"notaEn":"Only used with an impersonal «il»: «il faut partir», we have to go, one must go. Past «il a fallu»; future «il faudra».","v":"025c2cf5"},{"idioma":"fr","id":"fr-p123","tipo":"palavra","fr":"finir","en":"to finish","aceitasEn":["to finish","finish","to end","end"],"distratoresEn":["to pretend","to sign","to fix","to start"],"nivel":"A1","tags":["verbo"],"notaEn":"The model for «-ir» verbs that add «-iss-» in the plural: je finis, nous finissons, ils finissent; participle «fini». To pretend is «faire semblant».","v":"2b0aef5d"},{"idioma":"fr","id":"fr-p124","tipo":"palavra","fr":"gentil","aceitasFr":["gentille"],"en":"kind","aceitasEn":["kind","nice","sweet"],"distratoresEn":["brilliant","rude","frozen","fat"],"nivel":"A1","tags":["adjetivo","social"],"notaEn":"Feminine «gentille». Kind, nice: «c'est gentil !», that's so kind! For children, well-behaved. Gentle is «doux».","v":"a9b2212f"},{"idioma":"fr","id":"fr-p125","tipo":"palavra","fr":"hier","en":"yesterday","aceitasEn":["yesterday"],"distratoresEn":["here","today","tomorrow","now"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «h» is silent. «Hier soir», last night. The day before yesterday is «avant-hier».","v":"cc71aa1f"},{"idioma":"fr","id":"fr-p126","tipo":"palavra","fr":"huit","en":"eight","aceitasEn":["eight","8"],"distratoresEn":["eighty","four","eighteen","nine"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Sounds like «weet»; before a consonant the «t» goes silent: «huit livres». «Dans huit jours», in a week.","v":"11bf7078"},{"idioma":"fr","id":"fr-p127","tipo":"palavra","fr":"l'attention","en":"attention","aceitasEn":["attention","the attention","care"],"distratoresEn":["tension","intention","temptation","attempt"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine. «Faire attention», to pay attention, to be careful; on its own, «Attention !» means watch out!","v":"23c20588"},{"idioma":"fr","id":"fr-p128","tipo":"palavra","fr":"l'euro","aceitasFr":["un euro"],"en":"the euro","aceitasEn":["euro","the euro"],"distratoresEn":["the dollar","the cent","the pound","the yen"],"nivel":"A1","tags":["compras","economia"],"notaEn":"Masculine, linked in the plural: «dix euros», «dee-zuh-ROH». A cent is «le centime».","v":"cef20a51"},{"idioma":"fr","id":"fr-p129","tipo":"palavra","fr":"l'heure","aceitasFr":["une heure"],"en":"the hour","aceitasEn":["hour","the hour","time","the time","o'clock"],"distratoresEn":["the minute","the honor","the week","the hair"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine, with a silent «h». In clock times it is never dropped: «à six heures», at six o'clock. «Quelle heure est-il ?», what time is it?","v":"294ad81b"},{"idioma":"fr","id":"fr-p130","tipo":"palavra","fr":"l'âge","en":"age","aceitasEn":["age","the age"],"distratoresEn":["height","weight","agenda","edge"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine: «quel âge as-tu ?», how old are you? Age is something you have: «j'ai vingt ans», I'm twenty.","v":"0b4bf45c"},{"idioma":"fr","id":"fr-p131","tipo":"palavra","fr":"la carte","en":"the card / the map","aceitasEn":["card","the card","map","the map","menu","the menu"],"distratoresEn":["the cart / the trolley","the letter / the envelope","the poster / the sign","the bill / the receipt"],"nivel":"A1","tags":["compras","falso-amigo"],"notaEn":"A card, a map or a menu: «payer par carte», to pay by card; «à la carte». A cart is «un chariot», and a letter in the mail is «une lettre».","v":"c75e35cf"},{"idioma":"fr","id":"fr-p132","tipo":"palavra","fr":"la chance","en":"luck","aceitasEn":["luck","the luck","fortune"],"distratoresEn":["flame","dance","calm","misfortune"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Luck: «avoir de la chance», to be lucky; «bonne chance !», good luck! A chance in the sense of an opportunity is usually «l'occasion».","v":"8fa43934"},{"idioma":"fr","id":"fr-p133","tipo":"palavra","fr":"la clé","aceitasFr":["la clef"],"en":"the key","aceitasEn":["key","the key"],"distratoresEn":["the lock","the door","the clay","the padlock"],"nivel":"A1","tags":["casa"],"notaEn":"Also spelled «la clef», pronounced the same. «Fermer à clé», to lock. The lock itself is «la serrure».","v":"2af52afc"},{"idioma":"fr","id":"fr-p134","tipo":"palavra","fr":"la douche","en":"the shower","aceitasEn":["shower","the shower"],"distratoresEn":["the bath","the sink","the candy","the towel"],"nivel":"A1","tags":["casa"],"notaEn":"Feminine. You take it, as in English: «prendre une douche». A bath is «un bain».","v":"4a12b73d"},{"idioma":"fr","id":"fr-p135","tipo":"palavra","fr":"la fenêtre","en":"the window","aceitasEn":["window","the window"],"distratoresEn":["the door","the wall","the crack","the curtain"],"nivel":"A1","tags":["casa"],"notaEn":"Feminine. The circumflex marks a lost «s»: it comes from Latin «fenestra», as in «defenestrate».","v":"48f1f1fa"},{"idioma":"fr","id":"fr-p136","tipo":"palavra","fr":"la grand-mère","en":"the grandmother","aceitasEn":["grandmother","the grandmother","grandma","granny"],"distratoresEn":["the aunt","the godmother","the mother-in-law","the granddaughter"],"nivel":"A1","tags":["família"],"notaEn":"Hyphenated, and «grand» takes no feminine «e»: «ma grand-mère». Grandma is «mamie»; grandfather, «le grand-père».","v":"4a45897e"},{"idioma":"fr","id":"fr-p137","tipo":"palavra","fr":"la journée","en":"the day (as a whole)","aceitasEn":["day","the day","daytime","the daytime"],"distratoresEn":["the journey (a long trip)","the night (as a whole)","the newspaper (a daily)","the knee (a joint)"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine. The day as you live it, from morning to night: «toute la journée», all day; «bonne journée !». A calendar day is «le jour», and a journey is «un voyage».","v":"c710b13b"},{"idioma":"fr","id":"fr-p138","tipo":"palavra","fr":"la lettre","en":"the letter","aceitasEn":["letter","the letter"],"distratoresEn":["the card","the reading","the liter","the stamp"],"nivel":"A1","tags":["cotidiano","escola"],"notaEn":"Both a letter you mail and a letter of the alphabet: «écrire une lettre», «la lettre A». A card is «la carte».","v":"e7a1efc9"},{"idioma":"fr","id":"fr-p139","tipo":"palavra","fr":"la minute","en":"the minute","aceitasEn":["minute","the minute"],"distratoresEn":["the second","the minimum","the mine","the month"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Feminine: «une minute», «vingt minutes». «Une minute !», just a minute!","v":"5d848b4e"},{"idioma":"fr","id":"fr-p140","tipo":"palavra","fr":"la question","en":"the question","aceitasEn":["question","the question"],"distratoresEn":["the answer","the complaint","the amount","the quest"],"nivel":"A1","tags":["escola"],"notaEn":"A question, and also a matter: «c'est une question de temps», it's a matter of time. To ask one is «poser une question».","v":"885381ca"},{"idioma":"fr","id":"fr-p141","tipo":"palavra","fr":"la raison","en":"the reason","aceitasEn":["reason","the reason"],"distratoresEn":["the raisin","the ration","the reaction","the region"],"nivel":"A1","tags":["cotidiano"],"notaEn":"French «has» it: «tu as raison», you're right; «avoir tort», to be wrong. A raisin is «un raisin sec»; «le raisin» is the grape.","v":"c752c68a"},{"idioma":"fr","id":"fr-p142","tipo":"palavra","fr":"la robe","en":"the dress","aceitasEn":["dress","the dress"],"distratoresEn":["the robe","the skirt","the blouse","the clothes"],"nivel":"A1","tags":["roupa","falso-amigo"],"notaEn":"Not a robe: it's a dress. A bathrobe is «le peignoir»; clothes in general are «les vêtements».","v":"f25a80ff"},{"idioma":"fr","id":"fr-p143","tipo":"palavra","fr":"la table","en":"the table","aceitasEn":["table","the table"],"distratoresEn":["the chair","the tablecloth","the bed","the shelf"],"nivel":"A1","tags":["casa","comida"],"notaEn":"«Mettre la table», to set the table; «à table !», dinner's ready! «La table des matières» is the table of contents.","v":"bb56191b"},{"idioma":"fr","id":"fr-p144","tipo":"palavra","fr":"la tête","en":"the head","aceitasEn":["head","the head"],"distratoresEn":["the forehead","the ceiling","the chest","the neck"],"nivel":"A1","tags":["corpo"],"notaEn":"From Latin «testa»; the circumflex marks a lost «s». «J'ai mal à la tête», I have a headache. The forehead is «le front».","v":"389e1fd4"},{"idioma":"fr","id":"fr-p145","tipo":"palavra","fr":"la vaisselle","en":"the dishes","aceitasEn":["dishes","the dishes","dishware","crockery"],"distratoresEn":["the vase","the broom","the laundry","the tablecloth"],"nivel":"A2","tags":["casa"],"notaEn":"Feminine and singular, for all the dishes at once. «Faire la vaisselle», to do the dishes.","v":"db4d1b28"},{"idioma":"fr","id":"fr-p146","tipo":"palavra","fr":"le besoin","en":"the need","aceitasEn":["need","the need"],"distratoresEn":["the desire","the wish","the duty","the bison"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Masculine. Almost always with «avoir»: «j'ai besoin de toi», I need you. Feeling like something is «avoir envie de».","v":"bffd22e9"},{"idioma":"fr","id":"fr-p147","tipo":"palavra","fr":"le bébé","en":"the baby","aceitasEn":["baby","the baby"],"distratoresEn":["the drink","the crib","the doll","the calf"],"nivel":"A1","tags":["família"],"notaEn":"Masculine even for a girl: «c'est un beau bébé». Two acute accents: «bébé».","v":"e4da68f7"},{"idioma":"fr","id":"fr-p148","tipo":"palavra","fr":"le cours","en":"the class / the course","aceitasEn":["class","the class","course","the course","lesson","the lesson"],"distratoresEn":["the yard / the courtyard","the race / the run","the body / the trunk","the test / the exam"],"nivel":"A1","tags":["escola"],"notaEn":"Masculine, with an «s» even in the singular: «un cours de français», a French class. It sounds just like «la cour», the courtyard, and «le corps», the body.","v":"c54c30c3"},{"idioma":"fr","id":"fr-p149","tipo":"palavra","fr":"le foot","aceitasFr":["le football"],"en":"soccer","aceitasEn":["soccer","football"],"distratoresEn":["foot","basketball","volleyball","tennis"],"nivel":"A1","tags":["cultura"],"notaEn":"Short for «le football», and that's what everyone says. Played with «à»: «jouer au foot». A foot is «un pied».","v":"a75e01ff"},{"idioma":"fr","id":"fr-p150","tipo":"palavra","fr":"le gâteau","en":"the cake","aceitasEn":["cake","the cake"],"distratoresEn":["the cat","the pie","the bread","the ice cream"],"nivel":"A1","tags":["comida"],"notaEn":"Plural with «x»: «les gâteaux». Cookies are «les petits gâteaux» or «les biscuits».","v":"ce1ec5d9"},{"idioma":"fr","id":"fr-p151","tipo":"palavra","fr":"le mal","en":"pain / evil","aceitasEn":["pain","the pain","ache","evil","harm","difficulty"],"distratoresEn":["good / virtue","suitcase / bag","fear / fright","hunger / thirst"],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"Pain is something you have: «avoir mal à» plus the body part, «j'ai mal au dos», my back hurts. It is also evil, and difficulty: «j'ai du mal à dormir», I have trouble sleeping.","v":"7051eff9"},{"idioma":"fr","id":"fr-p152","tipo":"palavra","fr":"le mari","en":"the husband","aceitasEn":["husband","the husband"],"distratoresEn":["the groom","the boyfriend","the sailor","the father-in-law"],"nivel":"A1","tags":["família"],"notaEn":"«Mon mari», my husband; a wife is «ma femme». The groom on the wedding day is «le marié».","v":"ef0a7f3a"},{"idioma":"fr","id":"fr-p153","tipo":"palavra","fr":"le matin","en":"the morning","aceitasEn":["morning","the morning"],"distratoresEn":["the afternoon","the evening","the dawn","the matinee"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Le matin», with the article, means in the morning, every day: «je cours le matin». A whole morning is «la matinée».","v":"725a28c5"},{"idioma":"fr","id":"fr-p154","tipo":"palavra","fr":"le monde","en":"the world / people","aceitasEn":["world","the world","people"],"distratoresEn":["the mountain / the hill","the coin / the change","the way / the manner","the month / the week"],"nivel":"A1","tags":["social"],"notaEn":"The world and, in everyday speech, people: «tout le monde», everyone; «il y a du monde», it's crowded.","v":"c0072a38"},{"idioma":"fr","id":"fr-p155","tipo":"palavra","fr":"le médecin","en":"the doctor","aceitasEn":["doctor","the doctor","physician","the physician"],"distratoresEn":["the medicine","the nurse","the dentist","the patient"],"nivel":"A1","tags":["saúde","profissões"],"notaEn":"Used for men and women alike: «elle est médecin», she's a doctor. Medicine as a field is «la médecine»; a drug is «le médicament».","v":"0d00ade9"},{"idioma":"fr","id":"fr-p156","tipo":"palavra","fr":"le petit déjeuner","en":"breakfast","aceitasEn":["breakfast","the breakfast"],"distratoresEn":["lunch","dinner","a snack","an appetizer"],"nivel":"A1","tags":["comida"],"notaEn":"Literally little lunch: «le déjeuner» is lunch, and «le dîner» is dinner. You «take» it: «prendre le petit déjeuner». In Quebec, «le déjeuner» is breakfast.","v":"6e202d54"},{"idioma":"fr","id":"fr-p157","tipo":"palavra","fr":"le piano","en":"the piano","aceitasEn":["piano","the piano"],"distratoresEn":["the guitar","the violin","the organ","the tambourine"],"nivel":"A1","tags":["cultura"],"notaEn":"Played with «jouer de»: «jouer du piano», to play the piano.","v":"625ee355"},{"idioma":"fr","id":"fr-p158","tipo":"palavra","fr":"le pied","en":"the foot","aceitasEn":["foot","the foot"],"distratoresEn":["the leg","the hand","the knee","the chest"],"nivel":"A1","tags":["corpo"],"notaEn":"The final «d» is silent. «À pied», on foot: «je vais au travail à pied», I walk to work.","v":"a7a5bda9"},{"idioma":"fr","id":"fr-p159","tipo":"palavra","fr":"le samedi","aceitasFr":["samedi"],"en":"Saturday","aceitasEn":["saturday"],"distratoresEn":["Sunday","Friday","Thursday","Tuesday"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Without the article it's one Saturday: «samedi», on Saturday. With it, every Saturday: «le samedi». Lowercase.","v":"60cdc098"},{"idioma":"fr","id":"fr-p160","tipo":"palavra","fr":"le soir","en":"the evening","aceitasEn":["evening","the evening"],"distratoresEn":["the afternoon","the morning","the dawn","the weekend"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The evening, until bedtime: «ce soir», tonight; «bonsoir», good evening. The night you sleep through is «la nuit».","v":"91d82d97"},{"idioma":"fr","id":"fr-p161","tipo":"palavra","fr":"le sport","en":"sport","aceitasEn":["sport","sports","the sport"],"distratoresEn":["port","support","transport","passport"],"nivel":"A1","tags":["cultura","saúde"],"notaEn":"The final «t» is silent. «Faire du sport», to play sports or work out, with the partitive.","v":"4d76c67b"},{"idioma":"fr","id":"fr-p162","tipo":"palavra","fr":"les courses","en":"the shopping","aceitasEn":["shopping","the shopping","groceries","the groceries","grocery shopping"],"distratoresEn":["the classes","the bills","the colors","the chores"],"nivel":"A1","tags":["compras"],"notaEn":"Everyday shopping, mostly groceries: «faire les courses», to do the shopping. In the singular, «la course» is a race or a run.","v":"27a33324"},{"idioma":"fr","id":"fr-p163","tipo":"palavra","fr":"les vacances","en":"vacation","aceitasEn":["vacation","the vacation","vacations","holidays","the holidays","holiday"],"distratoresEn":["vacancies","fairs","parties","trips"],"nivel":"A1","tags":["viagem"],"notaEn":"Always plural in this sense: «partir en vacances», to go on vacation (British: on holiday). Summer vacation is «les grandes vacances».","v":"e785754f"},{"idioma":"fr","id":"fr-p164","tipo":"palavra","fr":"loin","en":"far","aceitasEn":["far","far away"],"distratoresEn":["near","slow","soon","deep"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Loin de», far from: «c'est loin d'ici ?», is it far from here? Near is «près».","v":"d8945603"},{"idioma":"fr","id":"fr-p165","tipo":"palavra","fr":"là","en":"there","aceitasEn":["there","over there","here"],"distratoresEn":["far","near","like this","inside"],"nivel":"A1","tags":["cotidiano"],"notaEn":"There, and in everyday speech also here: «je suis là», I'm here; «il n'est pas là», he's not in. The accent sets it apart from the article «la».","v":"d6194272"},{"idioma":"fr","id":"fr-p166","tipo":"palavra","fr":"malade","en":"sick","aceitasEn":["sick","ill"],"distratoresEn":["evil","crazy","tired","injured"],"nivel":"A1","tags":["adjetivo","saúde"],"notaEn":"Same form for masculine and feminine: «il est malade», «elle est malade». An illness is «la maladie», like English «malady».","v":"4b4312f5"},{"idioma":"fr","id":"fr-p167","tipo":"palavra","fr":"mettre","en":"to put","aceitasEn":["to put","put","to place","to put on","put on"],"distratoresEn":["to meet","to measure","to kill","to remove"],"nivel":"A1","tags":["verbo"],"notaEn":"To put, and also to put on clothes: «mettre un manteau». Irregular: je mets, nous mettons; participle «mis».","v":"61232edf"},{"idioma":"fr","id":"fr-p168","tipo":"palavra","fr":"mourir","en":"to die","aceitasEn":["to die","die","to pass away"],"distratoresEn":["to live","to be born","to move","to murmur"],"nivel":"A2","tags":["verbo"],"notaEn":"It takes «être», with an irregular participle: «il est mort», he died. The stem changes in the present: je meurs, nous mourons.","v":"562f7109"},{"idioma":"fr","id":"fr-p169","tipo":"palavra","fr":"ouvrir","en":"to open","aceitasEn":["to open","open"],"distratoresEn":["to hear","to close","to cover","to offer"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"Conjugated like an «-er» verb in the present (j'ouvre, il ouvre); past participle «ouvert». «Offrir» and «couvrir» work the same way.","v":"318c9992"},{"idioma":"fr","id":"fr-p170","tipo":"palavra","fr":"payer","en":"to pay","aceitasEn":["to pay","pay","to pay for","pay for"],"distratoresEn":["to weigh","to charge","to spend","to borrow"],"nivel":"A1","tags":["verbo","compras"],"notaEn":"No «for»: «payer le café», to pay for the coffee. Both «je paie» and «je paye» are correct.","v":"7a07a6cb"},{"idioma":"fr","id":"fr-p171","tipo":"palavra","fr":"pleuvoir","en":"to rain","aceitasEn":["to rain","rain"],"distratoresEn":["to cry","to snow","to thunder","to blow"],"nivel":"A1","tags":["verbo","natureza"],"notaEn":"Only with «il»: «il pleut», it's raining; participle «plu». Don't mix it up with «pleurer», to cry.","v":"652da57e"},{"idioma":"fr","id":"fr-p172","tipo":"palavra","fr":"regarder","en":"to look at / to watch","aceitasEn":["to look","look","to look at","look at","to watch","watch"],"distratoresEn":["to guard / to keep","to remember / to recall","to hear / to listen","to search / to seek"],"nivel":"A1","tags":["verbo"],"notaEn":"To look at and to watch, with no preposition: «regarde-moi», look at me; «regarder la télé», to watch TV. To see is «voir».","v":"fc310df9"},{"idioma":"fr","id":"fr-p173","tipo":"palavra","fr":"rouge","en":"red","aceitasEn":["red"],"distratoresEn":["purple","pink","orange","rough"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for masculine and feminine. Red wine is «vin rouge»; lipstick, «le rouge à lèvres».","v":"66d1a20b"},{"idioma":"fr","id":"fr-p174","tipo":"palavra","fr":"réserver","en":"to book","aceitasEn":["to book","to reserve","reserve"],"distratoresEn":["to solve","to reveal","to receive","to cancel"],"nivel":"A1","tags":["verbo","viagem"],"notaEn":"For tables, rooms and tickets: «réserver une table». A booking is «la réservation».","v":"50879dd3"},{"idioma":"fr","id":"fr-p175","tipo":"palavra","fr":"s'appeler","en":"to be called","aceitasEn":["to be called","be called","to be named","be named"],"distratoresEn":["to appeal","to keep quiet","to remember","to complain"],"nivel":"A1","tags":["verbo","social"],"notaEn":"The «l» doubles before a silent ending: je m'appelle, il s'appelle, but nous nous appelons. Without the pronoun, «appeler» means to call.","v":"b49d93fb"},{"idioma":"fr","id":"fr-p176","tipo":"palavra","fr":"se coucher","en":"to go to bed","aceitasEn":["to go to bed","go to bed","to lie down","lie down"],"distratoresEn":["to get up","to sit down","to hide","to get dressed"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"To go to bed or lie down; actually sleeping is «dormir». The sun «se couche» too: it sets. Past tense with «être»: «ils se sont couchés».","v":"7c2d8277"},{"idioma":"fr","id":"fr-p177","tipo":"palavra","fr":"se lever","en":"to get up","aceitasEn":["to get up","get up","to stand up","stand up","to rise"],"distratoresEn":["to go to bed","to wake up","to sit down","to wash up"],"nivel":"A1","tags":["verbo","casa"],"notaEn":"Out of bed or out of a chair: «je me lève à sept heures». Waking up is a different verb, «se réveiller». The «e» takes a grave accent before a silent ending: «je me lève», but «nous nous levons».","v":"5efcae60"},{"idioma":"fr","id":"fr-p178","tipo":"palavra","fr":"sept","en":"seven","aceitasEn":["seven","7"],"distratoresEn":["seventy","six","seventeen","eight"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The «p» is silent and the «t» is heard: «set». In September, «septembre», the «p» is pronounced.","v":"f715b47e"},{"idioma":"fr","id":"fr-p179","tipo":"palavra","fr":"six","en":"six","aceitasEn":["six","6"],"distratoresEn":["seven","ten","sixteen","sixty"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Like «dix»: on its own it sounds like «seess»; before a consonant the «x» goes silent («six livres»); before a vowel it sounds like «z» («six heures»).","v":"9e4ede42"},{"idioma":"fr","id":"fr-p180","tipo":"palavra","fr":"tard","en":"late","aceitasEn":["late"],"distratoresEn":["early","soon","slow","before"],"nivel":"A1","tags":["cotidiano"],"notaEn":"The adverb: «je suis rentré tard», I got home late. «Plus tard», later. Being late for something is «être en retard».","v":"27f63f4b"},{"idioma":"fr","id":"fr-p181","tipo":"palavra","fr":"tôt","en":"early","aceitasEn":["early"],"distratoresEn":["late","all","near","slowly"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Early: «je me lève tôt», I get up early. «Tôt ou tard», sooner or later; «plus tôt», earlier.","v":"c966c2bc"},{"idioma":"fr","id":"fr-p182","tipo":"palavra","fr":"vendre","en":"to sell","aceitasEn":["to sell","sell"],"distratoresEn":["to win","to lend","to buy","to rent"],"nivel":"A1","tags":["verbo","compras"],"notaEn":"Conjugated like «attendre»: je vends, il vend, nous vendons; participle «vendu». «À vendre», for sale.","v":"cc0aad29"},{"idioma":"fr","id":"fr-p183","tipo":"palavra","fr":"voyager","en":"to travel","aceitasEn":["to travel","travel"],"distratoresEn":["to watch over","to fly","to wander","to visit"],"nivel":"A1","tags":["verbo","viagem"],"notaEn":"Like «manger», it adds an «e» in «nous voyageons». A trip is «le voyage»: «bon voyage !».","v":"d42d9165"},{"idioma":"fr","id":"fr-p184","tipo":"palavra","fr":"écrire","en":"to write","aceitasEn":["to write","write"],"distratoresEn":["to choose","to listen","to hide","to read"],"nivel":"A1","tags":["verbo","escola"],"notaEn":"The initial «é» marks a lost «s», as in «scribe». Irregular: j'écris, nous écrivons; participle «écrit».","v":"849bda16"},{"idioma":"fr","id":"fr-p185","tipo":"palavra","fr":"le lit","en":"the bed","aceitasEn":["bed","the bed"],"distratoresEn":["the list","the hammock","the pillow","the chair"],"nivel":"A1","tags":["casa"],"notaEn":"The «t» is silent: «lee». «Aller au lit», to go to bed. A riverbed is «le lit» too.","v":"ae176e13"},{"idioma":"fr","id":"fr-p186","tipo":"palavra","fr":"la porte","en":"the door","aceitasEn":["door","the door"],"distratoresEn":["the port","the wall","the window","the bridge"],"nivel":"A1","tags":["casa"],"notaEn":"Feminine. «Fermer la porte», to close the door. A port is «le port»; the verb «porter» means to carry or wear.","v":"958d3216"},{"idioma":"fr","id":"fr-p187","tipo":"palavra","fr":"le chat","en":"the cat","aceitasEn":["cat","the cat"],"distratoresEn":["the dog","the mouse","the duck","the hat"],"nivel":"A1","tags":["animais"],"notaEn":"The «t» is silent: «shah». A kitten is «le chaton».","v":"94837d9c"},{"idioma":"fr","id":"fr-p188","tipo":"palavra","fr":"la gare","en":"the train station","aceitasEn":["train station","the station","station","the railway station","railway station"],"distratoresEn":["the garage","the season","the airport","the bus stop"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Feminine. A train station; a subway station is «la station». «La gare routière», the bus station.","v":"c4d5b8e5"},{"idioma":"fr","id":"fr-p189","tipo":"palavra","fr":"le lait","en":"milk","aceitasEn":["milk","the milk"],"distratoresEn":["cheese","juice","yogurt","lake"],"nivel":"A1","tags":["comida"],"notaEn":"The final «t» is silent. «Un café au lait», a coffee with milk.","v":"7aa7dbd5"},{"idioma":"fr","id":"fr-p190","tipo":"palavra","fr":"la semaine","en":"the week","aceitasEn":["week","the week"],"distratoresEn":["the seed","the fortnight","the session","the season"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«La semaine prochaine», next week; «en semaine», on weekdays. The weekend is «le week-end».","v":"bb7dd311"},{"idioma":"fr","id":"fr-p191","tipo":"palavra","fr":"la main","en":"the hand","aceitasEn":["hand","the hand"],"distratoresEn":["the arm","the finger","the sleeve","the mane"],"nivel":"A1","tags":["corpo"],"notaEn":"Feminine. «À la main», by hand; «se serrer la main», to shake hands.","v":"3f94ae8b"},{"idioma":"fr","id":"fr-p192","tipo":"palavra","fr":"le prix","en":"the price / the prize","aceitasEn":["price","the price","prize","the prize","the award"],"distratoresEn":["the prison / the jail","the deadline / the date","the rush / the hurry","the change / the bill"],"nivel":"A1","tags":["compras"],"notaEn":"Both price and prize: «le prix du pain», «le prix Nobel». The «x» is silent, and the plural is the same: «les prix».","v":"964ea02a"},{"idioma":"fr","id":"fr-p193","tipo":"palavra","fr":"trouver","en":"to find","aceitasEn":["to find","find"],"distratoresEn":["to trade","to trip","to bring","to lose"],"nivel":"A1","tags":["verbo"],"notaEn":"To find: «j'ai trouvé mes clés». Also for opinions: «je trouve que c'est cher», I find it expensive. To look for is «chercher».","v":"8056b24c"},{"idioma":"fr","id":"fr-p194","tipo":"palavra","fr":"demander","en":"to ask / to ask for","aceitasEn":["to ask","ask","to ask for","ask for","to request"],"distratoresEn":["to send / to order","to answer / to reply","to give / to offer","to delay / to linger"],"nivel":"A1","tags":["verbo"],"notaEn":"Both to ask and to ask for: «demander l'addition», to ask for the check; «demander l'heure», to ask the time. To demand forcefully is «exiger».","v":"37fe95d5"},{"idioma":"fr","id":"fr-p195","tipo":"palavra","fr":"donner","en":"to give","aceitasEn":["to give","give","to hand","to donate"],"distratoresEn":["to dominate","to tame","to take","to fold"],"nivel":"A1","tags":["verbo"],"notaEn":"Regular «-er» verb: je donne, nous donnons. «Donner sur», to look out onto: «la chambre donne sur la mer», the room faces the sea.","v":"a57a8a48"},{"idioma":"fr","id":"fr-p196","tipo":"palavra","fr":"commencer","en":"to begin","aceitasEn":["to begin","begin","to start","start"],"distratoresEn":["to comment","to trade","to combine","to finish"],"nivel":"A1","tags":["verbo"],"notaEn":"The «c» takes a cedilla before «a» and «o»: «nous commençons». Before an infinitive, use «à»: «il commence à pleuvoir», it's starting to rain.","v":"6eeceead"},{"idioma":"fr","id":"fr-p197","tipo":"palavra","fr":"oublier","en":"to forget","aceitasEn":["to forget","forget"],"distratoresEn":["to oblige","to obey","to remember","to publish"],"nivel":"A1","tags":["verbo"],"notaEn":"Things come straight after it: «j'ai oublié mes clés», I forgot my keys. Before an infinitive, «de»: «j'ai oublié de payer», I forgot to pay.","v":"a5ce69bc"},{"idioma":"fr","id":"fr-p198","tipo":"palavra","fr":"penser","en":"to think","aceitasEn":["to think","think"],"distratoresEn":["to weigh","to comb","to stroll","to fish"],"nivel":"A1","tags":["verbo"],"notaEn":"«Je pense que oui», I think so. «Penser à» is to think about, and also to remember to: «pense à acheter du pain», remember to buy bread.","v":"8ccfb16b"},{"idioma":"fr","id":"fr-p199","tipo":"palavra","fr":"cher","aceitasFr":["chère"],"en":"expensive / dear","aceitasEn":["expensive","dear","pricey"],"distratoresEn":["cheap / affordable","clear / obvious","full / crowded","boring / dull"],"nivel":"A1","tags":["adjetivo","compras"],"notaEn":"Feminine «chère». Expensive: «c'est trop cher». Before a name, dear: «chère Marie», at the start of a letter.","v":"12a5869f"},{"idioma":"fr","id":"fr-p200","tipo":"palavra","fr":"facile","en":"easy","aceitasEn":["easy"],"distratoresEn":["difficult","fragile","faithful","fertile"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for masculine and feminine. The opposite is «difficile». «C'est facile à dire», easier said than done.","v":"03f27634"},{"idioma":"fr","id":"fr-p201","tipo":"palavra","fr":"libre","en":"free","aceitasEn":["free","available","vacant"],"distratoresEn":["light","clean","pretty","slow"],"nivel":"A1","tags":["adjetivo"],"notaEn":"Same form for masculine and feminine: «la place est libre ?», is this seat free? Free of charge is «gratuit».","v":"24e89a45"},{"idioma":"fr","id":"fr-p202","tipo":"palavra","fr":"encore","en":"still / again","aceitasEn":["still","again","more","yet"],"distratoresEn":["now / today","before / after","never / ever","soon / early"],"nivel":"A1","tags":["cotidiano"],"notaEn":"Still («il dort encore», he's still asleep; «pas encore», not yet), again («encore une fois») and more («encore du café ?»).","v":"3363b894"},{"idioma":"fr","id":"fr-p203","tipo":"palavra","fr":"peut-être","en":"maybe","aceitasEn":["maybe","perhaps"],"distratoresEn":["surely","never","also","later"],"nivel":"A1","tags":["cotidiano"],"notaEn":"With a hyphen. Without it, «peut être» is the verb, can be: «il peut être malade», he may be sick.","v":"89451953"},{"idioma":"fr","id":"fr-p204","tipo":"palavra","fr":"parfois","en":"sometimes","aceitasEn":["sometimes","at times","occasionally"],"distratoresEn":["always","never","often","rarely"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Parfois je cuisine», sometimes I cook. «Quelquefois» means the same; often is «souvent».","v":"09bb8f91"},{"idioma":"fr","id":"fr-u142","tipo":"frase","requer":"fr-p185","fr":"Il est encore au lit.","en":"He's still in bed.","aceitasEn":["hes still in bed","he is still in bed","hes still lying in bed"],"distratoresEn":["He's still in the living room.","He's still in the kitchen.","He's still at school.","He's still at the beach."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"In bed is «au lit» («à» + «le»): «aller au lit», to go to bed. «Encore» here means still; it can also mean again.","requerTodas":["fr-p001","fr-p202","fr-p185"],"v":"7e72bbe2"},{"idioma":"fr","id":"fr-u143","tipo":"frase","requer":"fr-p187","fr":"Le chat dort sur le canapé.","en":"The cat is sleeping on the couch.","aceitasEn":["the cat is sleeping on the couch","the cats sleeping on the couch","the cat is sleeping on the sofa","the cat sleeps on the couch","the cat sleeps on the sofa"],"distratoresEn":["The dog is sleeping on the couch.","The baby is sleeping on the couch.","Grandpa is sleeping on the couch.","The boy is sleeping on the couch."],"nivel":"A1","tags":["animais","casa"],"notaEn":"«Chat» is pronounced «shah», with a silent «t». «Sur» means on: «sur le canapé», on the couch; «sur la table», on the table.","requerTodas":["fr-p187","fr-p109","+le canapé"],"v":"4e41e6c2"},{"idioma":"fr","id":"fr-u144","tipo":"frase","requer":"fr-p186","fr":"Ferme la porte, s'il te plaît.","en":"Close the door, please.","aceitasEn":["close the door please","please close the door","shut the door please","close the door","please shut the door"],"distratoresEn":["Close the window, please.","Close the box, please.","Close the suitcase, please.","Close the curtain, please."],"nivel":"A1","tags":["casa"],"notaEn":"«Ferme», from «fermer», is the «tu» imperative, hence «s'il te plaît». With «vous»: «fermez la porte, s'il vous plaît».","requerTodas":["+fermer","fr-p186"],"v":"496bf616"},{"idioma":"fr","id":"fr-u145","tipo":"frase","requer":"fr-p188","fr":"Je t'attends à la gare.","en":"I'll wait for you at the station.","aceitasEn":["ill wait for you at the station","i will wait for you at the station","im waiting for you at the station","ill wait for you at the train station","ill meet you at the station","ill be waiting for you at the station"],"distratoresEn":["I'll wait for you at the square.","I'll wait for you on the corner.","I'll wait for you at the bakery.","I'll wait for you at school."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«La gare» is only the train station; a subway station is «la station», and the bus station «la gare routière». «Attendre» takes no «for»: «je t'attends».","requerTodas":["fr-p018","fr-p188"],"v":"2a168a9c"},{"idioma":"fr","id":"fr-u146","tipo":"frase","requer":"fr-p189","fr":"Il n'y a plus de lait dans le frigo.","en":"There's no more milk in the fridge.","aceitasEn":["theres no more milk in the fridge","there is no more milk in the fridge","theres no milk left in the fridge","there isnt any more milk in the fridge","were out of milk","we are out of milk"],"distratoresEn":["There's no more juice in the fridge.","There's no more cheese in the fridge.","There's no more yogurt in the fridge.","There's no more ham in the fridge."],"nivel":"A1","tags":["comida","casa"],"notaEn":"«Ne… plus» means no more: «il n'y a plus de lait». After a negative, «du» becomes «de». «Le frigo» is the everyday word for fridge.","requerTodas":["fr-p002","fr-p189","+le frigo"],"v":"05732bd5"},{"idioma":"fr","id":"fr-u147","tipo":"frase","requer":"fr-p190","fr":"Je suis là toute la semaine.","en":"I'm here all week.","aceitasEn":["im here all week","i am here all week","im here the whole week","ill be here all week","i will be here all week"],"distratoresEn":["I'm here all night.","I'm here all afternoon.","I'm here all morning.","I'm here all season."],"nivel":"A1","tags":["cotidiano"],"notaEn":"All week is «toute la semaine», with «tout» in the feminine. Every week is «chaque semaine» or «toutes les semaines».","requerTodas":["fr-p001","fr-p165","fr-p070","fr-p190"],"v":"3ade17ae"},{"idioma":"fr","id":"fr-u148","tipo":"frase","requer":"fr-p191","fr":"Lave-toi les mains !","en":"Wash your hands!","aceitasEn":["wash your hands","go wash your hands"],"distratoresEn":["Wash your ears!","Wash your legs!","Wash your feet!","Wash your knees!"],"nivel":"A1","tags":["corpo","casa"],"notaEn":"With body parts, French uses a reflexive verb and «les», not «your»: «lave-toi les mains», literally wash yourself the hands.","requerTodas":["+se laver","fr-p191"],"v":"08ccbe28"},{"idioma":"fr","id":"fr-u149","tipo":"frase","requer":"fr-p192","fr":"Quel est le prix de cette chemise ?","en":"What's the price of this shirt?","aceitasEn":["whats the price of this shirt","what is the price of this shirt","how much is this shirt","how much does this shirt cost"],"distratoresEn":["What's the size of this shirt?","What's the fabric of this shirt?","What's the style of this shirt?","What's the number of this shirt?"],"nivel":"A1","tags":["compras","roupa"],"notaEn":"«Le prix» is both the price and the prize: «le prix Nobel». «La chemise» is a shirt; a T-shirt is «le t-shirt».","requerTodas":["fr-p001","fr-p192","+la chemise"],"v":"3531740e"},{"idioma":"fr","id":"fr-u150","tipo":"frase","requer":"fr-p192","fr":"Elle a gagné le premier prix.","en":"She won first prize.","aceitasEn":["she won first prize","she won the first prize","she took first prize","shes won first prize"],"distratoresEn":["She won the first game.","She won the first round.","She won the first set.","She won the first challenge."],"nivel":"A2","tags":["cotidiano","cultura"],"notaEn":"Here «le prix» is the prize, not the price. «Gagner» is to win and also to earn: «gagner sa vie», to earn a living.","requerTodas":["fr-p002","+gagner","+premier","fr-p192"],"v":"0582a6b7"},{"idioma":"fr","id":"fr-u151","tipo":"frase","requer":"fr-p193","fr":"Je ne trouve pas mon portable.","en":"I can't find my phone.","aceitasEn":["i cant find my phone","i cant find my cell phone","i cannot find my phone","i cant find my cellphone","i cant find my mobile"],"distratoresEn":["I can't find my charger.","I can't find my coat.","I can't find my umbrella.","I can't find my passport."],"nivel":"A1","tags":["objetos","tecnologia"],"notaEn":"To find is «trouver»; to look for is «chercher». «Le portable» is a cell phone; in Quebec, «le cellulaire».","requerTodas":["fr-p193","+le portable"],"v":"fcf8079e"},{"idioma":"fr","id":"fr-u152","tipo":"frase","requer":"fr-p193","fr":"Je trouve ce film génial.","en":"I think this movie is great.","aceitasEn":["i think this movie is great","i find this movie great","i think this film is great","i find this film great","i think this movie is amazing","i think this movie is brilliant"],"distratoresEn":["I think this movie is boring.","I think this movie is long.","I think this movie is sad.","I think this movie is weird."],"nivel":"A2","tags":["cultura"],"notaEn":"«Trouver» also gives an opinion, like to find in English: «je trouve ce film génial», I find this movie great. «Tu trouves ?» is do you think so?","requerTodas":["fr-p193","fr-p100","fr-p099"],"v":"5c66e912"},{"idioma":"fr","id":"fr-u153","tipo":"frase","requer":"fr-p194","fr":"Je peux te demander quelque chose ?","en":"Can I ask you something?","aceitasEn":["can i ask you something","can i ask you a question","could i ask you something","may i ask you something"],"distratoresEn":["Can I tell you something?","Can I show you something?","Can I give you something?","Can I bring you something?"],"nivel":"A1","tags":["social"],"notaEn":"«Demander» is to ask, both a question and for something: «demander l'heure», to ask the time; «demander de l'aide», to ask for help. It doesn't mean to demand.","requerTodas":["fr-p006","fr-p194"],"v":"a2b97e77"},{"idioma":"fr","id":"fr-u154","tipo":"frase","requer":"fr-p194","fr":"Je vais demander de l'aide.","en":"I'm going to ask for help.","aceitasEn":["im going to ask for help","i am going to ask for help","ill ask for help","i will ask for help","im gonna ask for help"],"distratoresEn":["I'm going to offer help.","I'm going to accept help.","I'm going to refuse help.","I'm going to look for help."],"nivel":"A1","tags":["social","cotidiano"],"notaEn":"To ask for something is «demander quelque chose», with no «for»; the person takes «à»: «demander de l'aide à un ami».","requerTodas":["fr-p003","fr-p194","+l'aide"],"v":"a228ddab"},{"idioma":"fr","id":"fr-u155","tipo":"frase","requer":"fr-p195","fr":"Tu peux me donner un coup de main ?","en":"Can you give me a hand?","aceitasEn":["can you give me a hand","could you give me a hand","can you lend me a hand","could you lend me a hand"],"distratoresEn":["Can you give me a hug?","Can you give me a ride?","Can you give me a minute?","Can you give me a push?"],"nivel":"A2","tags":["social","expressão"],"notaEn":"«Un coup de main» is a hand, some quick help. «Le coup» is a blow, and it turns up in many expressions: «un coup de fil», a phone call.","requerTodas":["fr-p006","fr-p195","+le coup","fr-p191"],"v":"5d77f671"},{"idioma":"fr","id":"fr-u156","tipo":"frase","requer":"fr-p195","fr":"Il m'a donné son numéro.","en":"He gave me his number.","aceitasEn":["he gave me his number","he gave me his phone number","hes given me his number","he has given me his number"],"distratoresEn":["He gave me his address.","He gave me his email.","He gave me his coat.","He gave me his book."],"nivel":"A1","tags":["social","tecnologia"],"notaEn":"«Son» can mean his or her: the possessive agrees with the thing («le numéro»), not with the owner. «Me» becomes «m'» before a vowel.","requerTodas":["fr-p002","fr-p195","+le numéro"],"v":"7e054fb6"},{"idioma":"fr","id":"fr-u157","tipo":"frase","requer":"fr-p196","fr":"Le film commence à huit heures.","en":"The movie starts at eight.","aceitasEn":["the movie starts at eight","the movie begins at eight","the film starts at eight","the film begins at eight","the movie starts at 8","the movie starts at eight oclock"],"distratoresEn":["The movie ends at eight.","The movie restarts at eight.","The movie stops at eight.","The movie comes back at eight."],"nivel":"A1","tags":["cultura","cotidiano"],"notaEn":"To start is «commencer», like commence. Before «a» and «o», the «c» takes a cedilla to keep its «s» sound: «nous commençons».","requerTodas":["fr-p100","fr-p196","fr-p126","fr-p129"],"v":"29ebfeb6"},{"idioma":"fr","id":"fr-u158","tipo":"frase","requer":"fr-p196","fr":"Il commence à pleuvoir.","en":"It's starting to rain.","aceitasEn":["its starting to rain","it is starting to rain","its beginning to rain","it is beginning to rain","its starting to rain now"],"distratoresEn":["The rain is stopping.","It's raining again.","It looks like rain.","It's about to rain."],"nivel":"A1","tags":["natureza"],"notaEn":"To start doing something is «commencer à» + infinitive. «Pleuvoir» only exists with «il»: «il pleut», it's raining.","requerTodas":["fr-p196","fr-p171"],"v":"7c41871f"},{"idioma":"fr","id":"fr-u159","tipo":"frase","requer":"fr-p197","fr":"N'oublie pas ton passeport !","en":"Don't forget your passport!","aceitasEn":["dont forget your passport","do not forget your passport","dont forget the passport"],"distratoresEn":["Don't forget your coat!","Don't forget your phone!","Don't forget your umbrella!","Don't forget your charger!"],"nivel":"A1","tags":["viagem"],"notaEn":"In a negative command, «ne… pas» wraps the verb: «n'oublie pas». It's the «tu» form, without the «s» of the present: «tu oublies».","requerTodas":["fr-p197","+le passeport"],"v":"41aaccad"},{"idioma":"fr","id":"fr-u160","tipo":"frase","requer":"fr-p197","fr":"J'ai oublié son nom.","en":"I forgot his name.","aceitasEn":["i forgot his name","i forgot her name","ive forgotten his name","ive forgotten her name","i have forgotten his name","i have forgotten her name"],"distratoresEn":["I forgot his number.","I forgot his birthday.","I forgot his face.","I forgot his address."],"nivel":"A1","tags":["social"],"notaEn":"«Son nom» can be his or her name. «Le nom» is also the surname: on a form, «nom et prénom» means last name and first name.","requerTodas":["fr-p002","fr-p197","+le nom"],"v":"1111258b"},{"idioma":"fr","id":"fr-u161","tipo":"frase","requer":"fr-p198","fr":"Je pense que oui.","en":"I think so.","aceitasEn":["i think so","i believe so","i guess so"],"distratoresEn":["I hope so.","I know.","Of course.","I doubt it."],"nivel":"A1","tags":["social","cotidiano"],"notaEn":"I think so is «je pense que oui», literally I think that yes; I don't think so is «je pense que non».","requerTodas":["fr-p198"],"v":"b03827c2"},{"idioma":"fr","id":"fr-u162","tipo":"frase","requer":"fr-p198","fr":"Je pense à toi.","en":"I'm thinking of you.","aceitasEn":["im thinking of you","i am thinking of you","im thinking about you","i am thinking about you","i think of you","i think about you"],"distratoresEn":["I trust you.","I believe in you.","I need you.","I dream of you."],"nivel":"A1","tags":["social","família"],"notaEn":"To think of or about is «penser à»: «je pense à toi», «je pense à mes vacances». After a preposition, you is «toi», not «tu».","requerTodas":["fr-p198"],"v":"d39e7091"},{"idioma":"fr","id":"fr-u163","tipo":"frase","requer":"fr-p199","fr":"C'est trop cher.","en":"It's too expensive.","aceitasEn":["its too expensive","it is too expensive","thats too expensive","that is too expensive","its way too expensive"],"distratoresEn":["It's too cheap.","It's too small.","It's too heavy.","It's too big."],"nivel":"A1","tags":["compras"],"notaEn":"«Cher» means expensive, and also dear: «cher ami». Cheap is «pas cher», or «bon marché».","requerTodas":["fr-p001","fr-p061","fr-p199"],"v":"e7bd40e5"},{"idioma":"fr","id":"fr-u164","tipo":"frase","requer":"fr-p199","fr":"Chère Julie, je t'écris de Paris.","en":"Dear Julie, I'm writing to you from Paris.","aceitasEn":["dear julie im writing to you from paris","dear julie im writing from paris","dear julie i am writing to you from paris","dear julie i am writing from paris"],"distratoresEn":["Hi Julie, I'm writing to you from Paris.","Poor Julie, I'm writing to you from Paris.","Lovely Julie, I'm writing to you from Paris.","Little Julie, I'm writing to you from Paris."],"nivel":"A2","tags":["social","cotidiano"],"notaEn":"Opening a letter, «cher» is dear, and it agrees: «cher Paul», «chère Julie». To write to someone is «écrire à»: «je t'écris», I'm writing to you.","requerTodas":["fr-p199","fr-p184"],"v":"850d7785"},{"idioma":"fr","id":"fr-u165","tipo":"frase","requer":"fr-p200","fr":"Ce n'est pas facile.","aceitasFr":["C'est pas facile."],"en":"It's not easy.","aceitasEn":["its not easy","it isnt easy","it is not easy","thats not easy","that is not easy","that isnt easy"],"distratoresEn":["It's not hard.","It's not possible.","It's not fair.","It's not normal."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Ce n'est pas» is the negative of «c'est»; in speech it's often «c'est pas facile». «Facile» is the same in the masculine and feminine.","requerTodas":["fr-p001","fr-p200"],"v":"fea9afb2"},{"idioma":"fr","id":"fr-u166","tipo":"frase","requer":"fr-p201","fr":"Cette place est libre ?","en":"Is this seat free?","aceitasEn":["is this seat free","is this seat available","is this seat empty","is this place free"],"distratoresEn":["Is this seat clean?","Is this seat comfortable?","Is this seat broken?","Is this seat wet?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«La place» is a seat or a spot — and also a town square: «la place de la Concorde». A parking space is «une place» too.","requerTodas":["+la place","fr-p001","fr-p201"],"v":"20888ce9"},{"idioma":"fr","id":"fr-u167","tipo":"frase","requer":"fr-p201","fr":"Tu es libre ce soir ?","en":"Are you free tonight?","aceitasEn":["are you free tonight","are you free this evening","you free tonight"],"distratoresEn":["Are you tired tonight?","Are you alone tonight?","Are you excited tonight?","Are you nervous tonight?"],"nivel":"A1","tags":["social"],"notaEn":"Having no plans is «être libre». Tonight is «ce soir»; «cette nuit» is the night you sleep through.","requerTodas":["fr-p001","fr-p201","fr-p160"],"v":"6aa5254e"},{"idioma":"fr","id":"fr-u168","tipo":"frase","requer":"fr-p203","fr":"Il va peut-être pleuvoir.","aceitasFr":["Peut-être qu'il va pleuvoir.","Il pleuvra peut-être."],"en":"It might rain.","aceitasEn":["it might rain","maybe itll rain","maybe it will rain","it may rain","it could rain","maybe its going to rain","maybe it is going to rain"],"distratoresEn":["I doubt it'll rain.","I hope it rains.","It shouldn't rain.","It's definitely going to rain."],"nivel":"A1","tags":["natureza"],"notaEn":"«Peut-être», maybe, goes between the helper verb and the infinitive: «il va peut-être pleuvoir». At the start of the sentence it takes «que»: «peut-être qu'il va pleuvoir».","requerTodas":["fr-p003","fr-p203","fr-p171"],"v":"3b1fdfbf"},{"idioma":"fr","id":"fr-u169","tipo":"frase","requer":"fr-p204","fr":"Parfois, je viens à vélo.","aceitasFr":["Je viens parfois à vélo.","Parfois, je viens en vélo."],"en":"Sometimes I come by bike.","aceitasEn":["sometimes i come by bike","sometimes i come by bicycle","i sometimes come by bike","sometimes i bike here","sometimes i ride my bike here"],"distratoresEn":["I always come by bike.","I never come by bike.","I rarely come by bike.","I come by bike every day."],"nivel":"A1","tags":["cotidiano","cidade"],"notaEn":"Sometimes is «parfois», one word. By bike is «à vélo», like «à pied»; by car, «en voiture».","requerTodas":["fr-p204","fr-p009","+le vélo"],"v":"c6df4060"},{"idioma":"fr","id":"fr-u170","tipo":"frase","requer":"fr-p202","fr":"Je n'ai pas encore mangé.","en":"I haven't eaten yet.","aceitasEn":["i havent eaten yet","i have not eaten yet","i didnt eat yet","i still havent eaten"],"distratoresEn":["I haven't eaten today.","I've hardly eaten.","I haven't eaten either.","I didn't eat yesterday."],"nivel":"A1","tags":["comida","gramática"],"notaEn":"Not yet is «pas encore», with «encore» right after «pas»: «je n'ai pas encore mangé». The opposite is «déjà»: «j'ai déjà mangé».","requerTodas":["fr-p002","fr-p202","fr-p013"],"v":"30b74d3a"},{"idioma":"fr","id":"fr-u171","tipo":"frase","requer":"fr-p202","fr":"Tu es encore en retard !","en":"You're late again!","aceitasEn":["youre late again","you are late again","late again"],"distratoresEn":["You're very late!","You're a little late!","You're late today!","You're always late!"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Encore» also means again: «encore en retard», late again. «Être en retard» is to be late.","requerTodas":["fr-p001","fr-p202","fr-p085"],"v":"d043f153"},{"idioma":"fr","id":"fr-u172","tipo":"frase","requer":"fr-p118","fr":"Je vais chercher ma fille à l'école.","en":"I'm going to pick up my daughter from school.","aceitasEn":["im going to pick up my daughter from school","im going to pick my daughter up from school","ill pick up my daughter from school","im picking up my daughter from school","im going to get my daughter from school","im going to pick up my daughter at school"],"distratoresEn":["I'm going to take my daughter to school.","I'm going to drop my daughter off at school.","I'm going to visit my daughter at school.","I'm going to wait for my daughter at school."],"nivel":"A1","tags":["família","escola"],"notaEn":"«Aller chercher» is to go and get, to pick someone up: «je vais chercher ma fille». «La fille» means daughter and also girl.","requerTodas":["fr-p003","fr-p118","+la fille","fr-p106"],"v":"1e90ad87"},{"idioma":"fr","id":"fr-u173","tipo":"frase","requer":"fr-p119","fr":"Tu connais bien Paris ?","en":"Do you know Paris well?","aceitasEn":["do you know paris well","you know paris well"],"distratoresEn":["Do you like Paris?","Do you live in Paris?","Do you visit Paris?","Do you miss Paris?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"To know a person or a place is «connaître»; to know a fact or how to do something is «savoir». The «î» only shows up before a «t»: «il connaît», but «tu connais».","requerTodas":["fr-p119","fr-p044"],"v":"02286460"},{"idioma":"fr","id":"fr-u174","tipo":"frase","requer":"fr-p122","fr":"Il ne faut pas fumer ici.","en":"You can't smoke here.","aceitasEn":["you cant smoke here","you cannot smoke here","no smoking here","smoking is not allowed here","you mustnt smoke here","you are not allowed to smoke here","youre not allowed to smoke here"],"distratoresEn":["You don't have to smoke here.","You can smoke here.","You have to smoke here.","People usually smoke here."],"nivel":"A1","tags":["gramática","cotidiano"],"notaEn":"«Il ne faut pas» means you mustn't — not you don't have to. For that, French says «ce n'est pas la peine» or «pas besoin».","requerTodas":["fr-p122","+fumer","fr-p048"],"v":"df6bdcca"},{"idioma":"fr","id":"fr-u175","tipo":"frase","requer":"fr-p123","fr":"Tu as fini de manger ?","en":"Have you finished eating?","aceitasEn":["have you finished eating","are you done eating","did you finish eating","are you finished eating","have you finished"],"distratoresEn":["Have you stopped eating?","Have you started eating?","Have you tried eating?","Have you quit eating?"],"nivel":"A1","tags":["comida"],"notaEn":"To finish doing something is «finir de» + infinitive: «tu as fini de manger ?». The past participle of «finir» is «fini».","requerTodas":["fr-p002","fr-p123","fr-p013"],"v":"75774537"},{"idioma":"fr","id":"fr-u176","tipo":"frase","requer":"fr-p167","fr":"Mets ton manteau, il fait froid.","en":"Put your coat on, it's cold.","aceitasEn":["put your coat on its cold","put on your coat its cold","put your coat on it is cold","wear your coat its cold","put your coat on its cold out"],"distratoresEn":["Put your hat on, it's cold.","Put your sweater on, it's cold.","Put your vest on, it's cold.","Put your scarf on, it's cold."],"nivel":"A1","tags":["roupa","natureza"],"notaEn":"To put on clothes is «mettre»: «mets ton manteau». Cold weather takes «faire»: «il fait froid».","requerTodas":["fr-p167","+le manteau","fr-p004","fr-p080"],"v":"610d1e7c"},{"idioma":"fr","id":"fr-u177","tipo":"frase","requer":"fr-p167","fr":"Tu peux mettre la table ?","en":"Can you set the table?","aceitasEn":["can you set the table","could you set the table","can you lay the table","will you set the table"],"distratoresEn":["Can you clean the table?","Can you clear the table?","Can you dry the table?","Can you move the table?"],"nivel":"A1","tags":["casa","comida"],"notaEn":"To set the table is «mettre la table»; to clear it is «débarrasser la table».","requerTodas":["fr-p006","fr-p167","fr-p143"],"v":"e0748349"},{"idioma":"fr","id":"fr-u178","tipo":"frase","requer":"fr-p169","fr":"Le magasin ouvre à neuf heures.","en":"The store opens at nine.","aceitasEn":["the store opens at nine","the shop opens at nine","the store opens at 9","the store opens at nine oclock"],"distratoresEn":["The store closes at nine.","The store fills up at nine.","The store empties out at nine.","The store reopens at nine."],"nivel":"A1","tags":["compras","cidade"],"notaEn":"«Le magasin» is a store; «le magazine» is a magazine. «Ouvrir» is conjugated like an -er verb: «j'ouvre», «il ouvre».","requerTodas":["+le magasin","fr-p169","+neuf","fr-p129"],"v":"e9ecbea5"},{"idioma":"fr","id":"fr-u179","tipo":"frase","requer":"fr-p170","fr":"C'est moi qui paie.","aceitasFr":["C'est moi qui paye."],"en":"I'm paying.","aceitasEn":["im paying","i am paying","ill pay","i will pay","its on me","this is on me","ill get this","let me pay"],"distratoresEn":["I'm driving.","I'm cooking.","I'm choosing.","I'm in charge."],"nivel":"A1","tags":["compras","social"],"notaEn":"«C'est moi qui» stresses the I, and the verb agrees with «moi»: «c'est moi qui paie». «Payer» has two spellings: «je paie» and «je paye».","requerTodas":["fr-p001","fr-p170"],"v":"bae19b8e"},{"idioma":"fr","id":"fr-u180","tipo":"frase","requer":"fr-p172","fr":"Il regarde la télé.","en":"He's watching TV.","aceitasEn":["hes watching tv","he is watching tv","he watches tv","hes watching television","he is watching television"],"distratoresEn":["He's watching a soap opera.","He's watching soccer.","He's watching a series.","He's watching cartoons."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"To watch is «regarder», with no preposition: «regarder la télé», «regarder un film». «La télé» is the everyday word for TV.","requerTodas":["fr-p172","+la télé"],"v":"335f9b75"},{"idioma":"fr","id":"fr-u181","tipo":"frase","requer":"fr-p172","fr":"Je regarde seulement.","aceitasFr":["Je regarde juste.","Je ne fais que regarder."],"en":"I'm just looking.","aceitasEn":["im just looking","i am just looking","im only looking","just looking"],"distratoresEn":["I'm just trying it on.","I'm just asking.","I'm just waiting.","I'm just passing through."],"nivel":"A1","tags":["compras"],"notaEn":"The shop phrase to wave off a salesperson. «Seulement», only, goes after the verb; people also just say «je regarde, merci».","requerTodas":["fr-p172","+seulement"],"v":"5585c58d"},{"idioma":"fr","id":"fr-u182","tipo":"frase","requer":"fr-p174","fr":"J'ai réservé une chambre à l'hôtel.","en":"I booked a room at the hotel.","aceitasEn":["i booked a room at the hotel","i reserved a room at the hotel","ive booked a room at the hotel","i have booked a room at the hotel","i booked a hotel room","ive reserved a room at the hotel"],"distratoresEn":["I booked a taxi at the hotel.","I booked a tour at the hotel.","I booked a dinner at the hotel.","I booked a hall at the hotel."],"nivel":"A1","tags":["viagem"],"notaEn":"«La chambre» is a room — at a hotel, «une chambre simple» or «double». The «h» of «hôtel» is silent, hence «l'hôtel».","requerTodas":["fr-p002","fr-p174","fr-p107","+l'hôtel"],"v":"be70960e"},{"idioma":"fr","id":"fr-u183","tipo":"frase","requer":"fr-p184","fr":"Comment ça s'écrit ?","en":"How do you spell that?","aceitasEn":["how do you spell that","how do you spell it","how is that spelled","how is it spelled","how do you write that","how do you write it"],"distratoresEn":["How do you say that?","How do you read that?","How do you pronounce that?","What do you call that?"],"nivel":"A1","tags":["escola"],"notaEn":"The «se» of «s'écrire» makes it passive: «ça s'écrit», literally it writes itself. To spell out letter by letter is «épeler».","requerTodas":["fr-p184"],"v":"549e4c3f"},{"idioma":"fr","id":"fr-u184","tipo":"frase","requer":"fr-p158","fr":"J'ai mal aux pieds.","en":"My feet hurt.","aceitasEn":["my feet hurt","my feet are hurting","my feet are sore","my foot hurts"],"distratoresEn":["My knees hurt.","My shoulders hurt.","My eyes hurt.","My arms hurt."],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"In the plural, «à» + «les» becomes «aux»: «j'ai mal aux pieds», «aux dents». In the singular: «au pied», «à la tête».","requerTodas":["fr-p002","fr-p151","fr-p158"],"v":"3fb81614"},{"idioma":"fr","id":"fr-u185","tipo":"frase","requer":"fr-p166","fr":"Je suis tombé malade.","aceitasFr":["Je suis tombée malade."],"en":"I got sick.","aceitasEn":["i got sick","i fell ill","i became sick","i became ill","i got ill"],"distratoresEn":["I got tired.","I got nervous.","I got sad.","I got angry."],"nivel":"A1","tags":["saúde"],"notaEn":"To get sick is «tomber malade», literally to fall sick. «Tomber» takes «être» in the passé composé, and a woman writes «tombée».","requerTodas":["fr-p001","+tomber","fr-p166"],"v":"24600091"},{"idioma":"fr","id":"fr-u186","tipo":"frase","requer":"fr-p121","fr":"Ça fait dix euros.","en":"That's ten euros.","aceitasEn":["thats ten euros","that is ten euros","that comes to ten euros","its ten euros","it is ten euros","that will be ten euros","thatll be ten euros","thats 10 euros"],"distratoresEn":["That's six euros.","That's eight euros.","That's seven euros.","That's three euros."],"nivel":"A1","tags":["compras"],"notaEn":"At the till, «ça fait» gives the total: «ça fait dix euros». The «x» of «dix» sounds like «s» at the end of a sentence and like «z» before a vowel: «dix euros».","requerTodas":["fr-p004","fr-p121","fr-p128"],"v":"745a94b0"},{"idioma":"fr","id":"fr-u187","tipo":"frase","requer":"fr-p094","fr":"Il est trois heures.","en":"It's three o'clock.","aceitasEn":["its three oclock","its three","it is three oclock","its 3 oclock","it is three","its 3"],"distratoresEn":["It's two o'clock.","It's six o'clock.","It's eight o'clock.","It's ten o'clock."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Time is told with «il est» and the word «heures», which is never dropped: «il est trois heures». One o'clock is «il est une heure».","requerTodas":["fr-p001","fr-p094","fr-p129"],"v":"a3eb932e"},{"idioma":"fr","id":"fr-u188","tipo":"frase","requer":"fr-p115","fr":"J'arrive dans dix minutes.","en":"I'll be there in ten minutes.","aceitasEn":["ill be there in ten minutes","i will be there in ten minutes","ill arrive in ten minutes","ill be there in 10 minutes","im arriving in ten minutes","ill get there in ten minutes","ill be there in ten","ill be here in ten minutes"],"distratoresEn":["I got there ten minutes ago.","I'm leaving in ten minutes.","I'll be there at ten.","I'll be ten minutes late."],"nivel":"A1","tags":["cotidiano","viagem"],"notaEn":"«Dans» + a length of time means in: «dans dix minutes». Ten minutes ago is «il y a dix minutes». The present works for the near future: «j'arrive».","requerTodas":["fr-p115","fr-p121","fr-p139"],"v":"5f1d160d"},{"idioma":"fr","id":"fr-u189","tipo":"frase","requer":"fr-p115","fr":"J'arrive !","en":"Coming!","aceitasEn":["coming","im coming","i am coming","be right there","ill be right there","on my way","im on my way"],"distratoresEn":["I'm here!","Be right back!","I'm done!","I've left!"],"nivel":"A1","tags":["cotidiano","expressão"],"notaEn":"«J'arrive !» is what you call out when someone calls you: coming! It doesn't mean you've arrived — that's «je suis arrivé».","requerTodas":["fr-p115"],"v":"2f82bb98"},{"idioma":"fr","id":"fr-u190","tipo":"frase","requer":"fr-p115","fr":"Qu'est-ce qui est arrivé ?","aceitasFr":["Qu'est-ce qui s'est passé ?"],"en":"What happened?","aceitasEn":["what happened","what has happened","whats happened"],"distratoresEn":["What changed?","What fell?","What broke?","What disappeared?"],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Arriver» means to arrive and also to happen: «qu'est-ce qui est arrivé ?», what happened? It takes «être» in the passé composé.","requerTodas":["fr-p001","fr-p115"],"v":"1cd883db"},{"idioma":"fr","id":"fr-u191","tipo":"frase","requer":"fr-p129","fr":"Il arrive toujours à l'heure.","en":"He's always on time.","aceitasEn":["hes always on time","he is always on time","he always arrives on time","he always gets here on time","he always gets there on time","hes always punctual"],"distratoresEn":["He's always early.","He's always late.","He's always in a hurry.","He's always tired."],"nivel":"A1","tags":["cotidiano"],"notaEn":"On time is «à l'heure»; late, «en retard»; early, «en avance». «Toujours» goes after the verb: «il arrive toujours».","requerTodas":["fr-p115","fr-p046","fr-p129"],"v":"557ed0e2"},{"idioma":"fr","id":"fr-u192","tipo":"frase","requer":"fr-p129","fr":"À quelle heure on mange ?","aceitasFr":["On mange à quelle heure ?","À quelle heure est-ce qu'on mange ?","À quelle heure mange-t-on ?"],"en":"What time do we eat?","aceitasEn":["what time do we eat","what time are we eating","at what time do we eat","what time are we going to eat"],"distratoresEn":["Where do we eat?","Who do we eat with?","What do we eat?","How much do we eat?"],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"What time, for when something happens, is «à quelle heure», with «heure» singular. Asking the current time is «quelle heure est-il ?».","requerTodas":["fr-p129","fr-p013"],"v":"31725da5"},{"idioma":"fr","id":"fr-u193","tipo":"frase","requer":"fr-p148","fr":"J'ai cours de français le lundi.","en":"I have French class on Mondays.","aceitasEn":["i have french class on mondays","i have french on mondays","i have a french class on mondays","ive got french class on mondays","on mondays i have french class","i have french class every monday"],"distratoresEn":["I have a French test on Mondays.","I have French homework on Mondays.","I have a French talk on Mondays.","I have French review on Mondays."],"nivel":"A1","tags":["escola"],"notaEn":"«Avoir cours» is to have class, with no article. «Le lundi», with the article, means on Mondays; plain «lundi» means this coming Monday.","requerTodas":["fr-p002","fr-p148","fr-p054","fr-p084"],"v":"f8f2af02"},{"idioma":"fr","id":"fr-u194","tipo":"frase","requer":"fr-p140","fr":"J'ai une question.","en":"I have a question.","aceitasEn":["i have a question","ive got a question","i have got a question"],"distratoresEn":["I have an answer.","I have an idea.","I have a suggestion.","I have a complaint."],"nivel":"A1","tags":["escola"],"notaEn":"«La question» is a question; to ask one is «poser une question», literally to put a question.","requerTodas":["fr-p002","fr-p140"],"v":"6d07a9e6"},{"idioma":"fr","id":"fr-u195","tipo":"frase","requer":"fr-p151","fr":"Ça fait mal !","en":"It hurts!","aceitasEn":["it hurts","that hurts","ouch that hurts"],"distratoresEn":["It itches!","It burns!","It's tight!","It tickles!"],"nivel":"A1","tags":["saúde","corpo"],"notaEn":"To hurt is «faire mal»: «ça fait mal», it hurts; «tu me fais mal», you're hurting me. With a body part, «avoir mal à».","requerTodas":["fr-p004","fr-p151"],"v":"2fa24914"},{"idioma":"fr","id":"fr-u196","tipo":"frase","requer":"fr-p155","fr":"Il faut appeler un médecin.","en":"We need to call a doctor.","aceitasEn":["we need to call a doctor","we have to call a doctor","someone needs to call a doctor","we need to get a doctor","we must call a doctor","we need to call the doctor"],"distratoresEn":["We need to call a lawyer.","We need to call a firefighter.","We need to call a technician.","We need to call an electrician."],"nivel":"A1","tags":["saúde"],"notaEn":"To call, also on the phone, is «appeler»: «appeler un médecin», «je t'appelle demain». Two «p»s, and in «j'appelle» two «l»s as well.","requerTodas":["fr-p122","+appeler","fr-p155"],"v":"17f2e332"},{"idioma":"fr","id":"fr-u197","tipo":"frase","requer":"fr-p165","fr":"Il n'est pas là.","en":"He's not here.","aceitasEn":["hes not here","he isnt here","he is not here","hes not in","he isnt in","hes out"],"distratoresEn":["He's not well.","He's not ready.","He's not awake.","He's not alone."],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"On the phone or at the door, «il n'est pas là» means he's not in. «Là» works for here as well as there: «je suis là», I'm here.","requerTodas":["fr-p001","fr-p165"],"v":"ade198ac"},{"idioma":"fr","id":"fr-u198","tipo":"frase","requer":"fr-p139","fr":"Une minute, s'il vous plaît.","en":"One minute, please.","aceitasEn":["one minute please","just a minute please","one moment please","just a moment please","wait a minute please"],"distratoresEn":["One glass, please.","One ticket, please.","One receipt, please.","One fork, please."],"nivel":"A1","tags":["cotidiano","social"],"notaEn":"«Minute» is feminine: «une minute». To ask someone to hang on, you can also say «un instant» or «une seconde».","requerTodas":["fr-p139"],"v":"28e2a1c2"},{"idioma":"fr","id":"fr-u199","tipo":"frase","requer":"fr-p168","fr":"Je meurs de faim !","en":"I'm starving!","aceitasEn":["im starving","i am starving","im dying of hunger","im so hungry","im really hungry","im famished"],"distratoresEn":["I'm so sleepy!","I'm freezing!","I'm boiling!","I'm dying of laughter!"],"nivel":"A1","tags":["comida","expressão"],"notaEn":"French exaggerates with «mourir de», to die of: «je meurs de faim», I'm starving; «je meurs de froid», I'm freezing. Present: je meurs, nous mourons, ils meurent.","requerTodas":["fr-p168","fr-p086"],"v":"c56ed9d5"},{"idioma":"fr","id":"fr-u200","tipo":"frase","requer":"fr-p004","fr":"Ça fait longtemps !","en":"Long time no see!","aceitasEn":["long time no see","its been a long time","it has been a long time","its been a while","it has been a while","long time"],"distratoresEn":["That took forever!","What a surprise!","Just in time!","What nice weather!"],"nivel":"A1","tags":["social","expressão"],"notaEn":"«Ça fait longtemps», it's been a long time, is the greeting for someone you haven't seen in ages. «Longtemps», a long time, is one word.","requerTodas":["fr-p004","+longtemps"],"v":"dc9821c3"},{"idioma":"fr","id":"fr-u201","tipo":"frase","requer":"fr-p003","fr":"Je vais bien.","en":"I'm fine.","aceitasEn":["im fine","i am fine","im good","im well","i am well","im ok","im okay","im doing well"],"distratoresEn":["I'm sad.","I'm tired.","I'm busy.","I'm sick."],"nivel":"A1","tags":["social"],"notaEn":"To say how you are, French uses «aller», to go: «je vais bien», I'm fine; «comment vas-tu ?», how are you?","requerTodas":["fr-p003","fr-p044"],"v":"d4c16ef3"},{"idioma":"fr","id":"fr-u202","tipo":"frase","requer":"fr-p070","fr":"Tout va bien.","en":"Everything's fine.","aceitasEn":["everythings fine","everything is fine","everythings ok","everything is ok","everythings okay","its all good","all is well","everything is going well"],"distratoresEn":["Everything's ready.","Everything's wrong.","Everything's quiet.","Everything's clean."],"nivel":"A1","tags":["cotidiano"],"notaEn":"«Tout va bien», literally all goes well, is how you reassure someone. «Tout» here stands alone, with no article.","requerTodas":["fr-p070","fr-p003","fr-p044"],"v":"b793e6a2"},{"idioma":"fr","id":"fr-u203","tipo":"frase","requer":"fr-p131","fr":"Vous avez une carte de la ville ?","aceitasFr":["Vous avez un plan de la ville ?","Avez-vous une carte de la ville ?"],"en":"Do you have a map of the city?","aceitasEn":["do you have a map of the city","do you have a city map","have you got a map of the city","do you have a map of the town","do you have a town map"],"distratoresEn":["Do you have a photo of the city?","Do you have a drawing of the city?","Do you have a model of the city?","Do you have a brochure of the city?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"«La carte» means a map, a card and a menu. A street map of a city is also «le plan».","requerTodas":["fr-p002","fr-p131","fr-p028"],"v":"785c112f"},{"idioma":"fr","id":"fr-u204","tipo":"frase","requer":"fr-p131","fr":"La carte, s'il vous plaît.","en":"The menu, please.","aceitasEn":["the menu please","can i see the menu please","could we have the menu please","menu please","can we have the menu please"],"distratoresEn":["The salt, please.","The change, please.","The receipt, please.","The waiter, please."],"nivel":"A1","tags":["comida"],"notaEn":"In a restaurant, «la carte» is the menu; «le menu» is the set menu at a fixed price.","requerTodas":["fr-p131"],"v":"18ada5fc"},{"idioma":"fr","id":"fr-u205","tipo":"frase","requer":"fr-p183","fr":"J'aime voyager en avion.","en":"I like traveling by plane.","aceitasEn":["i like traveling by plane","i like to travel by plane","i love traveling by plane","i like travelling by plane","i like flying","i like to fly"],"distratoresEn":["I like traveling by train.","I like traveling by car.","I like traveling by bus.","I like traveling by boat."],"nivel":"A1","tags":["viagem"],"notaEn":"By plane is «en avion», like «en train», «en voiture». On foot and by bike take «à»: «à pied», «à vélo».","requerTodas":["fr-p015","fr-p183","+l'avion"],"v":"709e31ab"},{"idioma":"fr","id":"fr-u206","tipo":"frase","requer":"fr-p173","fr":"Elle porte une robe rouge.","en":"She's wearing a red dress.","aceitasEn":["shes wearing a red dress","she is wearing a red dress","she wears a red dress","shes got a red dress on","she has a red dress on"],"distratoresEn":["She's wearing a blue dress.","She's wearing a green dress.","She's wearing a black dress.","She's wearing a white dress."],"nivel":"A1","tags":["roupa"],"notaEn":"To wear is «porter»: «elle porte une robe rouge». Colors go after the noun and agree: «une robe verte»; «rouge» stays the same.","requerTodas":["+porter","fr-p142","fr-p173"],"v":"acbae44d"},{"idioma":"fr","id":"fr-u207","tipo":"frase","requer":"fr-p163","fr":"Bonnes vacances !","en":"Have a good vacation!","aceitasEn":["have a good vacation","have a nice vacation","enjoy your vacation","have a great vacation","have a good holiday","enjoy your holiday"],"distratoresEn":["Have a good trip!","Have a good rest!","Have a good weekend!","Have a good stay!"],"nivel":"A1","tags":["viagem","social"],"notaEn":"«Les vacances» is always plural, so the adjective is too: «bonnes vacances».","requerTodas":["fr-p036","fr-p163"],"v":"015d990b"},{"idioma":"fr","id":"fr-u208","tipo":"frase","requer":"fr-p163","fr":"Je suis en vacances.","en":"I'm on vacation.","aceitasEn":["im on vacation","i am on vacation","im on holiday","i am on holiday"],"distratoresEn":["I'm on call.","I'm grounded.","I'm on my way out.","I'm moving."],"nivel":"A1","tags":["viagem"],"notaEn":"To be on vacation is «être en vacances», with «en»; to go on vacation is «partir en vacances».","requerTodas":["fr-p001","fr-p163"],"v":"514737eb"},{"idioma":"fr","id":"fr-u209","tipo":"frase","requer":"fr-p154","fr":"Je veux faire le tour du monde.","en":"I want to go around the world.","aceitasEn":["i want to go around the world","i want to travel around the world","i want to travel the world","i want to go round the world"],"distratoresEn":["I want to go around the city.","I want to go around the island.","I want to go around the lake.","I want to go around the block."],"nivel":"A1","tags":["viagem"],"notaEn":"To go around is «faire le tour»: «faire le tour du monde», «faire le tour du quartier». «Le monde» is the world; «tout le monde», everyone.","requerTodas":["fr-p007","fr-p004","+le tour","fr-p154"],"v":"6a8ce132"},{"idioma":"fr","id":"fr-u210","tipo":"frase","requer":"fr-p084","fr":"Le musée est fermé le lundi.","en":"The museum is closed on Mondays.","aceitasEn":["the museum is closed on mondays","the museum closes on mondays","the museums closed on mondays","the museum is closed mondays"],"distratoresEn":["The museum is closed on Saturdays.","The museum is closed on Tuesdays.","The museum is closed on Sundays.","The museum is closed on Fridays."],"nivel":"A1","tags":["cultura","cidade"],"notaEn":"With «le», a weekday becomes a habit: «le lundi», on Mondays. French weekdays are masculine and lowercase.","requerTodas":["+le musée","fr-p001","+fermer","fr-p084"],"v":"f0c78023"},{"idioma":"fr","id":"fr-u211","tipo":"frase","requer":"fr-p144","fr":"Il fait la tête.","en":"He's sulking.","aceitasEn":["hes sulking","he is sulking","hes in a sulk","hes pouting","he is pouting"],"distratoresEn":["He has a migraine.","He's downcast.","He's thoughtful.","He's distracted."],"nivel":"A2","tags":["expressão","social"],"notaEn":"«Faire la tête» is to sulk, to give someone the silent treatment. It has nothing to do with a headache, which is «avoir mal à la tête».","requerTodas":["fr-p004","fr-p144"],"v":"f1b561f3"},{"idioma":"fr","id":"fr-u212","tipo":"frase","requer":"fr-p160","fr":"Hier soir, je suis sorti avec des amis.","aceitasFr":["Hier soir, je suis sortie avec des amis.","Je suis sorti avec des amis hier soir.","Je suis sortie avec des amis hier soir."],"en":"Last night I went out with some friends.","aceitasEn":["last night i went out with some friends","last night i went out with friends","i went out with some friends last night","i went out with friends last night","yesterday evening i went out with some friends"],"distratoresEn":["Yesterday morning I went out with some friends.","Yesterday afternoon I went out with some friends.","The day before yesterday I went out with some friends.","On Saturday night I went out with some friends."],"nivel":"A1","tags":["social","cotidiano"],"notaEn":"Last night is «hier soir», with no preposition; tomorrow morning, «demain matin». «Sortir» takes «être» in the passé composé.","requerTodas":["fr-p125","fr-p160","fr-p001","fr-p108","fr-p024"],"v":"bcbc56a4"},{"idioma":"fr","id":"fr-u213","tipo":"frase","requer":"fr-p153","fr":"Je pars demain matin.","en":"I'm leaving tomorrow morning.","aceitasEn":["im leaving tomorrow morning","i am leaving tomorrow morning","ill leave tomorrow morning","i leave tomorrow morning","im off tomorrow morning"],"distratoresEn":["I'm leaving tomorrow afternoon.","I'm leaving tomorrow night.","I'm leaving this morning.","I'm leaving Sunday morning."],"nivel":"A1","tags":["viagem","cotidiano"],"notaEn":"Tomorrow morning is «demain matin», with no preposition, like «hier soir». «Partir» is to leave.","requerTodas":["fr-p083","fr-p059","fr-p153"],"v":"83bb0a08"},{"idioma":"fr","id":"fr-u214","tipo":"frase","requer":"fr-p153","fr":"Le matin, je bois un jus d'orange.","aceitasFr":["Le matin, je prends un jus d'orange."],"en":"In the morning I have an orange juice.","aceitasEn":["in the morning i have an orange juice","in the morning i drink orange juice","i drink orange juice in the morning","i have orange juice in the morning","in the morning i have orange juice","in the mornings i drink orange juice","in the morning i drink an orange juice"],"distratoresEn":["In the afternoon I have an orange juice.","In the evening I have an orange juice.","At lunch I have an orange juice.","On Sundays I have an orange juice."],"nivel":"A1","tags":["comida","cotidiano"],"notaEn":"«Le matin», with the article, means in the morning, every morning. Orange juice is «jus d'orange», with «de» and no article.","requerTodas":["fr-p153","fr-p014","+le jus","+l'orange"],"v":"6af06ee0"},{"idioma":"fr","id":"fr-u215","tipo":"frase","requer":"fr-p030","fr":"Il fait déjà nuit.","en":"It's already dark.","aceitasEn":["its already dark","it is already dark","its dark already","it is already night","its already night","its already nighttime"],"distratoresEn":["It's already light.","It's already cold.","It's already late.","It's already hot."],"nivel":"A1","tags":["natureza","cotidiano"],"notaEn":"Darkness, like the weather, takes «faire»: «il fait nuit», it's dark; «il fait jour», it's light.","requerTodas":["fr-p004","fr-p050","fr-p030"],"v":"d3961b05"},{"idioma":"fr","id":"fr-u216","tipo":"frase","requer":"fr-p037","fr":"Vous avez une taille plus grande ?","aceitasFr":["Vous avez la taille au-dessus ?"],"en":"Do you have a bigger size?","aceitasEn":["do you have a bigger size","do you have this in a bigger size","do you have a larger size","have you got a bigger size"],"distratoresEn":["Do you have a smaller size?","Do you have a looser size?","Do you have a tighter size?","Do you have a shorter size?"],"nivel":"A1","tags":["compras","roupa"],"notaEn":"In a clothing store, «la taille» is the size; for shoes, it's «la pointure». Bigger is «plus grand», feminine here because of «taille»: «plus grande».","requerTodas":["fr-p002","+la taille","fr-p037"],"v":"f5f2370e"},{"idioma":"fr","id":"fr-u217","tipo":"frase","requer":"fr-p089","fr":"Le prochain train part à quelle heure ?","aceitasFr":["À quelle heure part le prochain train ?"],"en":"What time does the next train leave?","aceitasEn":["what time does the next train leave","when does the next train leave","at what time does the next train leave","what time is the next train"],"distratoresEn":["What time does the next bus leave?","What time does the next plane leave?","What time does the next subway leave?","What time does the next boat leave?"],"nivel":"A1","tags":["viagem"],"notaEn":"«Prochain», next, goes before the noun: «le prochain train». With days and weeks it goes after: «lundi prochain», «la semaine prochaine».","requerTodas":["+prochain","fr-p089","fr-p083","fr-p129"],"v":"d46f6228"},{"idioma":"fr","id":"fr-u218","tipo":"frase","requer":"fr-p003","fr":"Allez tout droit.","en":"Go straight ahead.","aceitasEn":["go straight ahead","go straight","keep going straight","go straight on","continue straight ahead"],"distratoresEn":["Turn right.","Turn left.","Go back.","Stop here."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Straight ahead is «tout droit». To the right is «à droite»: don't mix up «droit», straight, and «droite», right.","requerTodas":["fr-p003","+tout droit"],"v":"6e9d7f80"},{"idioma":"fr","id":"fr-u219","tipo":"frase","requer":"fr-p032","fr":"C'est la deuxième rue à gauche.","en":"It's the second street on the left.","aceitasEn":["its the second street on the left","its the second street to the left","second street on the left","its the second left"],"distratoresEn":["It's the second avenue on the left.","It's the second square on the left.","It's the second corner on the left.","It's the second exit on the left."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Left is «la gauche»: «à gauche». Ordinals add «-ième»: «deuxième», «troisième»; only first is different, «premier».","requerTodas":["fr-p001","+deuxième","fr-p032","+la gauche"],"v":"3affd42d"},{"idioma":"fr","id":"fr-u220","tipo":"frase","requer":"fr-p011","fr":"Je vais prendre un thé.","en":"I'll have a tea.","aceitasEn":["ill have a tea","ill have tea","ill have some tea","i will have a tea","i will have tea","im going to have a tea","ill take a tea"],"distratoresEn":["I'll have a juice.","I'll have a wine.","I'll have an ice cream.","I'll have a soda."],"nivel":"A1","tags":["comida"],"notaEn":"Ordering in a café or restaurant uses «prendre»: «je vais prendre un thé», I'll have a tea. The «h» of «thé» is silent.","requerTodas":["fr-p003","fr-p011","+le thé"],"v":"a6c51604"},{"idioma":"fr","id":"fr-u221","tipo":"frase","requer":"fr-p017","fr":"Je travaille de chez moi.","en":"I work from home.","aceitasEn":["i work from home","i work at home","im working from home","i am working from home"],"distratoresEn":["I work near home.","I work far from home.","I work away from home.","I work around the corner."],"nivel":"A1","tags":["trabalho","casa"],"notaEn":"At someone's place is «chez»: «chez moi», at my place; «chez Paul», at Paul's. Working from home is «travailler de chez soi».","requerTodas":["fr-p017"],"v":"c7607880"},{"idioma":"fr","id":"fr-u222","tipo":"frase","requer":"fr-p147","fr":"Chut, le bébé dort !","en":"Shh, the baby's sleeping!","aceitasEn":["shh the babys sleeping","shh the baby is sleeping","shh the babys asleep","shh the baby is asleep","quiet the baby is sleeping"],"distratoresEn":["Shh, Grandpa's sleeping!","Shh, Dad's sleeping!","Shh, the dog's sleeping!","Shh, the cat's sleeping!"],"nivel":"A1","tags":["família","casa"],"notaEn":"«Chut !» is French for shh. «Le bébé» is always masculine, even for a baby girl.","requerTodas":["+chut","fr-p147","fr-p109"],"v":"b877a619"},{"idioma":"fr","id":"fr-u223","tipo":"frase","requer":"fr-p180","fr":"Il est tard, je rentre.","en":"It's late, I'm going home.","aceitasEn":["its late im going home","it is late im going home","its late im heading home","its getting late im going home","its late ill go home","it is late i am going home"],"distratoresEn":["It's cold, I'm going home.","It's dark, I'm going home.","It's early, I'm going home.","It's crowded, I'm going home."],"nivel":"A1","tags":["casa","cotidiano"],"notaEn":"It's late is «il est tard», with «être», like telling the time. Late for something is «en retard».","requerTodas":["fr-p001","fr-p180","fr-p071"],"v":"7f7c29ec"},{"idioma":"fr","id":"fr-u224","tipo":"frase","requer":"fr-p181","fr":"Il est encore tôt.","en":"It's still early.","aceitasEn":["its still early","it is still early","its early still","its early yet"],"distratoresEn":["It's still daytime.","It's still night.","It's still Monday.","It's still summer."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Early is «tôt», with a silent final «t». «Encore» here means still; not yet is «pas encore».","requerTodas":["fr-p001","fr-p202","fr-p181"],"v":"fadea2e6"},{"idioma":"fr","id":"fr-u225","tipo":"frase","requer":"fr-p019","fr":"On est quel jour aujourd'hui ?","aceitasFr":["Quel jour sommes-nous ?","Quel jour sommes-nous aujourd'hui ?","On est quel jour ?","Quel jour on est aujourd'hui ?"],"en":"What day is today?","aceitasEn":["what day is today","what day is it today","what day is it"],"distratoresEn":["What game is today?","What class is today?","What test is today?","What holiday is today?"],"nivel":"A1","tags":["cotidiano"],"notaEn":"In speech it's «on est quel jour ?», literally we are which day; more formally, «quel jour sommes-nous ?».","requerTodas":["fr-p001","fr-p019","fr-p049"],"v":"8a0034e1"},{"idioma":"fr","id":"fr-u226","tipo":"frase","requer":"fr-p167","fr":"J'ai mis une heure pour venir.","en":"It took me an hour to get here.","aceitasEn":["it took me an hour to get here","it took me an hour to come","it took me one hour to get here","i took an hour to get here"],"distratoresEn":["I walked an hour to get here.","I drove an hour to get here.","I biked an hour to get here.","I ran an hour to get here."],"nivel":"A2","tags":["viagem","cotidiano"],"notaEn":"«Mettre» + a length of time means it took: «j'ai mis une heure», it took me an hour. The participle is irregular: «mis».","requerTodas":["fr-p002","fr-p167","fr-p129","fr-p009"],"v":"784bcac2"},{"idioma":"fr","id":"fr-u227","tipo":"frase","requer":"fr-p118","fr":"Je cherche une pharmacie.","en":"I'm looking for a pharmacy.","aceitasEn":["im looking for a pharmacy","i am looking for a pharmacy","im looking for a drugstore","i am looking for a drugstore","im looking for a chemist"],"distratoresEn":["I'm looking for a bakery.","I'm looking for a school.","I'm looking for a beach.","I'm looking for a church."],"nivel":"A1","tags":["saúde","cidade"],"notaEn":"French pharmacies have a green cross outside. To look for is «chercher», with no «for»; to find is «trouver».","requerTodas":["fr-p118","+la pharmacie"],"v":"c11084ef"},{"idioma":"fr","id":"fr-u228","tipo":"frase","requer":"fr-p048","fr":"Il y a une boulangerie près d'ici ?","aceitasFr":["Est-ce qu'il y a une boulangerie près d'ici ?","Y a-t-il une boulangerie près d'ici ?"],"en":"Is there a bakery near here?","aceitasEn":["is there a bakery near here","is there a bakery nearby","is there a bakery around here","is there a bakery close by"],"distratoresEn":["Is there a laundromat near here?","Is there a bookstore near here?","Is there a stationery store near here?","Is there an ice cream shop near here?"],"nivel":"A1","tags":["compras","cidade"],"notaEn":"«La boulangerie» is the bakery, where you buy «la baguette». Near is «près», and near here, «près d'ici».","requerTodas":["fr-p002","+la boulangerie","+près","fr-p048"],"v":"e9d7a08c"},{"idioma":"fr","id":"fr-u229","tipo":"frase","requer":"fr-p064","fr":"Il est midi.","en":"It's noon.","aceitasEn":["its noon","it is noon","its twelve oclock","its midday","it is twelve","its twelve noon"],"distratoresEn":["It's midnight.","It's one in the afternoon.","It's lunchtime.","It's half past twelve."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Noon is «midi», no article: «il est midi». Midnight is «minuit». «Le Midi», capitalized, is also the south of France.","requerTodas":["fr-p001","fr-p064"],"v":"fce93c00"},{"idioma":"fr","id":"fr-u230","tipo":"frase","requer":"fr-p164","fr":"La gare est loin d'ici ?","aceitasFr":["Est-ce que la gare est loin d'ici ?"],"en":"Is the station far from here?","aceitasEn":["is the station far from here","is the train station far from here","is the station far"],"distratoresEn":["Is the station near here?","Is the station on the right?","Is the station on the left?","Is the station down there?"],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"Far from is «loin de», and «de» shortens to «d'» before a vowel: «loin d'ici». Near is «près de».","requerTodas":["fr-p188","fr-p001","fr-p164","fr-p048"],"v":"d52073dd"},{"idioma":"fr","id":"fr-u231","tipo":"frase","requer":"fr-p164","fr":"Mes parents habitent loin.","en":"My parents live far away.","aceitasEn":["my parents live far away","my parents live far","my parents live far from here","my parents live a long way away"],"distratoresEn":["My parents live nearby.","My parents live together.","My parents live alone.","My parents live abroad."],"nivel":"A1","tags":["família","casa"],"notaEn":"«Les parents» are your parents — and also relatives in general. Far away is «loin»; far from, «loin de».","requerTodas":["+les parents","fr-p016","fr-p164"],"v":"78288072"},{"idioma":"fr","id":"fr-u232","tipo":"frase","requer":"fr-p044","fr":"Je ne me sens pas bien.","en":"I don't feel well.","aceitasEn":["i dont feel well","i do not feel well","im not feeling well","i am not feeling well","i dont feel good"],"distratoresEn":["I don't feel lonely.","I don't feel tired.","I don't feel better.","I don't feel comfortable."],"nivel":"A1","tags":["saúde"],"notaEn":"To feel is «se sentir»: «je me sens bien», I feel fine. Present: je me sens, tu te sens, il se sent.","requerTodas":["+se sentir","fr-p044"],"v":"7bf00c75"},{"idioma":"fr","id":"fr-u233","tipo":"frase","requer":"fr-p176","fr":"Ne te couche pas trop tard !","en":"Don't go to bed too late!","aceitasEn":["dont go to bed too late","do not go to bed too late","dont stay up too late"],"distratoresEn":["Don't have dinner too late!","Don't go out too late!","Don't get home too late!","Don't get up too late!"],"nivel":"A1","tags":["casa","gramática"],"notaEn":"In a negative command, the pronoun moves back before the verb: «couche-toi», go to bed, but «ne te couche pas», don't go to bed.","requerTodas":["fr-p176","fr-p061","fr-p180"],"v":"885c59aa"},{"idioma":"fr","id":"fr-u234","tipo":"frase","requer":"fr-p023","fr":"Ils ont deux enfants.","aceitasFr":["Elles ont deux enfants."],"en":"They have two children.","aceitasEn":["they have two children","they have two kids","theyve got two kids","they have got two children","they have 2 children","theyve got two children"],"distratoresEn":["They have two grandchildren.","They have two nephews.","They have two brothers.","They have two cousins."],"nivel":"A1","tags":["família"],"notaEn":"«L'enfant» means child, including someone's child: «ils ont deux enfants». A son is «le fils».","requerTodas":["fr-p002","fr-p120","fr-p023"],"v":"9e807bb0"},{"idioma":"fr","id":"fr-u235","tipo":"frase","requer":"fr-p152","fr":"Je te présente mon mari.","aceitasFr":["Je vous présente mon mari."],"en":"This is my husband.","aceitasEn":["this is my husband","let me introduce my husband","id like you to meet my husband","meet my husband","i want you to meet my husband"],"distratoresEn":["This is my brother.","This is my father.","This is my boss.","This is my neighbor."],"nivel":"A1","tags":["família","social"],"notaEn":"To introduce someone: «je te présente», or more formally «je vous présente». «Mon mari», my husband; «ma femme», my wife.","requerTodas":["+présenter","fr-p152"],"v":"0115de50"},{"idioma":"fr","id":"fr-u236","tipo":"frase","requer":"fr-p004","fr":"Qu'est-ce que vous faites dans la vie ?","aceitasFr":["Qu'est-ce que tu fais dans la vie ?","Que faites-vous dans la vie ?"],"en":"What do you do for a living?","aceitasEn":["what do you do for a living","what is your job","whats your job","what line of work are you in","what do you do for work"],"distratoresEn":["What do you do on weekends?","What do you do on vacation?","What do you do in the morning?","What do you do for dinner?"],"nivel":"A1","tags":["trabalho","social"],"notaEn":"The polite way to ask someone's job, literally what do you do in life. With «tu», «qu'est-ce que tu fais dans la vie ?».","requerTodas":["fr-p004","+la vie"],"v":"44ffacff"},{"idioma":"fr","id":"fr-u237","tipo":"frase","requer":"fr-p002","fr":"J'ai de la fièvre.","en":"I have a fever.","aceitasEn":["i have a fever","ive got a fever","i have got a fever","i have a temperature","ive got a temperature","im running a fever","i am running a fever"],"distratoresEn":["I have a cough.","I'm thirsty.","I'm sleepy.","I have the flu."],"nivel":"A1","tags":["saúde"],"notaEn":"French uses «avoir», to have, for many states: «j'ai de la fièvre», «j'ai faim», «j'ai soif». Fever takes the partitive, «de la».","requerTodas":["fr-p002","+la fièvre"],"v":"a1a9a53c"},{"idioma":"fr","id":"fr-u238","tipo":"frase","requer":"fr-p060","fr":"J'ai raté le bus.","aceitasFr":["J'ai manqué le bus."],"en":"I missed the bus.","aceitasEn":["i missed the bus","ive missed the bus","i have missed the bus"],"distratoresEn":["I missed the train.","I missed the subway.","I missed the plane.","I missed the boat."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"To miss the bus is «rater le bus» (or «manquer le bus»); «perdre» is to lose something: «j'ai perdu mes clés».","requerTodas":["fr-p002","+rater","fr-p060"],"v":"02d7ac6f"},{"idioma":"fr","id":"fr-u239","tipo":"frase","requer":"fr-p101","fr":"Un ticket de métro, s'il vous plaît.","en":"A subway ticket, please.","aceitasEn":["a subway ticket please","one subway ticket please","a metro ticket please","a ticket for the subway please","one metro ticket please","an underground ticket please","a tube ticket please"],"distratoresEn":["A bus ticket, please.","A train ticket, please.","A movie ticket, please.","A museum ticket, please."],"nivel":"A1","tags":["viagem","cidade"],"notaEn":"A subway or bus ticket is «le ticket»; a train, plane or concert ticket is «le billet».","requerTodas":["+le ticket","fr-p101"],"v":"3a2987a2"},{"idioma":"fr","id":"fr-u240","tipo":"frase","requer":"fr-p001","fr":"Je suis en avance.","en":"I'm early.","aceitasEn":["im early","i am early","im ahead of time","i got here early"],"distratoresEn":["I'm late.","I'm busy.","I'm ready.","I'm alone."],"nivel":"A1","tags":["cotidiano"],"notaEn":"Early, ahead of time, is «en avance»; late, «en retard»; on time, «à l'heure».","requerTodas":["fr-p001","+l'avance"],"v":"af4487f3"},{"idioma":"fr","id":"fr-u241","tipo":"frase","requer":"fr-p049","fr":"Il y a du vent aujourd'hui.","aceitasFr":["Aujourd'hui, il y a du vent."],"en":"It's windy today.","aceitasEn":["its windy today","it is windy today","today its windy","its windy"],"distratoresEn":["It's rainy today.","It's cloudy today.","It's snowy today.","It's muggy today."],"nivel":"A1","tags":["natureza"],"notaEn":"Wind and sun take «il y a»: «il y a du vent», «il y a du soleil». Cold and heat take «il fait».","requerTodas":["fr-p002","+le vent","fr-p049"],"v":"993207ed"},{"idioma":"fr","id":"fr-u242","tipo":"frase","requer":"fr-p179","fr":"Mon fils a six ans.","en":"My son is six.","aceitasEn":["my son is six","my son is six years old","my son is 6","my son is 6 years old","my sons six"],"distratoresEn":["My son is seven.","My son is eight.","My son is ten.","My son is three."],"nivel":"A1","tags":["família"],"notaEn":"Age is something you have: «il a six ans», and «ans» can't be dropped. In «fils» the «l» is silent and the «s» is pronounced: «feess».","requerTodas":["+le fils","fr-p002","fr-p179","fr-p052"],"v":"b4a2907b"},{"idioma":"fr","id":"fr-u243","tipo":"frase","requer":"fr-p169","fr":"Ouvrez vos livres à la page dix.","en":"Open your books to page ten.","aceitasEn":["open your books to page ten","open your books at page ten","open your books on page ten","open your books to page 10"],"distratoresEn":["Open your books to page six.","Open your books to page eight.","Open your books to page seven.","Open your books to page three."],"nivel":"A1","tags":["escola"],"notaEn":"On page ten is «à la page dix». The «vous» imperative is just the present without the pronoun: «vous ouvrez», «ouvrez».","requerTodas":["fr-p169","fr-p033","+la page","fr-p121"],"v":"e6bee809"},{"idioma":"fr","id":"fr-u244","tipo":"frase","requer":"fr-p001","fr":"Où est la caisse ?","en":"Where's the checkout?","aceitasEn":["wheres the checkout","where is the checkout","where is the register","wheres the cash register","where do i pay","where is the cash desk"],"distratoresEn":["Where's the elevator?","Where's the fitting room?","Where's the parking lot?","Where's the exit?"],"nivel":"A1","tags":["compras"],"notaEn":"In a store, «la caisse» is the checkout; the person working it is «le caissier» or «la caissière».","requerTodas":["fr-p001","+la caisse"],"v":"8ea1f8e0"},{"idioma":"fr","id":"fr-u245","tipo":"frase","requer":"fr-p007","fr":"Je voudrais un kilo de tomates.","en":"I'd like a kilo of tomatoes.","aceitasEn":["id like a kilo of tomatoes","i would like a kilo of tomatoes","can i have a kilo of tomatoes","a kilo of tomatoes please","id like one kilo of tomatoes"],"distratoresEn":["I'd like a kilo of onions.","I'd like a kilo of carrots.","I'd like a kilo of oranges.","I'd like a kilo of apples."],"nivel":"A1","tags":["compras","comida"],"notaEn":"At a market, you order with the conditional of «vouloir»: «je voudrais». After a quantity, just «de», no article: «un kilo de tomates».","requerTodas":["fr-p007","+le kilo","+la tomate"],"v":"964b2259"},{"idioma":"fr","id":"fr-u246","tipo":"frase","requer":"fr-p001","fr":"Je suis en réunion.","en":"I'm in a meeting.","aceitasEn":["im in a meeting","i am in a meeting"],"distratoresEn":["I'm in class.","I'm on a trip.","I'm on strike.","I'm at the doctor's."],"nivel":"A1","tags":["trabalho"],"notaEn":"«La réunion» is a meeting. Being busy with something is «être en»: «en réunion», «en vacances», «en cours».","requerTodas":["fr-p001","+la réunion"],"v":"a7c7f7fc"},{"idioma":"fr","id":"fr-u247","tipo":"frase","requer":"fr-p104","fr":"Ma sœur est mariée.","en":"My sister is married.","aceitasEn":["my sister is married","my sisters married"],"distratoresEn":["My cousin is married.","My aunt is married.","My daughter is married.","My neighbor is married."],"nivel":"A1","tags":["família"],"notaEn":"«Marié» agrees: «il est marié», «elle est mariée». To get married is «se marier», to someone «se marier avec».","requerTodas":["fr-p104","fr-p001","+marié"],"v":"55fbe828"},{"idioma":"fr","id":"fr-u248","tipo":"frase","requer":"fr-p124","fr":"Mon chef est très gentil.","en":"My boss is very nice.","aceitasEn":["my boss is very nice","my boss is really nice","my boss is very kind","my boss is really kind"],"distratoresEn":["My boss is very demanding.","My boss is very serious.","My boss is very annoying.","My boss is very young."],"nivel":"A1","tags":["trabalho"],"notaEn":"«Gentil» means nice or kind, not gentle. «Le chef» is the boss — and also the head chef.","requerTodas":["+le chef","fr-p001","fr-p043","fr-p124"],"v":"6e06fea0"},{"idioma":"fr","id":"fr-u249","tipo":"frase","requer":"fr-p059","fr":"J'ai un examen demain.","en":"I have a test tomorrow.","aceitasEn":["i have a test tomorrow","i have an exam tomorrow","ive got a test tomorrow","ive got an exam tomorrow","i have got an exam tomorrow"],"distratoresEn":["I have a test today.","I have a test on Friday.","I have a test the day after tomorrow.","I have a test next week."],"nivel":"A1","tags":["escola"],"notaEn":"A test is «l'examen» or, a smaller one, «le contrôle». «Passer un examen» just means to take it; to pass is «réussir».","requerTodas":["fr-p002","+l'examen","fr-p059"],"v":"a28e3d9f"},{"idioma":"fr","id":"fr-u250","tipo":"frase","requer":"fr-p082","fr":"Je dois prendre ce médicament.","en":"I have to take this medicine.","aceitasEn":["i have to take this medicine","i have to take this medication","i need to take this medicine","i must take this medicine","ive got to take this medicine"],"distratoresEn":["I can take this medicine.","I want to take this medicine.","I'm going to take this medicine.","I'd rather take this medicine."],"nivel":"A1","tags":["saúde"],"notaEn":"Medicine is «le médicament»; taking it is «prendre». «Devoir» + infinitive means to have to.","requerTodas":["fr-p082","fr-p011","+le médicament"],"v":"03211d31"},{"idioma":"fr","id":"fr-u251","tipo":"frase","requer":"fr-p011","fr":"On prend l'ascenseur ?","en":"Shall we take the elevator?","aceitasEn":["shall we take the elevator","should we take the elevator","lets take the elevator","shall we take the lift","do we take the elevator"],"distratoresEn":["Shall we take the subway?","Shall we take the bus?","Shall we take the taxi?","Shall we take the train?"],"nivel":"A1","tags":["cidade","casa"],"notaEn":"Taking the elevator, the bus or the subway is always «prendre». The stairs are «l'escalier».","requerTodas":["fr-p011","+l'ascenseur"],"v":"8181bbb9"},{"idioma":"fr","id":"fr-u252","tipo":"frase","requer":"fr-p040","fr":"Il fait beau, on va au parc ?","en":"The weather's nice, shall we go to the park?","aceitasEn":["the weathers nice shall we go to the park","its nice out shall we go to the park","the weather is nice shall we go to the park","its a nice day shall we go to the park","its nice outside lets go to the park"],"distratoresEn":["The weather's cool, shall we go to the park?","The weather's cloudy, shall we go to the park?","The weather's hot, shall we go to the park?","The weather's cold, shall we go to the park?"],"nivel":"A1","tags":["natureza","cidade"],"notaEn":"«Il fait beau» is nice weather; bad weather is «il fait mauvais». «On va au parc ?», with «on», is the casual shall we.","requerTodas":["fr-p004","fr-p040","fr-p003","+le parc"],"v":"3f65261d"},{"idioma":"fr","id":"fr-v055","tipo":"frase","fr":"Elle est arrivée en retard.","en":"She arrived late.","aceitasEn":["she arrived late","she got here late","she came late","she showed up late","she got there late"],"distratoresEn":["She arrives late.","She used to arrive late.","She'll arrive late.","She would arrive late."],"formasFr":{"Elle arrive en retard":"present","Elle arrivait en retard":"imperfect","Elle arrivera en retard":"future","Elle arriverait en retard":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","viagem"],"notaEn":"«Arriver» takes «être» in the passé composé, and the participle agrees with the subject: «il est arrivé», «elle est arrivée», «ils sont arrivés».","requerTodas":["fr-p001","fr-p115","fr-p085"],"v":"73d8547f"},{"idioma":"fr","id":"fr-v056","tipo":"frase","fr":"Elle est née en France.","en":"She was born in France.","aceitasEn":["she was born in france"],"distratoresEn":["She's born in France.","She was being born in France.","She'll be born in France.","She would be born in France."],"formasFr":{"Elle naît en France":"present","Elle naissait en France":"imperfect","Elle naîtra en France":"future","Elle naîtrait en France":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","irregular","família"],"notaEn":"To be born is the single verb «naître», which takes «être» in the passé composé: «je suis né», «elle est née». Years take «en»: «née en 1990».","requerTodas":["fr-p001","+naître"],"v":"3421fc51"},{"idioma":"fr","id":"fr-v057","tipo":"frase","fr":"Elles sont restées à la maison.","en":"They stayed home.","aceitasEn":["they stayed home","they stayed at home","theyve stayed home","they have stayed at home"],"distratoresEn":["They stay home.","They used to stay home.","They'll stay home.","They'd stay home."],"formasFr":{"Elles restent à la maison":"present","Elles restaient à la maison":"imperfect","Elles resteront à la maison":"future","Elles resteraient à la maison":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","casa"],"notaEn":"«Rester» means to stay, not to rest. It takes «être», so with «elles» the participle adds «-es»: «elles sont restées».","requerTodas":["fr-p001","+rester","fr-p020"],"v":"068be0f4"},{"idioma":"fr","id":"fr-v058","tipo":"frase","fr":"Elle était très fatiguée.","en":"She was very tired.","aceitasEn":["she was very tired","she was really tired"],"distratoresEn":["She's very tired.","She'll be very tired.","She'd be very tired.","She had been very tired."],"formasFr":{"Elle est très fatiguée":"present","Elle sera très fatiguée":"future","Elle serait très fatiguée":"conditional","Elle avait été très fatiguée":"pluperfect"},"nivel":"A1","tags":["conjugação","imperfeito","irregular","saúde"],"notaEn":"Imperfect of «être»: j'étais, tu étais, il était, nous étions, vous étiez, ils étaient. Only the stem «ét-» is irregular; the endings are the usual ones.","requerTodas":["fr-p001","fr-p043","fr-p113"],"v":"39462994"},{"idioma":"fr","id":"fr-v059","tipo":"frase","fr":"Il y avait beaucoup de monde à la plage.","en":"There were a lot of people at the beach.","aceitasEn":["there were a lot of people at the beach","there were lots of people at the beach","there were many people at the beach","there were a lot of people on the beach"],"distratoresEn":["There are a lot of people at the beach.","There will be a lot of people at the beach.","There would be a lot of people at the beach.","There had been a lot of people at the beach."],"formasFr":{"Il y a beaucoup de monde à la plage":"present","Il y aura beaucoup de monde à la plage":"future","Il y aurait beaucoup de monde à la plage":"conditional","Il y avait eu beaucoup de monde à la plage":"pluperfect"},"nivel":"A2","tags":["conjugação","imperfeito","irregular","viagem"],"notaEn":"«Il y a» in the imperfect is «il y avait», there was, there were. People, in this sense, is «du monde»: «beaucoup de monde».","requerTodas":["fr-p002","fr-p067","fr-p154","fr-p087"],"v":"7e1e01b6"},{"idioma":"fr","id":"fr-v060","tipo":"frase","fr":"Ça ne va pas marcher.","aceitasFr":["Ça va pas marcher."],"en":"That won't work.","aceitasEn":["that wont work","that will not work","thats not going to work","that is not going to work","thats not gonna work","that isnt going to work","its not going to work","it wont work"],"distratoresEn":["That doesn't work.","That wasn't working.","That didn't work.","That wouldn't work."],"formasFr":{"Ça ne marche pas":"present","Ça ne marchait pas":"imperfect","Ça n'a pas marché":"passé composé","Ça ne marcherait pas":"conditional"},"nivel":"A2","tags":["conjugação","futuro","regular"],"notaEn":"In the negative near future, «ne… pas» wraps «aller»: «ça ne va pas marcher». «Marcher» means to walk and also to work, to function.","requerTodas":["fr-p003","+marcher"],"v":"a96296b5"},{"idioma":"fr","id":"fr-v061","tipo":"frase","fr":"Qu'est-ce que tu cherches ?","aceitasFr":["Tu cherches quoi ?"],"en":"What are you looking for?","aceitasEn":["what are you looking for","what are you searching for"],"distratoresEn":["What were you looking for?","What did you look for?","What will you look for?","What would you look for?"],"formasFr":{"Qu'est-ce que tu cherchais":"imperfect","Qu'est-ce que tu as cherché":"passé composé","Qu'est-ce que tu chercheras":"future","Qu'est-ce que tu chercherais":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular"],"notaEn":"Present of «chercher», a regular -er verb: je cherche, tu cherches, il cherche, nous cherchons, vous cherchez, ils cherchent. The «-es» of «tu cherches» is silent.","requerTodas":["fr-p118"],"v":"cd6c7683"},{"idioma":"fr","id":"fr-v062","tipo":"frase","fr":"Je connaissais bien cette ville.","en":"I knew this city well.","aceitasEn":["i knew this city well","i used to know this city well","i knew that city well","i used to know that city well"],"distratoresEn":["I know this city well.","I'll know this city well.","I'd know this city well.","I had known this city well."],"formasFr":{"Je connais bien cette ville":"present","Je connaîtrai bien cette ville":"future","Je connaîtrais bien cette ville":"conditional","J'avais bien connu cette ville":"pluperfect"},"nivel":"A2","tags":["conjugação","imperfeito","irregular","cidade"],"notaEn":"The imperfect comes from the «nous» form of the present: «nous connaissons» gives «je connaissais». The «ss» shows up in the whole plural and the imperfect.","requerTodas":["fr-p119","fr-p044","fr-p028"],"v":"230386fa"},{"idioma":"fr","id":"fr-v063","tipo":"frase","fr":"J'ai fini mes devoirs.","en":"I finished my homework.","aceitasEn":["i finished my homework","ive finished my homework","i have finished my homework","im done with my homework","i am done with my homework"],"distratoresEn":["I'm finishing my homework.","I was finishing my homework.","I'll finish my homework.","I would finish my homework."],"formasFr":{"Je finis mes devoirs":"present","Je finissais mes devoirs":"imperfect","Je finirai mes devoirs":"future","Je finirais mes devoirs":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","escola"],"notaEn":"«Fini» and «finis» sound the same; the «ai» is what separates «j'ai fini» from «je finis». «Les devoirs» is homework.","requerTodas":["fr-p002","fr-p123","+les devoirs"],"v":"0de4ae32"},{"idioma":"fr","id":"fr-v064","tipo":"frase","fr":"Ils mettent la table.","aceitasFr":["Elles mettent la table."],"en":"They're setting the table.","aceitasEn":["theyre setting the table","they are setting the table"],"distratoresEn":["They used to set the table.","They've set the table.","They'll set the table.","They would set the table."],"formasFr":{"Ils mettaient la table":"imperfect","Ils ont mis la table":"passé composé","Ils mettront la table":"future","Ils mettraient la table":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","casa"],"notaEn":"Present of «mettre»: je mets, tu mets, il met, nous mettons, vous mettez, ils mettent. One «t» in the singular, two in the plural.","requerTodas":["fr-p167","fr-p143"],"v":"78d77dc8"},{"idioma":"fr","id":"fr-v065","tipo":"frase","fr":"On ouvre les cadeaux ?","en":"Shall we open the presents?","aceitasEn":["shall we open the presents","should we open the presents","shall we open the gifts","lets open the presents","should we open the gifts"],"distratoresEn":["Did we use to open the presents?","Did we open the presents?","Would we open the presents?","Had we opened the presents?"],"formasFr":{"On ouvrait les cadeaux":"imperfect","On a ouvert les cadeaux":"passé composé","On ouvrirait les cadeaux":"conditional","On avait ouvert les cadeaux":"pluperfect"},"nivel":"A1","tags":["conjugação","presente","irregular","família"],"notaEn":"In the present, «ouvrir» is conjugated like an -er verb: «on ouvre», «j'ouvre»; the participle is irregular, «ouvert». With «on» and a rising tone, it's a suggestion.","requerTodas":["fr-p169","+le cadeau"],"v":"186757e0"},{"idioma":"fr","id":"fr-v066","tipo":"frase","fr":"J'ai payé cent euros.","en":"I paid a hundred euros.","aceitasEn":["i paid a hundred euros","i paid one hundred euros","ive paid a hundred euros","i paid 100 euros"],"distratoresEn":["I pay a hundred euros.","I used to pay a hundred euros.","I'll pay a hundred euros.","I would pay a hundred euros."],"formasFr":{"Je paie cent euros":"present","Je payais cent euros":"imperfect","Je paierai cent euros":"future","Je paierais cent euros":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","compras"],"notaEn":"In «payer», the «y» may become «i» before a silent «e»: «je paie» or «je paye», «je paierai». The passé composé keeps it: «j'ai payé».","requerTodas":["fr-p002","fr-p170","+cent","fr-p128"],"v":"8ef82801"},{"idioma":"fr","id":"fr-v067","tipo":"frase","fr":"On regardait un film.","en":"We were watching a movie.","aceitasEn":["we were watching a movie","we were watching a film"],"distratoresEn":["We watch a movie.","We watched a movie.","We'll watch a movie.","We had watched a movie."],"formasFr":{"On regarde un film":"present","On a regardé un film":"passé composé","On regardera un film":"future","On avait regardé un film":"pluperfect"},"nivel":"A1","tags":["conjugação","imperfeito","regular","cultura"],"notaEn":"The imperfect describes something in progress: «on regardait un film». The endings are the same for every verb: -ais, -ais, -ait, -ions, -iez, -aient.","requerTodas":["fr-p172","fr-p100"],"v":"e31e1529"},{"idioma":"fr","id":"fr-v068","tipo":"frase","fr":"Mes parents m'écrivent souvent.","en":"My parents often write to me.","aceitasEn":["my parents often write to me","my parents write to me often","my parents write me often","my parents often write me"],"distratoresEn":["My parents used to write to me often.","My parents wrote to me often.","My parents will often write to me.","My parents would often write to me."],"formasFr":{"Mes parents m'écrivaient souvent":"imperfect","Mes parents m'ont souvent écrit":"passé composé","Mes parents m'écriront souvent":"future","Mes parents m'écriraient souvent":"conditional"},"nivel":"A1","tags":["conjugação","presente","irregular","família"],"notaEn":"In the plural, «écrire» picks up a «v»: nous écrivons, vous écrivez, ils écrivent. Not in the singular: j'écris, tu écris, il écrit.","requerTodas":["+les parents","fr-p184","fr-p114"],"v":"f7913eb0"},{"idioma":"fr","id":"fr-v069","tipo":"frase","fr":"Ils ont vendu leur maison.","aceitasFr":["Elles ont vendu leur maison."],"en":"They sold their house.","aceitasEn":["they sold their house","theyve sold their house","they have sold their house"],"distratoresEn":["They're selling their house.","They were selling their house.","They'll sell their house.","They would sell their house."],"formasFr":{"Ils vendent leur maison":"present","Ils vendaient leur maison":"imperfect","Ils vendront leur maison":"future","Ils vendraient leur maison":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","casa"],"notaEn":"Verbs in -re like «vendre» form the participle in «-u»: «vendu», «attendu», «perdu». «Leur», their, has no «s» when there's only one thing.","requerTodas":["fr-p002","fr-p182","fr-p020"],"v":"7863eadd"},{"idioma":"fr","id":"fr-v070","tipo":"frase","fr":"Elle voyage beaucoup pour son travail.","en":"She travels a lot for work.","aceitasEn":["she travels a lot for work","she travels a lot for her job","she travels a lot for her work","she does a lot of traveling for work"],"distratoresEn":["She used to travel a lot for work.","She traveled a lot for work.","She'll travel a lot for work.","She would travel a lot for work."],"formasFr":{"Elle voyageait beaucoup pour son travail":"imperfect","Elle a beaucoup voyagé pour son travail":"passé composé","Elle voyagera beaucoup pour son travail":"future","Elle voyagerait beaucoup pour son travail":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","trabalho","viagem"],"notaEn":"Verbs in «-ger» keep the «e» before «a» and «o» so the «g» stays soft: «nous voyageons», «elle voyageait». In the passé composé, «beaucoup» goes between the helper and the participle: «elle a beaucoup voyagé».","requerTodas":["fr-p183","fr-p067","fr-p029"],"v":"78fa795c"},{"idioma":"fr","id":"fr-v071","tipo":"frase","fr":"Elle s'est levée tard.","en":"She got up late.","aceitasEn":["she got up late","she got out of bed late"],"distratoresEn":["She gets up late.","She used to get up late.","She'll get up late.","She would get up late."],"formasFr":{"Elle se lève tard":"present","Elle se levait tard":"imperfect","Elle se lèvera tard":"future","Elle se lèverait tard":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","pronomes","casa"],"notaEn":"Reflexive verbs take «être» in the passé composé, and the participle agrees: «il s'est levé», «elle s'est levée». Watch the accent: «je me lève», «je me lèverai».","requerTodas":["fr-p001","fr-p177","fr-p180"],"v":"4b0fba2e"},{"idioma":"fr","id":"fr-v072","tipo":"frase","fr":"Je vais me coucher.","en":"I'm going to bed.","aceitasEn":["im going to bed","i am going to bed","im going to go to bed","im off to bed","im heading to bed"],"distratoresEn":["I was going to bed.","I went to bed.","I would go to bed.","I had gone to bed."],"formasFr":{"Je me couchais":"imperfect","Je me suis couché":"passé composé","Je me coucherais":"conditional","Je m'étais couché":"pluperfect"},"nivel":"A1","tags":["conjugação","futuro","regular","pronomes","casa"],"notaEn":"In the near future, the reflexive pronoun sits right before the infinitive: «je vais me coucher», «tu vas te coucher». Negative: «je ne vais pas me coucher».","requerTodas":["fr-p003","fr-p176"],"v":"cfc9e8fc"},{"idioma":"fr","id":"fr-v073","tipo":"frase","fr":"Il a plu toute la nuit.","en":"It rained all night.","aceitasEn":["it rained all night","it rained the whole night","its rained all night","it has rained all night","it rained all night long"],"distratoresEn":["It rains all night.","It'll rain all night.","It would rain all night.","It had rained all night."],"formasFr":{"Il pleut toute la nuit":"present","Il pleuvra toute la nuit":"future","Il pleuvrait toute la nuit":"conditional","Il avait plu toute la nuit":"pluperfect"},"nivel":"A2","tags":["conjugação","pretérito","irregular","natureza"],"notaEn":"The participle of «pleuvoir» is «plu»: «il a plu». All night is «toute la nuit», with «tout» in the feminine.","requerTodas":["fr-p002","fr-p171","fr-p070","fr-p030"],"v":"9c7e8dfc"},{"idioma":"fr","id":"fr-v074","tipo":"frase","fr":"Il faudra partir tôt.","en":"We'll have to leave early.","aceitasEn":["well have to leave early","we will have to leave early","well need to leave early","we will need to leave early","were going to have to leave early","we are going to have to leave early"],"distratoresEn":["We have to leave early.","We had to leave early.","We'd have to leave early.","We had had to leave early."],"formasFr":{"Il faut partir tôt":"present","Il a fallu partir tôt":"passé composé","Il faudrait partir tôt":"conditional","Il avait fallu partir tôt":"pluperfect"},"nivel":"A2","tags":["conjugação","futuro","irregular","viagem"],"notaEn":"«Falloir» only exists with «il»: «il faut», «il fallait», «il a fallu», «il faudra», «il faudrait». The future stem is «faudr-».","requerTodas":["fr-p122","fr-p083","fr-p181"],"v":"1cb9702d"},{"idioma":"fr","id":"fr-v075","tipo":"frase","fr":"J'ai trouvé un bon restaurant.","en":"I found a good restaurant.","aceitasEn":["i found a good restaurant","ive found a good restaurant","i have found a good restaurant"],"distratoresEn":["I find a good restaurant.","I'll find a good restaurant.","I'd find a good restaurant.","I had found a good restaurant."],"formasFr":{"Je trouve un bon restaurant":"present","Je trouverai un bon restaurant":"future","Je trouverais un bon restaurant":"conditional","J'avais trouvé un bon restaurant":"pluperfect"},"nivel":"A1","tags":["conjugação","pretérito","regular","comida"],"notaEn":"«Bon» goes before the noun: «un bon restaurant». To find is «trouver»; to look for, «chercher»: «j'ai cherché et j'ai trouvé».","requerTodas":["fr-p002","fr-p193","fr-p036","fr-p098"],"v":"75536948"},{"idioma":"fr","id":"fr-v076","tipo":"frase","fr":"Elle donne des cours de piano.","en":"She gives piano lessons.","aceitasEn":["she gives piano lessons","she teaches piano","she gives piano classes"],"distratoresEn":["She used to give piano lessons.","She gave piano lessons.","She'll give piano lessons.","She would give piano lessons."],"formasFr":{"Elle donnait des cours de piano":"imperfect","Elle a donné des cours de piano":"passé composé","Elle donnera des cours de piano":"future","Elle donnerait des cours de piano":"conditional"},"nivel":"A1","tags":["conjugação","presente","regular","escola","cultura"],"notaEn":"To teach classes is «donner des cours»; to have class, «avoir cours». Present of «donner», regular: je donne, tu donnes, il donne, nous donnons, ils donnent.","requerTodas":["fr-p195","fr-p148","fr-p157"],"v":"b5d94fb9"},{"idioma":"fr","id":"fr-v077","tipo":"frase","fr":"Je n'oublierai jamais ce jour.","en":"I'll never forget this day.","aceitasEn":["ill never forget this day","i will never forget this day","ill never forget that day","i will never forget that day"],"distratoresEn":["I never forget this day.","I never used to forget this day.","I've never forgotten this day.","I'd never forget this day."],"formasFr":{"Je n'oublie jamais ce jour":"present","Je n'oubliais jamais ce jour":"imperfect","Je n'ai jamais oublié ce jour":"passé composé","Je n'oublierais jamais ce jour":"conditional"},"nivel":"A2","tags":["conjugação","futuro","regular"],"notaEn":"In the future, -er verbs keep the whole infinitive: «oublier» gives «j'oublierai». «Ne… jamais» means never.","requerTodas":["fr-p197","fr-p019"],"v":"ca0e5e83"},{"idioma":"fr","id":"fr-v078","tipo":"frase","fr":"Qu'est-ce que tu en penses ?","aceitasFr":["Tu en penses quoi ?"],"en":"What do you think of it?","aceitasEn":["what do you think of it","what do you think","what do you think about it","what do you think of that","what do you think about that"],"distratoresEn":["What did you think of it?","What will you think of it?","What would you think of it?","What had you thought of it?"],"formasFr":{"Qu'est-ce que tu en as pensé":"passé composé","Qu'est-ce que tu en penseras":"future","Qu'est-ce que tu en penserais":"conditional","Qu'est-ce que tu en avais pensé":"pluperfect"},"nivel":"A1","tags":["conjugação","presente","regular","social"],"notaEn":"Having an opinion of something is «penser de», and «en» stands for «of it»: «qu'est-ce que tu en penses ?». Thinking about is different: «penser à».","requerTodas":["fr-p198"],"v":"f9fcf333"},{"idioma":"fr","id":"fr-v079","tipo":"frase","fr":"Je lui ai demandé l'heure.","en":"I asked him the time.","aceitasEn":["i asked him the time","i asked her the time","i asked him what time it was","i asked her what time it was","ive asked him the time"],"distratoresEn":["I ask him the time.","I used to ask him the time.","I'll ask him the time.","I would ask him the time."],"formasFr":{"Je lui demande l'heure":"present","Je lui demandais l'heure":"imperfect","Je lui demanderai l'heure":"future","Je lui demanderais l'heure":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular"],"notaEn":"«Lui» means to him or to her: «je lui ai demandé», I asked him or her. Asking the time is «demander l'heure».","requerTodas":["fr-p002","fr-p194","fr-p129"],"v":"1abd152c"},{"idioma":"fr","id":"fr-v080","tipo":"frase","fr":"J'ai commencé un nouveau travail.","en":"I started a new job.","aceitasEn":["i started a new job","ive started a new job","i have started a new job","i began a new job"],"distratoresEn":["I'm starting a new job.","I was starting a new job.","I'll start a new job.","I would start a new job."],"formasFr":{"Je commence un nouveau travail":"present","Je commençais un nouveau travail":"imperfect","Je commencerai un nouveau travail":"future","Je commencerais un nouveau travail":"conditional"},"nivel":"A1","tags":["conjugação","pretérito","regular","trabalho"],"notaEn":"In the imperfect, «commencer» takes a cedilla: «je commençais». The passé composé doesn't need one: «j'ai commencé». «Nouveau» goes before the noun.","requerTodas":["fr-p002","fr-p196","fr-p039","fr-p029"],"v":"5d5d7b0e"},{"idioma":"fr","id":"fr-v081","tipo":"frase","fr":"J'avais froid.","en":"I felt cold.","aceitasEn":["i felt cold","i was feeling cold"],"distratoresEn":["I feel cold.","I'll feel cold.","I'd feel cold.","I had felt cold."],"formasFr":{"J'ai froid":"present","J'aurai froid":"future","J'aurais froid":"conditional","J'avais eu froid":"pluperfect"},"nivel":"A1","tags":["conjugação","imperfeito","irregular","natureza","corpo"],"notaEn":"Cold is something you have: «j'ai froid», I'm cold; «j'avais froid», I was cold, I felt cold. Imperfect of «avoir»: j'avais, tu avais, il avait, nous avions, vous aviez, ils avaient.","requerTodas":["fr-p002","fr-p080"],"v":"69975706"}]};
